(window.GIM_TS=window.GIM_TS||{})["Rosh Hashanah.2"]={"from":48,"a":[["\u0003מקצתן נעשו עדים\u0004 ויעידו בפני האחרים \u0003ומקצתן נעשו דיינין\u0004 לדון באותו דין, אלו \u0003דברי ר' טרפון, ר' עקיבא אומר: כולן נעשין עדים, ואין עד נעשה דיין.\u0004 ולכאורה, מה שנאמר במשנתנו נוגד את דברי ר' עקיבא!","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שמשנתנו היא כשיטת \u0003ר' עקיבא,\u0004 אולם יש לחלק ולומר, ש\u0003עד כאן לא\u0004 שמענו \u0003קאמר\u0004 \u0005[\u0006ש\u0005אמר]\u0006 \u0003ר' עקיבא התם\u0004 \u0005[שם]\u0006 \u0003אלא בדיני נפשות, דרחמנא אמר\u0004 \u0005[שהתורה אמרה]:\u0006 \u0003\"ושפטו העדה\" \"והצילו העדה\"\u0004 (במדבר לה, כד-כה) שאחת מחובות בית דין היא להפוך בזכותו של הנאשם, \u0003וכיון דחזיוהו דקטל נפשא לא מצו חזו ליה זכותא\u0004 \u0005[וכיון שראו אותו\u0006 בעיניהם \u0005שהרג נפש\u0006 שוב \u0005אינם יכולים לראות לו זכות],\u0006 \u0003אבל הכא\u0004 \u0005[כאן]\u0006 בראיית מולד הירח, שאין חובה להגיע להחלטה באופן זה או אחר — בזה \u0003אפילו ר' עקיבא מודה,\u0004 שמי שהיה עד בדבר רשאי להיות דיין.","מעתה דנים במצות היום של תקיעת שופר. \u0003כל השופרות כשרים\u0004 לתקיעה \u0003חוץ מ\u0004קרן \u0003של פרה מפני שהוא קרן\u0004 ואינו קרוי שופר. \u0003אמר ר' יוסי: והלא כל השופרות נקראו קרן, שנאמר: \"במשך בקרן היובל\"\u0004 (יהושע ו, ה), ו\"יובל\" זה הוא איל, וקרנו ודאי קרויה שופר.","ושואלים: הלא \u0003שפיר קאמר\u0004 \u0005[יפה אמר]\u0006 \u0003ר' יוסי\u0004 ולכאורה הוכחה ניצחת היא! ומסבירים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 החולקים עליו, אומרים: אכן, \u0003כל השופרות אקרו\u0004 \u0005[נקראו]\u0006 \u0003שופר ואקרו\u0004 \u0005[ונקראו]\u0006 גם כן \u0003קרן,\u0004 אולם זה של \u0003פרה\u0004 — \u0003קרן אקרי\u0004 \u0005[נקרא],\u0006 \u0003שופר לא אקרי\u0004 \u0005[נקרא],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בכור שורו הדר לו וקרני ראם קרניו\"\u0004 (דברים לג, יז), ומשמעו: שקרני אותו שור האמור, הם קרני ראם. הרי שקרויים הם קרן.","\u0003ור' יוסי אמר לך\u0004 \u0005[היה יכול לומר לך]:\u0006 קרני ה\u0003פרה נמי אקרי\u0004 \u0005[גם כן נקראו]\u0006 \u0003שופר, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ותטב לה' משור פר\"\u0004 (תהלים סט, לב) והפסוק בצורתו תמוה: \u0003אם\u0004 הוא \u0003שור למה\u0004 נקרא \u0003פר,\u0004 שהרי גיל הפר גדול מזה של השור! \u0003ואם פר\u0004 — \u0003למה שור,\u0004 ולכאורה יש כאן סתירה. \u0003אלא מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"שור פר\"\u0004 — יש לקרוא אותו כאילו היה כתוב \u0003\"משופר\"\u0004 ולפי זה אף קרני שור ופר נקראות שופר.","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 כיצד מבינים הם את הקושי שבפסוק זה? לדעתם יש לפרשו \u0003כדרב מתנה.\u0004 ש\u0003אמר רב מתנה: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"שור פר\"\u0004 — \u0003שהוא גדול כפר,\u0004 שאף ששור הוא צעיר יותר, מכל מקום זה היה שור הגדול כפר.","\u0003עולא אמר: היינו טעמא דרבנן\u0004 \u0005[זהו טעמם של חכמים],\u0006 \u0003כ\u0004דברי \u0003רב חסדא.\u0004 ש\u0003אמר רב חסדא: מפני מה אין כהן גדול נכנס בבגדי זהב לפני ולפנים\u0004 אל תוך קודש הקדשים \u0003לעבוד עבודה\u0004 — \u0003לפי שאין קטיגור נעשה סניגור.\u0004 שכיון שחטאו בני ישראל בעגל הזהב אין נכנסים לפני ולפנים בדבר שיש בו כדי להזכיר עוון זה.","ושואלים: \u0003ולא?\u0004 האין משתמשים כלל בקודש בפר? \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 את \u0003דם\u0004 ה\u0003פר\u0004 שמכניסים לקודש הקדשים כדי להזות ממנו! ומשיבים: \u0003הואיל ואשתני\u0004 \u0005[ונשתנה]\u0006 הדבר ואינו הפר עצמו אלא דמו בלבד — \u0003אשתני\u0004 \u0005[\u0006הרי \u0005השתנה]\u0006 ושוב אינו מעכב.","ומקשים עוד: \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 את ה\u0003ארון ו\u0004את ה\u0003כפורת ו\u0004את ה\u0003כרוב\u0004 שגם הם מצופים זהב, ואם גנאי הוא בדבר — מדוע הם בפנים? ומשיבים: הכוונה היתה \u0003חוטא בל יקריב קאמרינן\u0004 \u0005[אומרים אנו],\u0006 והחוטא הבא לבקש כפרה ראוי לו שלא להכנס בחפצי זהב המזכירים עוון.","ומקשים: \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 \u0003כף ומחתה\u0004 שמכניסים אותן לקודש קדשים להקריב קטורת והן עשויות זהב! ומשיבים: \u0003חוטא בל יתנאה\u0004 בתכשיט זהב \u0003קא אמרינן\u0004 \u0005[אומרים אנו].\u0006","ומקשים עוד: \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 \u0003בגדי זהב\u0004 שלובש הכהן \u0003מבחוץ\u0004 שלא בקודש הקדשים ומדוע אין אומרים שאל יתנאה החוטא? ומשיבים: \u0003מבפנים קא אמרינן\u0004 \u0005[אומרים אנו],\u0006 אבל מבחוץ — אין להקפיד בכך. ומקשים: אם כן, \u0003שופר נמי\u0004 \u0005[גם כן]\u0006 \u0003מבחוץ הוא,\u0004 שהרי אין מכניסים אותו בקודש הקדשים! ומשיבים: \u0003כיון\u0004 ש\u0003לזכרון הוא\u0004 עשוי להיות לפני ה' — הרי \u0003כבפנים דמי\u0004 \u0005[נחשב].\u0006 על עצם הטעם הזה מקשים: וכי זה הוא טעמם של חכמים?","\u0003והא תנא\u0004 \u0005[והרי שנה\u0006 התנא\u0005]:\u0006 \u0003\"מפני שהוא קרן\" קאמר\u0004 \u0005[אמר]\u0006 וזהו טעמו של דבר! ומשיבים: \u0003חדא\u0004 \u0005[\u0006טעם \u0005אחד]\u0006 \u0003ועוד\u0004 טעם נוסף \u0003קאמר\u0004 \u0005[אמר]\u0006 והזכיר רק אחד מהם במשנה, וכך משמעות הדברים: \u0003חדא\u0004 \u0005[\u0006טעם \u0005אחד]\u0006 \u0003שאין קטיגור נעשה סניגור, ועוד\u0004 טעם נוסף — \u0003מפני שהוא קרן\u0004 ואיננו נקרא שופר.","ושואלים: \u0003ור' יוסי\u0004 מה אומר ומשיב הוא לטענות אלה? ומסבירים: \u0003אמר לך\u0004 \u0005[יכול היה לומר לך]:\u0006 \u0003דקא אמרת\u0004 \u0005[זה שאמרת]\u0006 \u0003אין קטיגור נעשה סניגור\u0004 אמת הוא, אבל \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 \u0003מבפנים, והאי\u0004 \u0005[וזה]\u0006 ה\u0003שופר מבחוץ הוא. ודקא אמרת\u0004 \u0005[וזה שאמרת]\u0006 \u0003מפני שהוא קרן\u0004 — \u0003כל השופרות נמי אקרו\u0004 \u0005[גם כן נקראו]\u0006 \u0003קרן.\u0004","\u0003אביי אמר: היינו טעמייהו דרבנן\u0004 \u0005[זהו טעמם של חכמים]:\u0006 \u0003שופר אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003ולא שנים ושלשה שופרות\u0004 יחד, \u0003והא\u0004 \u0005[וזו]\u0006 הקרן של ה\u0003פרה, כיון דקאי גילדי גילדי\u0004 \u0005[שהיא עשויה שכבות שכבות]\u0006 — \u0003מיתחזי\u0004 \u0005[הריהו נראה]\u0006 \u0003כשנים ושלשה שופרות.\u0004","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003תנא\u0004 זה, \u0003מפני שהוא קרן קאמר\u0004 \u0005[אמר],\u0006 משמע שזה הוא הנימוק! ודוחים: \u0003חדא\u0004 \u0005[\u0006נימוק \u0005אחד]\u0006 \u0003ועוד\u0004 נימוק נוסף \u0003קאמר\u0004 \u0005[אמר];\u0006 \u0003חדא\u0004 \u0005[\u0006נימוק \u0005אחד\u0006 יסודי\u0005]\u0006 ש\u0003שופר אחד אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003ולא שנים ושלשה שופרות, ועוד\u0004 נימוק נוסף — \u0003מפני שהוא קרן.\u0004","\u0003ור' יוסי אמר לך\u0004 \u0005[\u0006היה \u0005יכול לומר לך]:\u0006 \u0003דקאמרת\u0004 \u0005[זה שאמרת]\u0006 \u0003שופר אחד אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003ולא שנים ושלשה שופרות\u0004 — אין זו קושיה, \u0003כיון דמחברי אהדדי\u0004 \u0005[כיון שהם מחוברים זה בזה],\u0006 ממילא \u0003חד\u0004 \u0005[\u0006שופר \u0005אחד]\u0006 \u0003הוא, ודקאמרת\u0004 \u0005[וזה שאמרת]\u0006 \u0003מפני שהוא קרן\u0004 — \u0003כל השופרות נמי\u0004 \u0005[גם כן]\u0006 \u0003אקרו\u0004 \u0005[נקראו]\u0006 \u0003קרן.\u0004","מתוך דברי ר' יוסי במשנה מוכח שקרן איל קרויה קרן, וזאת מן האמור בקרן היובל. ושואלים: \u0003מאי משמע דהאי יובלא לישנא דדכרא\u0004 \u0005[מהיכן נשמע שיובל זה לשון איל]\u0006 \u0003הוא?\u0004 ומשיבים: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' עקיבא: כשהלכתי לערביא\u0004 (למדינת ערב), שמעתי ש\u0003היו קורין\u0004 (קוראים) \u0003לדכרא\u0004 \u0005[לאיל]\u0006 \u0003\"יובלא\",\u0004 ואם כן ידועה משמעות \"יובל\" מההשוואה ללשון קרובה.","אגב מאמר זה מביאים דברים דומים, \u0003ואמר ר' עקיבא: כשהלכתי לגליא\u0004 שמעתי ש\u0003היו קורין לנדה \"גלמודה\",\u0004 ועל ידי כך נתבארה מלה זו בכתובים, ויש לפרשה ברמז — \u0003מאי\u0004 \u0005[מה]\u0006 עניינו של \u0003גלמודה\u0004 — \u0003גמולה\u0004 (מופרשת) \u0003דא\u0004 \u0005[מופרשת זו]\u0006 \u0003מבעלה.\u0004 שהרי הנידה אסורה לבעלה אף במגע. \u0003ואמר ר' עקיבא: כשהלכתי לאפריקי היו קורין למעה\u0004 של כסף \u0003קשיטה.\u0004 ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה]?\u0006 ומשיבים: \u0003לפרושי\u0004 \u0005[לפרש]\u0006 את הכתוב \u0003\"\u0004ב\u0003מאה קשיטה\"\u0004 (בראשית לג, יט) \u0003דאורייתא [\u0004ש\u0005בתורה],\u0006 שפירושו \u0003מאה דנקי\u0004 \u0005[מאה מעות].\u0006","כיוצא בו \u0003אמר רבי: כשהלכתי לכרכי הים, היו קורין\u0004 שם \u0003למכירה \"כירה\".\u0004 ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה]?\u0006 ומשיבים: \u0003לפרושי\u0004 \u0005[לפרש]\u0006 על ידי כך את הכתוב \u0003\"אשר כריתי לי\"\u0004 (בראשית נ, ה), שפירושו איפוא: קניתי.","\u0003אמר ר' שמעון בן לקיש: כשהלכתי לתחום קן נשרייא היו קורין\u0004 שם \u0003לכלה \"נינפי\", ולתרנגול \"שכוי\".\u0004 ומסבירים מה נלמד מכך: \u0003לכלה נינפי\u0004 — \u0003מאי קרא\u0004 \u0005[מה הכתוב]\u0006 שמשתמש בלשון דומה — שנאמר: \u0003\"יפה נוף משוש כל הארץ\"\u0004 (תהלים מח, ג), ופירושו איפוא: יפה כמו כלה. \u0003ולתרנגול \"שכוי\"\u0004 — \u0003אמר רב יהודה אמר רב, ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שאמר זאת \u0003ר' יהושע בן לוי: מאי קרא\u0004 \u0005[מהו הפסוק]\u0006 השייך לזה — \u0003\"מי שת בטחות חכמה או מי נתן לשכוי בינה\"\u0004 (איוב לח, לו), ויש לפרשו: \u0003\"מי שת בטחות חכמה\"\u0004 — \u0003אלו כליות\u0004 שהם חבויות (\"טוחות\") בגופו של אדם, \u0003\"או מי נתן לשכוי בינה\" זה תרנגול\u0004 היודע לקרוא בשעות קבועות בלילה.","ואגב הדברים בבירור מובנן של מילים זרות במקומות שונים, מסופר: \u0003לוי איקלע לההוא אתרא\u0004 \u0005[הזדמן למקום אחד],\u0006 \u0003אתא גברא לקמיה\u0004 \u0005[בא אדם לפניו]\u0006 להתלונן על מה שנעשה לו, \u0003אמר ליה\u0004 \u0005[לו]\u0006 אותו אדם:"],["\u0003קבען פלניא\u0004 \u0005[קבע אותי פלוני].\u0006 \u0003לא הוה ידע\u0004 \u0005[היה יודע,\u0006 מבין\u0005]\u0006 לוי \u0003מאי קאמר ליה\u0004 \u0005[מה אמר לו]\u0006 אותו אדם, מה פירושה של מלה זו. \u0003אתא שאיל בי מדרשא\u0004 \u0005[\u0006בא \u0005ושאל בבית המדרש],\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003גזלן\u0004 \u0005[גזל אותי]\u0006 \u0003אמר לך\u0004 אותו אדם, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"היקבע אדם אלהים\"\u0004 (מלאכי ג, ח). \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא\u0004 מן המקום \u0003ברניש לרב אשי: אי הואי התם\u0004 \u0005[אם הייתי שם]\u0006 במקום לוי הייתי מנסה למצוא את המובן בדרך אחרת, \u0003הוה אמינא ליה\u0004 \u0005[הייתי אומר לו]:\u0006 \u0003היכי\u0004 \u0005[איך]\u0006 \u0003קבעך? במאי\u0004 \u0005[במה]\u0006 \u0003קבעך? ואמאי\u0004 \u0005[ומדוע]\u0006 \u0003קבעך?\u0004 ו\u0003ממילא\u0004 מתוך תשובותיו \u0003הוה ידעינא\u0004 \u0005[הייתי יודע]\u0006 במה מדובר. ומסבירים: \u0003ואיהו\u0004 \u0005[והוא],\u0006 לוי שלא עשה כן, \u0003סבר: מילתא דאיסורא קאמר ליה\u0004 \u0005[דבר של איסור אמר לו]\u0006 ולכן לא היה יכול לשאול באופן זה. ועוד בענין מילים נדירות.","\u0003לא הוו ידעי רבנן\u0004 \u0005[ידעו חכמים]\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 המלה \u0003\"סירוגין\"\u0004 האמורה במשנה. \u0003שמעוה לאמתא דבי\u0004 \u0005[שמעו אותה\u0006 את \u0005השפחה של בית]\u0006 \u0003רבי דחזתנהו רבנן דהוו עיילי פסקי פסקי\u0004 \u0005[שראתה את החכמים שהם נכנסים\u0006 לבית רבי \u0005פרקים פרקים]\u0006 ולא בבת אחת, ו\u0003אמרה להו\u0004 \u0005[להם]:\u0006 \u0003עד מתי אתם נכנסין סירוגין סירוגין,\u0004 וממילא הבינו מה פירוש המלה סירוגין.","\u0003לא הוו ידעי רבנן\u0004 \u0005[ידעו חכמים]\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 המלה \u0003\"חלוגלוגות\"\u0004 שבמשנה, \u0003יומא חד שמעוה לאמתא דבי\u0004 \u0005[יום אחד שמעו אותה\u0006 את \u0005השפחה\u0006 של \u0005בית]\u0006 \u0003רבי דחזית לההוא גברא דקא מבדר פרפחיניה\u0004 \u0005[שראתה אדם אחד שמפזר את חלוגלוגותיו],\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003עד מתי אתה מפזר חלוגלוגך,\u0004 וידעו מה הם אלה.","\u0003לא הוו ידעי רבנן\u0004 \u0005[ידעו חכמים]\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 פירוש הכתוב: \u0003\"סלסלה ותרוממך\"\u0004 (משלי ד, ח), שלא ידעו מה פירוש סלסול, \u0003יומא חד שמעוה לאמתא דבי\u0004 \u0005[יום אחד שמעו אותה\u0006 את \u0005השפחה\u0006 של \u0005בית]\u0006 \u0003רבי דהות אמרה לההוא גברא\u0004 \u0005[שהיתה אומרת לאדם אחד]\u0006 \u0003דהוה קא מהפך בשעריה\u0004 \u0005[שהיה מהפך בשערו],\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003עד מתי אתה מסלסל בשערך.\u0004","\u0003לא הוו ידעי רבנן\u0004 \u0005[ידעו חכמים]\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 הכתוב: \u0003\"וטאטאתיה במטאטא השמד\"\u0004 (ישעיה יד, כג), \u0003יומא חד שמעוה לאמתא דבי\u0004 \u0005[יום אחד שמעו אותה\u0006 את \u0005השפחה\u0006 של \u0005בית]\u0006 \u0003רבי דהוות אמרה\u0004 \u0005[שהיתה אומרת]\u0006 \u0003לחבירתה: שקולי טאטיתא\u0004 \u0005[קחי מטאטא]\u0006 \u0003וטאטי ביתא\u0004 \u0005[וטאטאי את הבית]\u0006 והבינו.","\u0003לא הוו ידעי רבנן\u0004 \u0005[ידעו חכמים]\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 הכתוב: \u0003\"השלך על ה' יהבך והוא יכלכלך\"\u0004 (תהלים נה, כג), שלא ידעו פירוש \"יהבך\". \u0003אמר רבה בר בר חנה: יומא חד הוה אזלינא בהדי ההוא טייעא\u0004 \u0005[יום אחד הלכתי עם ערבי אחד],\u0006 \u0003הוה דרינא טונא\u0004 \u0005[הייתי נושא משא]\u0006 \u0003ואמר לי\u0004 אותו ערבי: \u0003שקול יהביך ושדי אגמלאי\u0004 \u0005[טול את משאך והניחו על גמלי]\u0006 ומכאן מבינים ש\"יהב\" פירושו משא.","\u0003שופר של ראש השנה,\u0004 שהיו תוקעים בו בראש השנה בבית המקדש, היה \u0003של יעל\u0004 והיה \u0003פשוט\u0004 כלומר ישר, \u0003ופיו\u0004 (סמוך למקום שתוקעים בו) \u0003מצופה זהב, ושתי חצוצרות היו מן הצדדין\u0004 לצידו של התוקע בשופר. ובשעת התקיעה \u0003שופר מאריך\u0004 בתקיעה \u0003וחצוצרות מקצרות, שמצות היום בשופר.\u0004","\u0003ו\u0004אילו \u0003ב\u0004ימי ה\u0003תעניות\u0004 היו תוקעים \u0003בשל זכרים\u0004 (אילים) \u0003כפופין, ופיהן מצופה כסף, ושתי חצוצרות באמצע\u0004 בין השופרות, \u0003שופר\u0004 היה \u0003מקצר וחצוצרות מאריכות, שמצות היום בחצוצרות.\u0004","ומוסיפים: \u0003שוה היובל\u0004 לענין המצוה לתקוע בשופר ביום הכיפורים ביובל \u0003לראש השנה,\u0004 הן \u0003לתקיעה\u0004 עצמה ולדיניה, \u0003ו\u0004הן \u0003לברכות\u0004 הנוספות בתפילת העמידה. \u0003ר' יהודה אומר\u0004 שאין הדבר כך, והיו משנים: \u0003בראש השנה תוקעין בשל זכרים\u0004 (אילים) \u0003וביובלות\u0004 תוקעים \u0003בשל יעלים.\u0004","\u0003אמר ר' לוי: מצוה של ראש השנה ושל יום הכפורים\u0004 של שנת היובל, היא לתקוע \u0003ב\u0004שופרות \u0003כפופין ושל כל השנה\u0004 (בתעניות) \u0003בפשוטין.\u0004 ומקשים, \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003שופר של ראש השנה של יעל פשוט!\u0004 ומתרצים: \u0003הוא\u0004 ש\u0003אמר\u0004 את דבריו, אמרם \u0003כי האי תנא\u0004 \u0005[\u0006אמרם \u0005כ\u0006דעת \u0005תנא זה];\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהודה אומר: בראש השנה היו תוקעין בשל זכרים כפופין, וביובלות בשל יעלים.\u0004 ושואלים:","\u0003אם כן, ולימא הלכתא\u0004 \u0005[ושיאמר\u0006 ש\u0005הלכה]\u0006 \u0003כר' יהודה,\u0004 ומדוע הוצרך לומר את תוכן ההלכה עצמה, כאילו היה זה דבר חדש? ומסבירים: \u0003אי אמרת\u0004 \u0005[אם היית אומר]\u0006 כי \u0003הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כר' יהודה, הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003אפילו\u0004 בשופר \u0003של יובל נמי\u0004 \u0005[גם כן]\u0006 \u0003כר' יהודה סבירא ליה\u0004 \u0005[סבור הוא],\u0006 שצריך לתקוע בשל יעל, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שרק לענין ראש השנה פסק כמותו, אבל לא לענין אחר.","לעצם הדברים שואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון\u0005, נחלקו]?\u0006 \u0003מר\u0004 \u0005[חכם זה],\u0006 ר' יהודה \u0003סבר: בראש השנה כמה דכייף איניש דעתיה\u0004 \u0005[ככל שאדם כופף\u0006 יותר \u0005את דעתו]\u0006 ואת עצמו שמתפלל כשהוא כפוף והולך, \u0003טפי מעלי\u0004 \u0005[מעולה יותר],\u0006 וכרמז לכך תוקעים בשופר כפוף, \u0003ו\u0004אילו \u0003ביום הכפורים\u0004 — \u0003כמה דפשיט איניש דעתיה\u0004 \u0005[ככל שאדם פושט\u0006 יותר \u0005את דעתו]\u0006 ואת עצמו בתפילה, \u0003טפי מעלי\u0004 \u0005[מעולה יותר].\u0006 \u0003ומר\u0004 \u0005[וחכם זה]\u0006 \u0003סבר: בראש השנה כמה דפשיט איניש דעתיה\u0004 \u0005[ככל שאדם פושט\u0006 יותר \u0005את דעתו]\u0006 ומפשט את דעתו מכל עקמימות, \u0003טפי מעלי\u0004 \u0005[מעולה יותר],\u0006 ואילו \u0003בתעניות כמה דכייף איניש דעתיה\u0004 \u0005[ככל שאדם כופף\u0006 יותר \u0005את דעתו]\u0006 ואת עצמו \u0003טפי מעלי\u0004 \u0005[מעולה יותר].\u0006"],["שנינו במשנה ש\u0003פיו\u0004 של השופר שבמקדש היה \u0003מצופה זהב.\u0004 ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 שופר ש\u0003ציפהו זהב במקום הנחת פיו\u0004 — \u0003פסול\u0004 לתקיעה, ואם היה ציפוי הזהב \u0003שלא במקום הנחת פיו\u0004 — \u0003כשר! אמר אביי: כי תנן נמי מתניתין\u0004 \u0005[כאשר שנינו גם כן, במשנתנו]\u0006 — \u0003שלא במקום הנחת פה תנן\u0004 \u0005[שנינו]\u0006 אלא מעט למעלה ממנו.","שנינו במשנה שהיו \u0003שתי חצוצרות מן הצדדים.\u0004 ושואלים: \u0003ותרי קלי מי משתמעי\u0004 \u0005[ושני קולות\u0006 יחד \u0005האם\u0006 הם \u0005נשמעים]?\u0006 שבגלל החצוצרות אין שומעים את קול השופר כראוי. \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 שתי לשונות אלה, \u0003\"זכור\"\u0004 (שמות כ, ח) \u0003ו\"שמור\"\u0004 (דברים ה, יב), שהם שתי הנוסחות בדיבר שבעשרת הדברות העוסק בענין יום השבת, בספר שמות ובספר דברים, \u0003בדבור אחד נאמרו,\u0004 שבדיבור זה נאמר \"זכור\" ו\"שמור\" כאחת, \u0003מה שאין הפה יכולה לדבר ואין האוזן יכולה לשמוע,\u0004 משמע שאי אפשר לשמוע שני קולות כאחד, ואף מפני החצוצרות אין קול השופר יכול להשמע! ומשיבים: \u0003לכך מאריך בשופר\u0004 כדי שיוכלו לשמוע את קול השופר לעצמו.","על תשובה זו תוהים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 וללמוד מכאן \u0003דכי שמע\u0004 \u0005[שכאשר היה שומע]\u0006 את \u0003סוף\u0004 ה\u0003תקיעה בלא\u0004 ששמע את \u0003תחילת\u0004 ה\u0003תקיעה יצא?\u0004 שהרי מתחיל בשופר ובחצוצרות כאחת אלא שבסוף התקיעה תוקעים בשופר בלבד, ואם אכן די בכך, משמע שיוצאים ידי חובה בשמיעת סוף התקיעה. \u0003וממילא\u0004 נלמד גם כן כי השומע את \u0003תחילת\u0004 ה\u0003תקיעה בלא\u0004 ששמע את \u0003סוף\u0004 ה\u0003תקיעה\u0004 גם כן \u0003יצא.\u0004","ולבירור אפשרות זו, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 מקור המדבר בענין זה, שנינו: \u0003תקע בראשונה\u0004 שהיא התקיעה שבתחילת סדר תקיעות אחד \u0003ומשך\u0004 (האריך) בתקיעה ה\u0003שניה\u0004 שהיא האחרונה לאותו סדר תקיעות, כך שהיא נשמעת \u0003כשתים\u0004 ובכך רצה שתהיה נחשבת כשתי תקיעות נפרדות, האחת כתקיעה האחרונה לסדר תקיעות זה והשניה כראשונה לסדר התקיעות הבא — \u0003אין בידו אלא אחת\u0004 ואינה נחשבת כשתי תקיעות נבדלות. ויש לתהות: \u0003אמאי\u0004 \u0005[מדוע]\u0006 נאמר כך? \u0003תיסלק לה בתרתי\u0004 \u0005[תעלה,\u0006 תיחשב, \u0005לו כשתים],\u0006 שהרי כפי שאמרנו מחצית תקיעה נחשבת לתקיעה! ומשיבים: \u0003פסוקי תקיעתא מהדדי לא פסקינן\u0004 \u0005[לחלק התקיעות זו מזו אין אנו מחלקים],\u0006 שאין אנו יכולים לחתוך קול אחד ולדונו כשנים, אף שהשומע מחצית תקיעה יצא בה ידי חובה.","ומנסים להוכיח ממקור אחר: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006\u0003,\u0004 ממה ששנינו: \u0003התוקע לתוך הבור, או לתוך הדות\u0004 (בור שהוא חלק מבנין), \u0003או לתוך הפיטס\u0004 (חבית גדולה), \u0003אם קול שופר שמע\u0004 בבירור — הרי זה \u0003יצא, ואם קול הברה\u0004 (הד) בלבד \u0003שמע\u0004 — \u0003לא יצא.\u0004 ולכאורה \u0003אמאי\u0004 \u0005[מדוע]\u0006 לא יצא? \u0003ליפוק\u0004 \u0005[שייצא]\u0006 ידי חובתו \u0003בתחילת תקיעה, מקמי דליערבב קלא\u0004 \u0005[לפני שיתערבב הקול]\u0006 על ידי ההד, ואף שאינו יכול לשמוע את סוף התקיעה בבהירות, מכל מקום הלא את תחילתה שמע כראוי!","\u0003אלא\u0004 יש לחזור מן ההסבר שאמרנו, וכך יש לומר: \u0003תרתי קלי מחד גברא\u0004 \u0005[שני קולות\u0006 הנשמעים \u0005מאיש אחד]\u0006 ממקור אחד — \u0003לא משתמעי\u0004 \u0005[אינם נשמעים],\u0006 וזה היה הנס במתן תורה שנשמעו כאחד מאותו מקור, אולם \u0003מתרי גברי\u0004 \u0005[משני אנשים]\u0006 המשמיעים קול — \u0003משתמעי\u0004 \u0005[נשמעים]\u0006 הקולות, ואפשר להבחין ביניהם.","ומקשים: \u0003ומתרי גברי מי משתמעי\u0004 \u0005[ומשני אנשים האם נשמעים]\u0006 הדברים בבירור? \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בתורה\u0004 — \u0003אחד קורא ואחד מתרגם, ובלבד שלא יהו שנים קורין ושנים מתרגמין,\u0004 הרי ששניים אין קולם נשמע!","ומעירים: מכאן אין להקשות \u0003הא לא דמיא\u0004 \u0005[זה אינו דומה]\u0006 \u0003אלא לסיפא\u0004 \u0005[ל\u0006מה שנאמר \u0005בסופה]\u0006 של אותה ברייתא עצמה, ששנינו בה: \u0003בהלל ובמגילה\u0004 — \u0003אפילו עשרה קורין\u0004 כאחד. \u0003אלמא\u0004 \u0005[מכאן],\u0006 \u0003כיון\u0004 ש\u0003חביב\u0004 הדבר לשומעיו \u0003יהיב דעתיה\u0004 \u0005[נותנים דעתם]\u0006 ומקשיבים היטב וממילא מבחינים בדיבורים, \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 \u0003כיון\u0004 ש\u0003חביב\u0004 השופר — \u0003יהיב דעתיה ושמע\u0004 \u0005[הוא נותן דעתו\u0006 להבחין בקולות \u0005ושומע].\u0006","\u0003אלא אם אכן אפשר להבחין בקול השופר אף כשתוקעים באותו זמן בחצוצרה, למה מאריך\u0004 איפוא \u0003בשופר?\u0004 הרי זה כדי \u0003לידע\u0004 ולהדגיש \u0003שמצות היום בשופר\u0004 היא.","שנינו במשנה כי \u0003בתעניות\u0004 תוקעים \u0003בשל זכרים\u0004 (אילים) \u0003כפופין ופיו\u0004 של השופר \u0003מצופה כסף.\u0004 ושואלים: \u0003מאי שנא התם\u0004 \u0005[במה שונה שם]\u0006 בשופר של ראש השנה שמצפים אותו ב\u0003זהב, ומאי שנא הכא\u0004 \u0005[ובמה שונה כאן]\u0006 בתענית שמצפים את פיו ב\u0003כסף?\u0004 ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 טעם אחד: \u0003כל\u0004 שופר שעושים לשם \u0003כינופיא\u0004 \u0005[אסיפת קהל]\u0006 של \u0003כסף הוא, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"עשה לך שתי חצוצרת כסף\u0004 מקשה תעשה אותם והיו לך למקרא העדה ולמסע את המחנות\" (במדבר י, ב). \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003התורה חסה על ממונן של ישראל\u0004 ולכך אין מצפים אלא בכסף שהוא חומר זול יותר מזהב.","ומקשים: אם כן, \u0003התם נמי נעביד\u0004 \u0005[שם,\u0006 בראש השנה \u0005גם כן נעשה]\u0006 ציפוי של \u0003כסף!\u0004 ומשיבים: \u0003אפילו הכי\u0004 \u0005[כך]\u0006 \u0003כבוד יום טוב עדיף\u0004 וראוי להדר וליפות את שופרו של החג, אולם בתענית, שאיננה יום טוב — אין צורך להדר ביותר, ומסתפקים בשל כסף.","מסופר: \u0003רב פפא בר שמואל סבר למיעבד עובדא כמתניתין\u0004 \u0005[לעשות מעשה כמשנתנו]\u0006 בשופר ובחצוצרות ובכל שאר הפרטים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: לא אמרו\u0004 דבר זה \u0003אלא במקדש\u0004 בלבד. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003במה דברים אמורים\u0004 — \u0003במקדש, אבל בגבולין\u0004 מחוץ למקדש: \u0003מקום שיש\u0004 תקיעה ב\u0003חצוצרות\u0004 כגון בתעניות — \u0003אין שופר,\u0004 וב\u0003מקום שיש שופר\u0004 — \u0003אין חצוצרות.\u0004","\u0003וכן הנהיג ר' חלפתא בציפורי ור' חנניא בן תרדיון בסיכני\u0004 שיעשו כדרך המתוארת במשנה, \u0003וכשבא דבר אצל חכמים אמרו: לא היו נוהגין כן אלא בשערי מזרח\u0004 של המקדש \u0003ובהר הבית בלבד.\u0004","\u0003אמר רבא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003ר' יהושע בן לוי: מאי קראה\u0004 \u0005[מהו הכתוב]\u0006 המלמד אותנו דבר זה — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בחצצרות וקול שופר הריעו לפני המלך ה'\"\u0004 (תהלים צח, ו), כלומר: \u0003לפני המלך ה'\u0004 במקדשו \u0003הוא דבעינן\u0004 \u0005[שצריכים אנו]\u0006 \u0003חצוצרות וקול שופר\u0004 יחד, \u0003אבל בעלמא\u0004 \u0005[בכלל]\u0006 מחוץ למקדש — \u0003לא.\u0004","שנינו במשנה: \u0003שוה היובל לראש השנה לתקיעה ולברכות. אמר ר' שמואל בר יצחק: כמאן מצלינן האידנא\u0004 \u0005[כ\u0006דעת \u0005מי מתפללים אנו היום]\u0006 בראש השנה, ואומרים בתפילה: \u0003\"זה היום תחלת מעשיך זכרון ליום ראשון\", כמאן\u0004 \u0005[כמי]\u0006 — \u0003כ\u0004שיטת \u0003ר' אליעזר, שאמר: בתשרי נברא העולם\u0004 ולכן מזכירים בראש השנה יום ראשון.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב עינא:\u0004 שנינו, \u0003שוה יובל לראש השנה לתקיעה ולברכות, והא איכא\u0004 \u0005[והרי יש]\u0006 \u0003\"זה היום תחלת מעשיך זכרון ליום ראשון\"\u0004 ש\u0003בראש השנה איתא\u0004 \u0005[ישנו],\u0006 שיש מקום לאומרו, \u0003ו\u0004אילו \u0003ביובל ליתא\u0004 \u0005[איננו],\u0006 שהרי אין זה זכרון ליום ראשון, ואין זה \"תחילת מעשיך\"! ומשיבים: \u0003כי קתני\u0004 \u0005[כאשר שנינו]\u0006 — הרי זה \u0003אשארא\u0004 \u0005[על שאר\u0006 הדברים\u0005]\u0006 שבנוסח הברכות, ומשמיטים קטע זה.","\u0003רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי מתני הכי\u0004 \u0005[היה שונה\u0006 את הקטע האחרון \u0005כך],\u0006 \u0003אמר רב שמואל בר יצחק: הא דתנן\u0004 \u0005[זו ששנינו\u0006 במשנתנו\u0005]\u0006 \u0003שוה היובל לראש השנה לתקיעה ולברכות כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי] —\u0006 ש\u0003לא כ\u0004שיטת \u0003ר' אליעזר, דאי\u0004 \u0005[שאם]\u0006 כשיטת \u0003ר' אליעזר\u0004 היא, \u0003כיון\u0004 ש\u0003אמר\u0004 ש\u0003בתשרי נברא העולם,\u0004 אם כן \u0003הא איכא\u0004 \u0005[הרי יש]\u0006 גם את הנוסח \u0003\"זה היום תחלת מעשיך זכרון ליום ראשון\"\u0004 ש\u0003בראש השנה איתא\u0004 \u0005[ישנו],\u0006 \u0003וביובל ליתא\u0004 \u0005[איננו],\u0006 וממשנתנו מובן שאינו כן! ודוחים: \u0003כי קתני\u0004 \u0005[כאשר שנינו]\u0006 מה ששנינו היה זה \u0003אשארא\u0004 \u0005[על שאר\u0006 הדברים\u0005]\u0006 ולא על קטע זה, שבו משנים, וכדעת ר' אליעזר.","\u0003שופר שנסדק ודבקו\u0004 בדבק, אף על פי שהוא לכאורה שלם — הרי הוא \u0003פסול\u0004 לתקיעה. וכן, אם \u0003דיבק שברי שופרות\u0004 ועשה מהם שופר אחד שלם — הרי זה \u0003פסול.\u0004"],["\u0003ניקב\u0004 השופר \u0003וסתמו, אם\u0004 הנקב \u0003מעכב\u0004 ומשנה \u0003את\u0004 קול \u0003התקיעה\u0004 — \u0003פסול, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003כשר. התוקע לתוך הבור, או לתוך הדות\u0004 (בור העשוי בבנין), \u0003או לתוך הפיטס\u0004 (כד גדול מאוד), \u0003אם קול שופר\u0004 בלבד \u0003שמע\u0004 — \u0003יצא, ואם קול הברה\u0004 (הד היוצא על ידי הפיטס או הבור) \u0003שמע\u0004 — \u0003לא יצא.\u0004","\u0003וכן, מי שהיה עובר אחורי בית הכנסת, או שהיה ביתו סמוך לבית הכנסת ושמע קול שופר או קול מגילה, אם כוון לבו\u0004 — \u0003יצא, ואם לאו\u0004 — \u0003לא יצא.\u0004 ועל פי הלכה זו יתכן מקרה ששמעו שנים, ועם כל זה האחד יצא ידי חובתו והשני לא יצא. ו\u0003אף על פי שזה שמע וזה שמע,\u0004 מכל מקום \u0003זה כוון לבו\u0004 לצאת ידי חובתו בשעה ששמע ולכן אכן יצא, \u0003וזה לא כוון לבו\u0004 ולכן לא יצא.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 היה השופר \u0003ארוך וקצרו\u0004 — הרי זה \u0003כשר. גרדו\u0004 את השופר מעוביו כל כך עד ש\u0003העמידו על גלדו\u0004 (עורו) בלבד — הרי זה \u0003כשר.\u0004 אם \u0003ציפהו זהב במקום הנחת פה\u0004 — הרי זה \u0003פסול, שלא במקום הנחת פה\u0004 — \u0003כשר. ציפהו זהב מבפנים\u0004 — הרי זה \u0003פסול\u0004 לפי שאין שומעים אז קול שופר אלא קול היוצא מכלי זהב. ציפהו זהב \u0003מבחוץ, אם נשתנה קולו מכמות שהיה\u0004 לפני הציפוי — הרי זה \u0003פסול, ואם לאו\u0004 \u0005[לא] —\u0006 אינו אלא כקישוט ו\u0003כשר.\u0004","\u0003ניקב\u0004 השופר \u0003וסתמו, אם מעכב את התקיעה\u0004 על ידי הסתימה — \u0003פסול, ואם לאו\u0004 — \u0003כשר. נתן שופר בתוך שופר\u0004 ותקע, \u0003אם\u0004 את \u0003קול\u0004 השופר ה\u0003פנימי שמע\u0004 — \u0003יצא\u0004 שהרי שופר אחד הוא, \u0003ואם\u0004 את \u0003קול\u0004 השופר ה\u0003חיצון שמע\u0004 — \u0003לא יצא\u0004 לפי שהקול יוצא בין שני השופרות כאחד.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא אחרת: \u0003גרדו, בין מבפנים בין מבחוץ\u0004 — \u0003כשר. גרדו\u0004 עד כדי כך ש\u0003העמידו\u0004 רק \u0003על גלדו\u0004 (עורו) בלבד — \u0003כשר. הניח שופר בתוך שופר\u0004 ותקע בו, \u0003אם\u0004 את \u0003קול\u0004 השופר ה\u0003פנימי שמע\u0004 — \u0003יצא, ואם\u0004 את \u0003קול\u0004 ה\u0003חיצון שמע\u0004 — \u0003לא יצא. הפכו\u0004 את השופר \u0003ותקע בו\u0004 — \u0003לא יצא.\u0004","\u0003אמר רב פפא: לא תימא\u0004 \u0005[תאמר]\u0006 \u0003דהפכיה ככתונא\u0004 \u0005[שהפכו,\u0006 את השופר \u0005ככתונת],\u0006 כלומר, שהפך שיהיה חלקו הפנימי בחוץ וחלקו החיצוני בפנים, \u0003אלא\u0004 הכוונה היא \u0003שהרחיב את\u0004 הצד \u0003הקצר\u0004 (הצר) \u0003וקיצר\u0004 (הצר) \u0003את הרחב. מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של דין אחרון זה — \u0003כ\u0004דברי \u0003רב מתנה,\u0004 ש\u0003אמר רב מתנה:\u0004 נאמר, \u0003\"והעברת\u0004 שופר תרועה \u0003\"(ויקרא כה, ט), ללמדנו: דרך העברתו בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהא השופר כדרך שהוא עובר בראש הבהמה, ואם עשה בשינוי — פסול.","שנינו במשנה: שאם \u0003דיבק שברי שופרות\u0004 — \u0003פסול. תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003הוסיף עליו\u0004 על השופר \u0003כל שהוא, בין\u0004 שהוסיף עליו \u0003במינו\u0004 ממין השופר \u0003בין שלא במינו\u0004 — הרי זה \u0003פסול. ניקב\u0004 השופר \u0003וסתמו, בין במינו בין שלא במינו\u0004 — \u0003פסול. ר' נתן אומר:\u0004 אם סתמו \u0003במינו\u0004 — \u0003כשר,\u0004 אם \u0003שלא במינו\u0004 — \u0003פסול.\u0004","על כך אמרו: \u0003במינו כשר\u0004 — \u0003אמר ר' יוחנן: והוא שנשתייר רובו\u0004 של השופר שלם והוסיף בו רק טלאי קטן משופר אחר. ו\u0003מכלל\u0004 הדברים הללו למדים אנו, שאם סתמו \u0003שלא במינו, אף על פי שנשתייר רובו\u0004 — \u0003פסול.\u0004","\u0003איכא דמתני לה אסיפא\u0004 \u0005[יש ששונה\u0006 דבר \u0005זה על סופה]\u0006 של אותה משנה. ששנינו: אם סתם את השופר \u0003שלא במינו\u0004 — \u0003פסול, אמר ר' יוחנן: והוא שנפחת רובו\u0004 של השופר. \u0003מכלל\u0004 הדברים אתה שומע, שאם סתמו ודבקו \u0003במינו, אף על פי שנפחת רובו\u0004 — \u0003כשר.\u0004","\u0003ציפהו זהב, מבפנים\u0004 — \u0003פסול.\u0004 ציפהו \u0003מבחוץ, אם נשתנה קולו מכמות שהיה\u0004 — \u0003פסול, ואם לאו\u0004 — \u0003כשר.\u0004 אם \u0003נסדק\u0004 השופר \u0003לאורכו\u0004 — \u0003פסול.\u0004 ואם נסדק \u0003לרוחבו\u0004 — רואים. \u0003אם נשתייר\u0004 בחלק השופר שאינו סדוק \u0003שיעור תקיעה\u0004 — הרי זה \u0003כשר, ואם לאו\u0004 — \u0003פסול.\u0004","\u0003וכמה שיעור תקיעה\u0004 שיהא בשופר? \u0003פירש רבן שמעון בן גמליאל: כדי שיאחזנו בידו ויראה\u0004 משהו ממנו \u0003לכאן ולכאן\u0004 משני צידי היד. \u0003היה קולו\u0004 של השופר \u0003דק\u0004 ביותר \u0003או עבה, או צרור\u0004 (קול יבש) — הרי זה \u0003כשר, שכל הקולות כשירין בשופר\u0004 ולא קבעה התורה קול מסויים בלבד.","\u0003שלחו ליה לאבוה\u0004 \u0005[לו לאביו]\u0006 של \u0003שמואל\u0004 מארץ ישראל הלכה: \u0003קדחו ותקע בו יצא.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן הדבר מאליו\u0005],\u0006 שהרי \u0003כולהו נמי מיקדח קדחו להו\u0004 \u0005[\u0006השופרות \u0005כולם גם כן קודחים אותם],\u0006 שהרי לאחר הסרת הקרן מן הבהמה, קודחים ומוציאים את העצם הבולטת שבה הוא מחובר בראש הבהמה, ומה החידוש בהלכה זו?","\u0003אמר רב אשי:\u0004 כאן מדובר באופן \u0003שקדחו בזכרותו,\u0004 כלומר, שקדחו חור בתוך העצם שבקרן ולא הוציאו אותה בשלימותה מן השופר, כרגיל. \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 אפילו \u0003מין במינו חוצץ\u0004 ועצם זו כיון שאינה מן הקרן עצמה תיחשב לחציצה בשופר, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שהם נחשבים מאותו מין ואינו חוצץ.","שנינו במשנה: \u0003התוקע לתוך הבור או לתוך הדות,\u0004 אם שמע קול הברה לא יצא. \u0003אמר רב הונא: לא שנו\u0004 שבאופן כזה אין יוצאים ידי חובת תקיעה, \u0003אלא לאותן העומדים על שפת הבור\u0004 בחוץ, שהם אינם שומעים אלא את ההד הבא מן הבור, \u0003אבל אותן העומדין בבור\u0004 עצמו — \u0003יצאו\u0004 שהרי הם עצמם שומעים תחילה את קול השופר.","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003התוקע לתוך הבור או לתוך הדות\u0004 — \u0003יצא. והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 בפירוש כי באופן כזה \u0003לא יצא! אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 שיש לישב זאת \u0003כ\u0004דברי \u0003רב הונא,\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","זו היתה גירסה אחת, והיו שגרסו באופן אחר: \u0003איכא דרמי להו מירמא\u0004 \u0005[יש שהשליך,\u0006 הראה סתירה בדברים \u0005הללו]\u0006 והביא את דברי הונא כתירוץ להם; \u0003תנן\u0004 \u0005[שנינו במשנה]:\u0006 \u0003התוקע לתוך הבור או לתוך הדות\u0004 — \u0003לא יצא. והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003יצא! אמר רב הונא: לא קשיא\u0004 \u0005[קשה];\u0006 \u0003כאן\u0004 — \u0003לאותן העומדין על שפת הבור\u0004 — לא יצא, \u0003כאן לאותן העומדין בבור\u0004 — יצא.","\u0003אמר רבה:\u0004"],["\u0003שמע מקצת תקיעה בבור\u0004 ויצא מן הבור \u0003ו\u0004שמע \u0003מקצת תקיעה על שפת הבור\u0004 — \u0003יצא\u0004 ידי חובה. שמע \u0003מקצת תקיעה קודם שיעלה עמוד השחר,\u0004 שעדיין אינו זמן הראוי לתקיעה, \u0003ומקצת תקיעה לאחר שיעלה עמוד השער\u0004 — \u0003לא יצא.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: מאי שנא התם\u0004 \u0005[במה שונה שם]\u0006 בענין יום ולילה שאינו יוצא בה, משום \u0003דבעינא כולה תקיעה בחיובא, וליכא\u0004 \u0005[שצריכים שתהא כל התקיעה ב\u0006זמן \u0005חיוב, ואיננה].\u0006 \u0003הכא נמי\u0004 — \u0003בעינא כולה תקיעה בחיובא, וליכא\u0004 \u0005[כאן גם כן,\u0006 בבור, \u0005צריכים אנו את כל התקיעה ב\u0006מקום \u0005חיוב ואין\u0006 כאן\u0005]!\u0006","ודוחים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]?!\u0006 \u0003התם\u0004 \u0005[שם]\u0006 \u0003לילה לאו\u0004 \u0005[לא]\u0006 \u0003זמן חיובא\u0004 \u0005[חיוב]\u0006 \u0003הוא כלל\u0004 ותקיעת שופר בלילה אין לה שום משמעות, אולם \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003בור מקום חיובא\u0004 \u0005[חיוב]\u0006 \u0003הוא לאותן העומדין ב\u0004תוך ה\u0003בור.\u0004 שחלק התקיעה שבתוך הבור אינו פסול מעיקרו אלא רק מפני גורם חיצוני ולכן יש מקום לצרפו.","ושואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 ללמוד מכאן ש\u0003סבר רבה,\u0004 שאם \u0003שמע סוף תקיעה בלא תחילת תקיעה\u0004 — \u0003יצא, וממילא\u0004 מובן שאם שמע \u0003תחילת תקיעה בלא סוף תקיעה\u0004 גם כן \u0003יצא.\u0004","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה שאין הדבר כן. ששנינו: \u0003תקע בראשונה, ומשך\u0004 בתקיעה \u0003השניה\u0004 במשך זמן \u0003כשתים\u0004 (כשתי תקיעות) \u0003אין בידו אלא אחת\u0004 שאין מחשיבים אותה לשתי תקיעות. \u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 שאם חושבים אנו חלק של תקיעה כתקיעה שלימה — \u0003תסלק לה בתרתי\u0004 \u0005[תעלה לה,\u0006 תיחשב, \u0005כשתיים]!\u0006 ומשיבים: \u0003פסוקי תקיעתא מהדדי לא פסקינן\u0004 \u0005[לחלק\u0006 \u0003את\u0004 \u0005התקיעות זו מזו אין אנו מחלקים],\u0006 ואיננו יכולים להחליט שתקיעה אחת מתחלקת לשתיים. ועם כל זאת, חלק מן התקיעה — מספיק כדי לצאת בו ידי חובה.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת, ממה ששנינו במשנתנו: \u0003התוקע לתוך הבור או לתוך הדות, או לתוך הפיטס, אם קול שופר שמע\u0004 — \u0003יצא, ואם קול הברה\u0004 (הד) \u0003שמע\u0004 — \u0003לא יצא. ואמאי\u0004 \u0005[ומדוע]\u0006 יהא הדין כך? \u0003ליפוק\u0004 \u0005[שייצא\u0006 ידי חובתו\u0005]\u0006 \u0003בתחילת\u0004 ה\u0003תקיעה מקמי דליערבב קלא\u0004 \u0005[לפני שיתערבב הקול]\u0006 על ידי ההד — אם יוצא ידי חובה רק בחלקה הראשון של התקיעה!","ומשיבים: אכן, מחצית תקיעה איננה נחשבת, כפי שהוכחנו, אלא שיש להבין את דבריו של רבה עצמו באופן אחר. שלא דיבר מענין תקיעה שאחרים שומעים ויוצאים ידי חובתם בשמיעתה, אלא \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003רבה\u0004 — הרי זה \u0003ב\u0004אדם ה\u0003תוקע ועולה לנפשיה\u0004 \u0005[לעצמו]\u0006 שהיה בבור ותקע ויצא מן הבור והמשיך לתקוע.","ותוהים: \u0003אי הכי, מאי למימרא\u0004 \u0005[אם כך מה\u0006 יש \u0005לומר]?\u0006 הלא הדבר הוא פשוט ומדוע יפסל במקרה זה? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003זמנין דמפיק רישיה\u0004 \u0005[לפעמים שמוציא\u0006 את \u0005ראשו]\u0006 מן הבור \u0003ואכתי\u0004 \u0005[ועדיין]\u0006 ה\u0003שופר\u0004 עצמו \u0003ב\u0004תוך ה\u0003בור וקא מיערבב קלא\u0004 \u0005[ומתערבב הקול]\u0006 והוא שומע רק את ההד ולא את קול השופר, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין חוששים, ואם עשה כן — יצא ידי חובתו.","\u0003אמר רב יהודה: בשופר של\u0004 בהמת \u0003עולה\u0004 שהוא הקדש — \u0003לא יתקע, ואם\u0004 בכל זאת עבר \u0003ותקע\u0004 — \u0003יצא\u0004 ידי חובה. \u0003בשופר של שלמים\u0004 — \u0003לא יתקע. ואם\u0004 בכל זאת עבר \u0003ותקע\u0004 — \u0003לא יצא.\u0004","ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 קרבן \u0003עולה בת מעילה היא\u0004 שיש בו קדושה לפני הקרבתו, והמשתמש בה לצורך חולין הריהו מועל בקדשים, ומ\u0003כיון\u0004 שכבר \u0003מעל בה\u0004 בנטילת השופר לשימושו, הרי במעילה זו \u0003נפקא לה\u0004 \u0005[יוצאת היא]\u0006 בכך \u0003לחולין\u0004 ולכן יוצא הוא ידי חובה. ואולם \u0003שלמים דלאו\u0004 \u0005[שלא]\u0006 \u0003בני מעילה נינהו\u0004 \u0005[הם]\u0006 לפני הקרבתם, שאין מעילה בקדשים קלים, אלא באימורים ושאר החלקים העולים לגבוה, וגם זאת רק לאחר זריקת הדם, ולכן מאחר שאינו עובר משום מעילה, אף אינו מוציא לחולין על ידה. וכיון שהשלמים הם הקדש שאסור לעשות בו שימוש (אף שאם עשה, אין בכך משום מעילה), ואם כן \u0003איסורא\u0004 \u0005[איסור]\u0006 \u0003הוא דרכיב בהו\u0004 \u0005[שרוכב,\u0006 מוטל, \u0005עליהם],\u0006 אבל \u0003לא נפקי\u0004 \u0005[יוצאים]\u0006 \u0003לחולין\u0004 על ידי שימוש בהם, ונשארים באיסורם.","\u0003מתקיף ליה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבא,\u0004 שאין סברה זו מספקת: שהרי \u0003אימת\u0004 \u0005[אימתי]\u0006 \u0003מעל\u0004 — \u0003לבתר\u0004 \u0005[אחרי]\u0006 ש\u0003תקע,\u0004 שהרי רק אז עשה שימוש בקדשים, ואם כן \u0003כי קא תקע\u0004 \u0005[כאשר הוא תוקע]\u0006 — \u0003באיסורא תקע\u0004 \u0005[באיסור\u0006 הוא \u0005תוקע],\u0006 אפילו בעולה.","\u0003אלא אמר רבא: אחד זה,\u0004 שופר של עולה, \u0003ואחד זה,\u0004 שופר של שלמים, אם תקע בהם — \u0003לא יצא. הדר\u0004 \u0005[חזר]\u0006 רבא עצמו ו\u0003אמר,\u0004 שיש לדחות את כל הטיעון מעיקרו, ו\u0003אחד זה,\u0004 שופר של עולה, \u0003ואחד זה,\u0004 שופר של שלמים, אם תקע בהם — \u0003יצא.\u0004 וטעמו של דבר: \u0003מצות לא להנות ניתנו.\u0004 כלומר, קיומה של מצוה אינו נחשב כהנאה שנהנה עושה־המצוה, ועל כן שימוש בדבר לצורך מצוה אינו נידון כהנאה ממנו.","בבעיה מקבילה \u0003אמר רב יהודה: בשופר של עבודה זרה לא יתקע\u0004 לכתחילה, \u0003ואם תקע\u0004 — \u0003יצא. בשופר של עיר הנדחת\u0004 (עיר שכל תושביה עבדו עבודה זרה, ודינם שיהרגו הם וכל רכושם ישרף) — \u0003לא יתקע, ואם תקע\u0004 — \u0003לא יצא. מאי טעמא\u0004 \u0005[מה הטעם]\u0006 — \u0003עיר הנדחת כתותי מיכתת שיעוריה\u0004 \u0005[שבור וכתות שיעורה],\u0006 שכיון שהכל עומד לשריפה הרי זה כאילו כבר הכל שרוף ואבוד והריהו נדון כאפר, ואין בו שיעור למצוה.","\u0003אמר רבא: המודר הנאה מחבירו,\u0004 שנדר שלא ליהנות מאדם מסויים — בכל זאת אותו אדם \u0003מותר לתקוע לו\u0004 (עבורו) תקיעה \u0003של מצוה.\u0004 לפי העקרון שקיום מצוה אינו נחשב כהנאה. ומאותו טעם, \u0003המודר הנאה משופר\u0004 מסויים — \u0003מותר לתקוע בו תקיעה של מצוה.\u0004","\u0003ואמר רבא: המודר הנאה מחבירו\u0004 — \u0003מזה עליו מי חטאת\u0004 (מאפר פרה אדומה, לטהרו מטומאת המת) \u0003בימות הגשמים.\u0004 לפי שאז יש רק מצוה בדבר. \u0003אבל לא בימות החמה\u0004 כשיש לו גם הנאה מעצם הזיית המים עליו. \u0003המודר הנאה ממעין\u0004 מסויים — \u0003טובל בו טבילה של מצוה בימות הגשמים, אבל לא בימות החמה,\u0004 שאז יש לו הנאה מעצם הטבילה במים צוננים.","\u0003שלחו ליה\u0004 \u0005[לו]\u0006 מארץ ישראל \u0003לאבוה\u0004 \u0005[לאביו]\u0006 של \u0003שמואל:\u0004 אדם ש\u0003כפאו\u0004 (הכריח אותו) אחר \u0003ו\u0004כתוצאה מכפייה זו \u0003אכל מצה\u0004 — \u0003יצא.\u0004 ומבררים: \u0003כפאו מאן\u0004 \u0005[מי]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003כפאו שד,\u0004 כלומר, שעשה זאת מתוך טירוף הדעת. \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 אדם שהוא \u0003עתים\u0004 (פעמים) \u0003חלים\u0004 (בריא) \u0003עתים שוטה\u0004 (משוגע), \u0003כשהוא חלים\u0004 — \u0003הרי הוא כפקח לכל דבריו,\u0004 הן לענין חובותיו והן לענין אחריותו. ו\u0003כשהוא שוטה הרי הוא כשוטה לכל דבריו,\u0004 ופטור מכל המצוות. ואם כן מי שכפאו שד, איננו אז בגדר חייב במצוות כלל!","\u0003אמר רב אשי: שכפאוהו פרסיים\u0004 לאכול. \u0003אמר רבא:\u0004 זאת אומרת: \u0003התוקע לשיר\u0004 שלא נתכוון לשם מצווה — \u0003יצא\u0004 ידי חובה, שהעיקר הוא בשמיעת התקיעה, ואין כוונת התוקע מעכבת.","ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 \u0003היינו הך\u0004 \u0005[הוא הוא],\u0006 שכיון שאמרו שאדם האוכל בכפיה יוצא ידי אכילת מצוה אף שלא נתכוון לעשות זאת מעצמו, הוא הדין שיצא ידי חובה גם בתקיעה מעין זו! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 שיש חילוק בדברים; \u0003התם\u0004 \u0005[שם]\u0006 \u0003אכול מצה אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אכל\u0004 ועשה את הדבר המעשי שנצטווה עליו,"],["\u0003אבל הכא\u0004 \u0005[כאן]\u0006 בשופר הלא \u0003\"זכרון תרועה\"\u0004 (ויקרא כג, כד) \u0003כתיב\u0004 \u0005[נאמר],\u0006 וזכרון צריך שיהיה מתוך תודעה, \u0003והאי\u0004 \u0005[וזה]\u0006 הלא \u0003מתעסק בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא,\u0004 ואין כוונתו למצוה כלל, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין הכוונה מעכבת אפילו במצוה זו. ומסכמים: \u0003אלמא קסבר\u0004 \u0005[מכאן\u0006 נובע, \u0005שסבר]\u0006 \u0003רבא\u0004 כי \u0003מצות אין צריכות כוונה,\u0004 שיוצא ידי חובה גם אם לא התכוון בשעת עשיית המצוה כדי לצאת.","\u0003איתיביה\u0004 \u0005[הקשו לו]\u0006 ממה ששנינו במשנה: \u0003היה קורא בתורה, והגיע זמן המקרא\u0004 של קריאת שמע, \u0003אם כוון לבו\u0004 — \u0003יצא, ואם לאו\u0004 — \u0003לא יצא.\u0004 ונדייק: \u0003מאי לאו\u0004 \u0005[האם לא],\u0006 \u0003כוון לבו,\u0004 פירושו: \u0003לצאת\u0004 ידי חובה, ואם לא כיוון לבו — לא יצא, משמע שמצוות צריכות כוונה!","ודוחים: \u0003לא,\u0004 הכוונה היתה: אם כיוון לבו \u0003לקרות.\u0004 על תשובה זו תוהים: \u0003לקרות?! הא קא קרי\u0004 \u0005[הרי הוא\u0006 כבר \u0005קורא]\u0006 שהרי לשון המשנה \"היה קורא בתורה\"! ומשיבים: כאן מדובר \u0003ב\u0004אדם שהיה \u0003קורא\u0004 כדי \u0003להגיה\u0004 את הספר, שאינו קורא כדרכו אלא בשינוי הברות, לבדוק אם אומנם הספר מוגה, ואם הזדמן שקרא פרשת שמע וכיוון לקרות כהלכתה — הרי זה יצא.","ומציעים ראיה אחרת, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממשנתנו: \u0003היה עובר אחורי בית הכנסת או שהיה ביתו סמוך לבית הכנסת, ושמע קול שופר או קול מגילה, אם כוון לבו\u0004 — \u0003יצא, ואם לאו\u0004 — \u0003לא יצא. מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה ש\u0003כוון לבו לצאת\u0004 ידי חובה? הרי שמצוות צריכות כוונה!","ודוחים: \u0003לא,\u0004 הכוונה היא אם כיון לבו \u0003לשמוע.\u0004 ותוהים: \u0003לשמוע?! הא\u0004 \u0005[\u0006ו\u0005הרי]\u0006 נאמר במשנה במפורש ש\u0003שמע\u0004 את קול השופר! ומשיבים: \u0003סבור\u0004 הוא, שקול \u0003חמור בעלמא\u0004 \u0005[סתם]\u0006 \u0003הוא\u0004 ששמע, שאם לא ידע השומע שהוא שומע קול שופר אלא סבר שקול אחר הוא — לא יצא, אבל די אכן רק בידיעה שזה קול שופר.","\u0003איתיביה\u0004 \u0005[הקשו לו]\u0006 ממה ששנינו בברייתא: \u0003נתכוון שומע ולא נתכוון משמיע,\u0004 נתכוון \u0003משמיע ולא נתכוון שומע\u0004 — \u0003לא יצא, עד שיתכוון שומע ומשמיע.\u0004 ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 לענין \u0003נתכוון משמיע ולא נתכוון שומע\u0004 יתכן הדבר לפי שיטת רבא — \u0003כסבור,\u0004 קול \u0003חמור בעלמא\u0004 \u0005[סתם]\u0006 \u0003הוא\u0004 ששמע ולא שם לבו לכך, \u0003אלא נתכוון שומע ולא נתכוון משמיע היכי משכחת לה\u0004 \u0005[היאך מוצא אתה אותה]\u0006 \u0003לאו\u0004 \u0005[האם לא]\u0006 הכוונה כשהוא \u0003תוקע לשיר\u0004 ולא למצוה, ואם כן משמע מכאן שהמשמיע צריך להתכוון למצוה!","ודוחים: \u0003דלמא דקא מנבח נבוחי\u0004 \u0005[שמא\u0006 הכוונה היא \u0005כמנבח נביחות],\u0006 כלומר, איננו תוקע כדרך התקיעה הראויה, אלא כמתעסק בלבד בשופר, ועלו בידו תקיעות בלא מתכוון.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אלא מעתה,\u0004 לשיטתך שאין אדם צריך לכוון לצאת ידי מצוה, \u0003הישן בשמיני\u0004 של חג הסוכות, כלומר: לאחר סיום חג הסוכות, בתוך \u0003הסוכה\u0004 — \u0003ילקה,\u0004 שהרי הוא עובר בכך על \"בל תוסיף\" שהוסיף יום אחד על המצוה הכתובה בתורה, שהרי לשיטת רבא גם אם לא התכוון לקיים מצות סוכה אלא ישן בסוכה מטעם אחר — עצם שהייתו בסוכה היא עצמה מצוה, ואם עשאה שלא בזמנה, הרי שעובר משום \"בל תוסיף\"!","\u0003אמר לו\u0004 רבא: \u0003שאני אומר: מצות, אינו עובר עליהן\u0004 ב\"בל תוסיף\", \u0003אלא\u0004 אם היתה תוספת מעשה המצוה \u0003בזמנן,\u0004 אולם אם היתה תוספת זו שלא בזמן הראוי לקיום מצוה זו — אין בכך משום \"בל תוסיף\". והוא הדין כאן בנוגע לישן בסוכה בשמיני שמאחר ובשמיני אין קיימת עוד מצות סוכה, לכן שנתו בסוכה אינה מהווה תוספת למצוה — שכבר אין מצוה בדבר.","\u0003מתיב\u0004 \u0005[מקשה\u0006 על כך\u0005]\u0006 \u0003רב שמן בר אבא,\u0004 ממה ששנינו: \u0003מנין לכהן שעולה לדוכן\u0004 לברך ברכת כהנים, \u0003שלא יאמר: הואיל ונתנה לי\u0004 ה\u0003תורה רשות לברך את ישראל, אוסיף ברכה אחת משלי,\u0004 שאינה מנוסח ברכת הכהנים האמורה בתורה, \u0003כגון\u0004 שמברך: \u0003\"ה' אלהי אבותכם יסף עליכם\"\u0004 (דברים א, יא) — \u0003תלמוד לומר: \"לא תספו על הדבר\u0004 אשר אנכי מצוה אתכם \u0003\"(דברים ד, ב). והא הכא\u0004 \u0005[והרי כאן]\u0006 בכהן, \u0003כיון דבריך ליה\u0004 \u0005[שברך]\u0006 כבר את ברכת הכהנים — \u0003עברה ליה זמניה\u0004 \u0005[לו שעתו\u0006 לברך\u0005]\u0006 ולשיטת רבא לאחר זמן המצוה אין עובר משום \"בל תוסיף\", \u0003ו\u0004בכל זאת \u0003קתני\u0004 \u0005[שנה]\u0006 ש\u0003עבר!\u0004","ומתרצים לשיטת רבא: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה עוסקים אנו]\u0006 — \u0003ב\u0004ש\u0003לא סיים\u0004 את נוסח הברכה הראוי והוסיף לאחריו כרצונו, אלא הוסיף בתוך סדר הברכות.","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 באותו ענין עצמו במפורש לשון \u0003סיים!\u0004 ומתרצים: \u0003סיים ברכה אחת,\u0004 כלומר, את הפסוק הראשון של ברכת כהנים, ועדיין יש לו שתים אחרות לברך.","ומקשים עוד: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 אחרת בענין זה: \u0003סיים כל ברכותיו!\u0004 ומתרצים: \u0003שאני הכא\u0004 \u0005[שונה כאן]\u0006 בברכת כהנים, \u0003כיון דאלו מתרמי ליה צבורא אחרינא\u0004 \u0005[שאם יזדמן לו ציבור אחר]\u0006 — \u0003הדר\u0004 \u0005[\u0006הריהו \u0005חוזר]\u0006 ו\u0003מברך,\u0004 אם כן \u0003כוליה יומא זמניה\u0004 \u0005[כל היום זמנו]\u0006 \u0003הוא\u0004 ולא עבר זמן המצוה, ומכיון שכך, אם הוסיף ברכה מדעתו, אף לאחר שסיים — עדיין הדבר נחשב כבזמנו ועובר משום \"בל תוסיף\".","והעיר רבא: \u0003מנא תימרא\u0004 \u0005[\u0006ו\u0005מניין תאמר]\u0006 סברה זו שמצוה שמותר לעשותה פעם נוספת, כל היום נחשב כזמנה — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 אותם קרבנות \u0003הניתנין במתנה אחת,\u0004 כלומר, שזורקים את דמם על המזבח רק פעם אחת (כגון בכור או מעשר) \u0003שנתערבו ב\u0004דם של קרבנות אחרים ה\u0003נתנין מתנה אחת\u0004 — \u0003ינתנו\u0004 הדמים המעורבים כולם \u0003מתנה אחת.\u0004 נתערבו דמים הניתנים \u0003מתן ארבע,\u0004 שמזים מהם ארבע פעמים על ארבע קרנות המזבח כגון עולה, שנתערבו \u0003ב\u0004אחרים שאף הם ממחוייבי \u0003מתן ארבע\u0004 — \u0003ינתנו\u0004 כולם \u0003במתן ארבע.\u0004","אולם אם נתערבו קרבנות שהם מחוייבי \u0003מתן ארבע ב\u0004אלה שהם מחוייבי \u0003מתן אחת, ר' אליעזר אומר: ינתנו\u0004 כולם \u0003במתן ארבע, ר' יהושע אומר: ינתנו במתן אחת.\u0004","\u0003אמר לו ר' אליעזר\u0004 לר' יהושע \u0003:\u0004 אם כדבריך — \u0003הרי הוא עובר על \"בל תגרע\"\u0004 שהרי מאחר שחייב היה לתת על חלק מהם ארבע מתנות ונתן רק אחת, הרי שעבר בכך על \"בל תגרע\"! \u0003אמר לו ר' יהושע:\u0004 לדבריך \u0003הרי הוא עובר על \"בל תוסיף\"\u0004 לגבי הקרבנות שחובתם רק במתנה אחת!","\u0003אמר לו ר' אליעזר: לא נאמר \"בל תוסיף\" אלא כשהוא בעצמו,\u0004 אם היה נותן קרבן הטעון מתנה אחת בארבע מתנות, אבל בתערובת אין בכך איסור. \u0003אמר לו ר' יהושע:\u0004 אף אני אומר כשיטתך, \u0003לא נאמר \"בל תגרע\" אלא כשהוא בעצמו.\u0004","\u0003ועוד אמר ר' יהושע: כשלא נתת,\u0004 גם אם \u0003עברת על \"בל תגרע\",\u0004 הרי \u0003לא עשית מעשה בידך,\u0004 שהרי זו רק הימנעות מעשייה, ואילו \u0003כשנתת\u0004 כולם במתן ארבעה — \u0003עברת על \"בל תוסיף\" ועשית מעשה בידך.\u0004","עד כאן מהלך הדברים במשנה, ומכאן מנסה רבא להסיק: \u0003והא הכא\u0004 \u0005[והרי כאן]\u0006 \u0003כיון דיהיב ליה\u0004 \u0005[שנתן\u0006 כבר\u0005]\u0006 את ה\u0003מתנה\u0004 האחת של ה\u0003בכור\u0004 כפי הראוי, הלא \u0003עברה ליה לזמניה\u0004 \u0005[עבר זמנו]\u0006 שהרי סיים כבר את מצות נתינת הדם של הבכור, ובכל זאת \u0003קתני\u0004 \u0005[שנה]\u0006 שם ש\u0003עבר משום \"בל תוסיף\", לאו משום דאמרינן\u0004 \u0005[האם לא משום שאומרים אנו]\u0006 נימוק זה: \u0003כיון דאילו מתרמי ליה בוכרא אחרינא\u0004 \u0005[שאם היה מזדמן לו בכור אחר]\u0006 להקריבו — \u0003הדר\u0004 \u0005[היה חוזר]\u0006 ו\u0003מזה מיניה\u0004 \u0005[ממנו],\u0006 אם כן \u0003כוליה יומא זמניה\u0004 \u0005[כל היום זמנו\u0006 הוא\u0005]\u0006 למצות הזייה.","את ההוכחה הזאת דוחים: \u0003ממאי\u0004 \u0005[ממה]\u0006 מסיק אתה שזה כן? \u0003דלמא קסבר\u0004 \u0005[שמא סבר]\u0006 \u0003ר' יהושע\u0004 כי \u0003מצות עובר עליהן\u0004 משום \"בל תוסיף\" \u0003אפילו שלא בזמנן,\u0004 ואין להוכיח איפוא מכאן.","ומסבירים: \u0003אנן הכי קאמרינן\u0004 \u0005[אנו כך אמרנו],\u0006 כלומר, כך רצינו לומר בהבאת משנה זו: \u0003רב שמן בר אבא מאי טעמא שביק מתניתין ומותיב\u0004 \u0005[מה טעם הניח את משנתנו\u0006 לגבי מתנות \u0005והקשה]\u0006 \u0003מברייתא, לותיב ממתניתין\u0004 \u0005[שיקשה ממשנתנו]\u0006 שהרי היא מוסמכת יותר! אלא \u0003מתניתין מאי טעמא\u0004 \u0005[\u0006מ\u0005משנתנו מה טעם]\u0006 \u0003לא מותיב\u0004 \u0005[מקשה]\u0006 — משום שהוא יודע שאפשר להשתמש בנימוק \u0003כיון דאילו מתרמי ליה בוכרא אחרינא בעי מזה מיניה\u0004 \u0005[שאם היה מזדמן לו בכור אחר היה צריך להזות ממנו]\u0006 ולכן \u0003כוליה יומא זמניה\u0004 \u0005[כל היום זמנו]\u0006 \u0003הוא,\u0004 אם כן, ב\u0003ברייתא נמי\u0004 \u0005[גם כן]\u0006 \u0003כיון דאי מתרמי צבורא אחרינא\u0004 \u0005[כיון שאם\u0006 היה \u0005מזדמן ציבור אחר]\u0006 \u0003הדר\u0004 \u0005[היה חוזר]\u0006 ו\u0003מברך\u0004 — \u0003כוליה יומא זמניה\u0004 \u0005[כל היום זמנו הוא].\u0006","ומסבירים: \u0003ורב שמן בר אבא\u0004 שהקשה מן הברייתא ולא מן המשנה מה דעתו? \u0003התם לא סגי דלא יהיב\u0004 \u0005[שם אינו יכול שלא יתן]\u0006 שאם מזדמן לו בכור — חייב הוא לתת מדמו ואם כן ודאי שלענין זה כל היום זמנו, אולם \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003אי בעי\u0004 \u0005[אם רוצה]\u0006 — \u0003מברך, אי בעי\u0004 \u0005[אם רוצה]\u0006 — \u0003לא מברך, גם אם הזדמן ציבור אחר,\u0004 שחובתו היא לברך רק פעם אחת.","\u0003רבא\u0004 עצמו \u0003אמר\u0004 שאין כאן קושיה מתחילה, כי כדי \u0003לצאת\u0004 ידי חובה \u0003לא בעי\u0004 \u0005[אין צורך]\u0006 ב\u0003כוונה,\u0004 אולם אם רוצה אדם \u0003לעבור\u0004 משום \"בל תוסיף\" או \"בל תגרע\" — \u0003בעי\u0004 \u0005[צריך]\u0006 \u0003כוונה\u0004 לצאת ידי חובת מצוה כדי שיעבור בכך.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003מתן דמים ל\u0004דעת \u0003ר' יהושע\u0004 שהוא \u0003לעבור, ו\u0004בכל זאת \u0003לא בעי\u0004 \u0005[אינו צריך]\u0006 \u0003כוונה\u0004 לעבור, שהרי לדעתו אם הוסיף בדמים יותר מן המתנות הראויות הרי הוא עובר! \u0003אלא אמר רבא,\u0004 יש לדחות את מה שאמרנו ולומר בנוסח אחר: כדי \u0003לצאת\u0004 — \u0003לא בעי\u0004 \u0005[אין צורך]\u0006 ב\u0003כוונה,\u0004 אולם \u0003לעבור\u0004 על \"בל תוסיף\", אם היה זה \u0003בזמנו\u0004 — \u0003לא בעי\u0004 \u0005[אין צריך]\u0006 \u0003כוונה\u0004 ועובר, וכפי שאמר ר' יהושע, אבל אם מוסיף או גורע \u0003שלא בזמנו\u0004 כגון ביום שמיני של סוכות — \u0003בעי\u0004 \u0005[צריך]\u0006 \u0003כוונה\u0004 לצאת, ואם אינו מתכוון — אינו עובר.","לעצם ענין כוונת התקיעות מסופר: \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לשמעיה\u0004 \u0005[לשמשו]:\u0006"],["\u0003איכוון\u0004 \u0005[התכוון]\u0006 לתקוע עבורי \u0003ותקע לי.\u0004 ומדייקים: \u0003אלמא קסבר\u0004 \u0005[מכאן שסבר]\u0006 ר' זירא כי \u0003משמיע בעי\u0004 \u0005[צריך]\u0006 \u0003כוונה\u0004 להוציא את השומע.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו במשנתנו: \u0003היה עובר אחורי בית הכנסת, או שהיה ביתו סמוך לבית הכנסת, ושמע קול שופר או קול מגילה, אם כוון לבו\u0004 לצאת — \u0003יצא, ואם לאו\u0004 — \u0003לא יצא.\u0004 ויש להקשות: \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003כוון לבו מאי הוי\u0004 \u0005[מה היה]\u0006 על ידי כך? הלא \u0003היאך לא קא מיכוון אדעתא דידיה\u0004 \u0005[ההוא\u0006 התוקע \u0005איננו מכוון על דעתו שלו,\u0006 של העובר\u0005]\u0006 להוציאו ידי חובה. ואם צריך כוונת משמיע — כיצד הוא יוצא?","ומשיבים: \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003בשליח צבור עסקינן\u0004 \u0005[עוסקים אנו]\u0006 \u0003דדעתיה אכוליה עלמא\u0004 \u0005[שדעתו על כל העולם],\u0006 שאינו תוקע עבור אדם מסויים, אלא כוונתו להוציא את כל הקהל, ולכן כל השומע יוצא ידי חובה בתקיעתו.","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה מברייתא: \u0003נתכוון שומע\u0004 קול התקיעה \u0003ולא נתכוון משמיע\u0004 (התוקע), \u0003נתכוון משמיע ולא נתכוון שומע\u0004 — \u0003לא יצא, עד שיתכוון שומע ומשמיע\u0004 — \u0003קתני\u0004 \u0005[שנה שם]\u0006 \u0003משמיע דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003שומע.\u0004 ונדייק: \u0003מה שומע\u0004 — שהוא \u0003שומע לעצמו\u0004 ומתכוון לצאת בזה, \u0003אף משמיע,\u0004 התוקע, הכוונה היא ש\u0003משמיע\u0004 ומתכוון \u0003לעצמו\u0004 ולא לאחרים, \u0003וקתני\u0004 \u0005[ושנינו]\u0006 שם \u0003לא יצא.\u0004 אבל אם כיוון להשמיע לעצמו — שוב אינו צריך להתכוון להוציא אחרים. וקשה לר' זירא!","ומשיבים: \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 בענין זה, \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003שומע\u0004 — \u0003שומע לעצמו, ומשמיע\u0004 — \u0003משמיע לפי דרכו\u0004 ואינו צריך להתכוון להוציא אדם מסויים. \u0003אמר ר' יוסי: במה דברים אמורים\u0004 — \u0003בשליח צבור, אבל ביחיד\u0004 — \u0003לא יצא, עד שיתכוין שומע ומשמיע.\u0004 וכדברי ר' זירא.","באותו נושא של כוונת הלב, מביאים דברי הכתוב: \u0003\"והיה כאשר ירים משה ידו וגבר ישראל\u0004 וכאשר יניח ידו וגבר עמלק \" (שמות יז, יא), ויש להבין: \u0003וכי ידיו של משה עושות מלחמה\u0004 בהרמתן \u0003או שוברות מלחמה\u0004 בהורדתן? \u0003אלא לומר לך: כל זמן שהיו ישראל מסתכלין כלפי מעלה ומשעבדין את לבם לאביהם שבשמים\u0004 — \u0003היו מתגברים\u0004 במלחמה, \u0003ואם לאו,\u0004 שלא שיעבדו את לבם — \u0003היו נופלים.\u0004","\u0003כיוצא בדבר אתה אומר: \"עשה לך שרף ושים אתו על נס והיה כל הנשוך וראה אתו וחי\"\u0004 (במדבר כא, ח). ויש להבין: \u0003וכי נחש\u0004 זה של נחושת \u0003ממית, או נחש מחיה? אלא, בזמן שישראל מסתכלין כלפי מעלה ומשעבדין את לבם לאביהם שבשמים\u0004 — \u0003היו מתרפאין, ואם לאו היו נימוקים\u0004 (נרקבים) מנשיכות הנחשים.","ולענין הלכה: \u0003חרש שוטה וקטן\u0004 שתקעו — \u0003אין מוציאין את הרבים ידי חובתן. זה הכלל,\u0004 לענין זה, כמו לעניינים אחרים: \u0003כל שאינו מחוייב בדבר\u0004 (בדבר־מצוה) לעשותה — \u0003אינו מוציא את הרבים ידי חובתן.\u0004 אם עושה אותה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הכל חייבין בתקיעת שופר: כהנים ולוים וישראלים, גרים ועבדים משוחררים, וטומטום\u0004 (מי שאין איברי המין ניכרים בו כלל) \u0003ואנדרוגינוס\u0004 (מי שיש בו איברי מין של זכר ונקבה) וכן \u0003מי שחציו עבד וחציו בן חורין.\u0004","\u0003טומטום\u0004 שתקע — \u0003אינו מוציא לא את מינו,\u0004 טומטום כמוהו, שיתכן והתוקע הוא נקבה והשומע הוא זכר, \u0003ולא את שאינו מינו. אנדרוגינוס\u0004 — \u0003מוציא את מינו\u0004 אנדרוגינוס כמותו, שאם הולכים אנו אחר סימני הזכר שבו — הוא הדין לגבי השומע, ואם הולכים אנו אחר סימני הנקבות שבו — הרי הוא הדין לגבי השומע, \u0003אבל לא את\u0004 אדם אחר \u0003שאינו מינו. מי שחציו עבד וחציו בן חורין\u0004 — \u0003אינו מוציא לא את מינו,\u0004 כיון שאין צד העבדות שבו מוציא את צד החירות של השומע, \u0003ו\u0004בודאי \u0003לא את שאינו מינו,\u0004 כלומר, בן חורין גמור. עד כאן לשון הברייתא, ומעתה באים לפרש אותה.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003הכל חייבין בתקיעת שופר כהנים לוים וישראלים.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 \u0003אי הני לא מיחייבי\u0004 \u0005[אם אלה אינם חייבים]\u0006 — \u0003מאן מיחייבי\u0004 \u0005[מי הם החייבים]\u0006 במצוה?!","ומשיבים: \u0003כהנים אצטריכא ליה\u0004 \u0005[הוצרך לו]\u0006 לומר, כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"יום תרועה יהיה לכם\"\u0004 (במדבר כט, א), ובשל כך היינו סבורים לומר: \u0003מאן דליתיה אלא בתקיעה דחד יומא\u0004 \u0005[מי שאינו אלא רק בתקיעה של יום אחד\u0006 בלבד\u0005]\u0006 — \u0003הוא דמיחייב\u0004 \u0005[שמחוייב]\u0006 בתקיעת שופר בראש השנה, \u0003והני כהנים\u0004 \u0005[ואותם הכהנים]\u0006 \u0003הואיל ואיתנהו\u0004 \u0005[וישנם]\u0006 \u0003בתקיעות\u0004 של \u0003כל השנה,\u0004 שתוקעים עם הקרבת הקרבנות במקדש, \u0003דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]:\u0006 \u0003\"ותקעתם בחצצרת על עלתיכם\u0004 ועל זבחי שלמיכם\u0003\"\u0004 (במדבר י, י), \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא ליחייבו\u0004 \u0005[יתחייבו]\u0006 בתקיעת שופר בראש השנה — על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו],\u0006 שאף הכהנים מחוייבים בתקיעת שופר בראש השנה.","על כך תוהים: \u0003מי דמי\u0004 \u0005[האם דומים]\u0006 הדברים? הלא \u0003התם\u0004 \u0005[שם]\u0006 בקרבנות אינה אלא תקיעת \u0003חצוצרות והכא\u0004 \u0005[וכאן]\u0006 מדובר בתקיעת \u0003שופר! אלא,\u0004 יש טעם אחר בדבר; \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 להיאמר, כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003שוה היובל לראש השנה לתקיעה ולברכות,\u0004 הייתי אומר: \u0003מאן דאיתיה\u0004 \u0005[מי שישנו]\u0006 בקיום \u0003מצות היובל\u0004 כולה — \u0003איתיה\u0004 \u0005[ישנו]\u0006 גם \u0003במצוה\u0004 של \u0003ראש השנה, והני\u0004 \u0005[ואותם]\u0006 \u0003כהנים הואיל וליתנהו [ואינם]\u0004 שייכים \u0003במצוה\u0004 של \u0003יובל, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כהנים ולוים מוכרין\u0004 את שדותיהם ובתיהם בערים שניתנו להם אחוזה \u0003לעולם\u0004 ואין הם מוגבלים בדיני היובל, \u0003ו\u0004אף \u0003גואלין\u0004 את קרקעותיהם \u0003לעולם\u0004 ללא הגבלת זמן, ונמצא שאין דיני היובל חלים עליהם כמו על שאר ישראל, ואם כן \u0003אימא\u0004 \u0005[אמור]\u0006 שאף \u0003במצוה\u0004 של \u0003ראש השנה\u0004 ש\u0003לא ליחייבו\u0004 \u0005[יתחייבו] —\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שהם חייבים אף בכך.","שנינו באותה ברייתא, ש\u0003מי שחציו עבד וחציו בן חורין\u0004 — \u0003אינו מוציא לא את מינו ולא את שאינו מינו. אמר רב הונא:\u0004 אף שאינו מוציא אחרים, אם תקע \u0003לעצמו מוציא.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן לרב הונא: מאי שנא\u0004 \u0005[במה שונה,\u0006 מדוע\u0005]\u0006 \u0003לאחרים דלא\u0004 \u0005[אינו]\u0006 יכול להוציא \u0005—\u0006 ש\u0003לא אתי\u0004 \u0005[\u0006יכול \u0005לבוא]\u0006 \u0003צד עבדות ומפיק\u0004 \u0005[ומוציא]\u0006 ידי חובה את \u0003צד\u0004 ה\u0003חרות\u0004 של השומע, שכיון שחציו עבד, הרי כעבד אינו יכול להוציא אחרים ידי חובה, אם כן \u0003לעצמו נמי\u0004 \u0005[גם כן]\u0006 לא יוציא, כי \u0003לא אתי צד עבדות דידיה\u0004 \u0005[שלו]\u0006 \u0003ומפיק\u0004 \u0005[ויוציא]\u0006 ידי חובה את \u0003צד\u0004 ה\u0003חירות דידיה\u0004 \u0005[שלו]\u0006 עצמו.","\u0003אלא אמר רב נחמן: אף לעצמו אינו מוציא.\u0004 ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003מי שחציו עבד וחציו בן חורין\u0004 ותקע בשופר — \u0003אף לעצמו אינו מוציא\u0004 ידי חובה.","כיון שעסקנו פה בענין הוצאה ידי חובה מביאים ברייתא: \u0003תני\u0004 \u0005[שנה]\u0006 החכם \u0003אהבה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' זירא: כל הברכות כולן, אף על פי שיצא\u0004 כבר אדם ידי חובתו בהן — \u0003מוציא\u0004 אחרים ידי חובה, אם מברך עבורם, שכל ישראל ערבים זה לזה. \u0003חוץ מברכת הלחם וברכת היין\u0004 לפניהם ולאחריהם, \u0003שאם לא יצא\u0004 ועדיין הוא חייב לברך — \u0003מוציא\u0004 גם אחרים ידי חובה, \u0003ואם יצא\u0004 כבר — \u0003אינו מוציא,\u0004 כיון שברכות אלה הן על ההנאה עצמה, והמברך אינו יכול לברך אלא אם כן הוא עצמו נהנה. והוא הדין אף לשאר ברכות שאינן באות כחובה אלא בשל הנאת המברך מדבר מסויים, כמו ברכת הריח וכדומה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא:\u0004"],["\u0003ברכת הלחם\u0004 שמברכים \"המוציא\" לפני אכילת \u0003מצה, וברכת היין של קידוש היום\u0004 בשבת ובחג \u0003מהו\u0004 לענין זה? וצדדי השאלה: \u0003כיון\u0004 ש\u0003חובה הוא\u0004 לברך ברכות אלה משום המצוה שבדבר, אם כן הריהו \u0003מפיק\u0004 \u0005[מוציא]\u0006 אחרים ידי חובה אף שהוא עצמו כבר יצא, \u0003או דלמא\u0004 \u0005[שמא]\u0006 כיון שה\u0003ברכה\u0004 עצמה \u0003לאו\u0004 \u0005[לא]\u0006 \u0003חובה היא\u0004 \u0005[חובה],\u0006 שהחובה היא באכילה ושתיה, אם כן כיון שכבר יצא ידי חובתו ועיקר הברכה אינה אלא על הנאת האכילה ושתיה — שוב אינו יכול להוציא אחרים. ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר, שכן \u0003אמר רב אשי: כי הוינן בי\u0004 \u0005[כאשר היינו\u0006 לומדים \u0005בבית\u0006 אצל\u0005]\u0006 \u0003רב פפי, הוה מקדש לן\u0004 \u0005[היה עושה קידוש עבורנו]\u0006 \u0003וכי הוה אתי אריסיה מדברא הוה מקדש להו\u0004 \u0005[וכאשר היו באים אריסיו מן השדה היה מקדש להם],\u0006 הרי שרשאי אדם לחזור ולקדש ואף לברך על היין, אף כאשר יצא כבר ידי חובה.","","","","","","","","","","","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003לא יפרוס אדם פרוסה\u0004 ויברך \u0003לאורחין, אלא אם כן\u0004 הריהו \u0003אוכל עמהם\u0004 ומברך בעצם עבור עצמו, \u0003אבל פורס הוא לבניו ולבני ביתו\u0004 ומברך, \u0003כדי לחנכן במצות,\u0004 שידעו כיצד מברכים. \u0003ובהלל ובמגילה אף על פי שיצא\u0004 ידי חובה — יכול לקרוא בשנית ו\u0003מוציא\u0004 בכך אחרים ידי חובתם. \u0003יום טוב של ראש השנה שחל להיות בשבת\u0004 — \u0003במקדש היו תוקעין\u0004 בשופר, כבכל ראש השנה, \u0003אבל לא\u0004 תוקעים \u0003במדינה\u0004 מחוץ לתחום המקדש. \u0003משחרב בית המקדש, התקין רבן יוחנן בן זכאי שיהו תוקעין\u0004 אף בשבת \u0003בכל מקום שיש בו בית דין\u0004 של עשרים ושלושה דיינים. \u0003אמר ר' אלעזר: לא התקין רבן יוחנן בן זכאי\u0004 תקנה זו \u0003אלא ביבנה בלבד,\u0004 שבה שכנה באותו זמן הסנהדרין הגדולה של שבעים ואחד, אבל לא במקום אחר. \u0003אמרו לו: אחד יבנה, ואחד כל מקום שיש בו בית דין.\u0004 ומוסיפים: \u0003ועוד זאת היתה ירושלים\u0004 בעודה בבניינה \u0003יתירה על יבנה\u0004 שגם לאחר תקנת רבן יוחנן בן זכאי היה הבדל בדין: \u0003שכל עיר\u0004 שהיא \u0003רואה\u0004 את ירושלים \u0003ושומעת\u0004 תקיעת שופר מירושלים \u0003וקרובה\u0004 אליה \u0003ויכולה לבוא\u0004 לירושלים — \u0003תוקעין\u0004 אף בה בשופר, שהיא כנספחת לירושלים. \u0003וביבנה לא היו תוקעין אלא בבית דין בלבד,\u0004 ולא מחוץ לתחום בית הדין. שואלים: \u0003מנא הני מילי\u0004 \u0005[מנין דברים אלה]\u0006 שבשבת לא יתקעו בשופר? \u0003אמר ר' לוי בר לחמא אמר ר' חמא בר חנינא: כתוב אחד אומר\u0004 לגבי ראש השנה: \u0003\"שבתון זכרון תרועה\"\u0004 (ויקרא כג, כד), משמע שיש רק להזכיר את ענין התרועה, אבל אין תוקעים בפועל. \u0003וכתוב אחד אומר: \"יום תרועה יהיה לכם\"\u0004 (במדבר כט, א) — תרועה ממש, והדברים לכאורה סותרים! ויש לתרץ, \u0003לא קשיא\u0004 \u0005[אינו קשה];\u0006 \u0003כאן\u0004 — \u0003ביום טוב שחל להיות בשבת\u0004 אין תוקעים, ויש רק זכרון תרועה, \u0003כאן\u0004 — \u0003ביום טוב שחל להיות בחול\u0004 — תוקעים. \u0003אמר רבא\u0004 והקשה על טעם זה: \u0003אי מדאורייתא\u0004 \u0005[אם מן התורה]\u0006 \u0003היא\u0004 חלוקה זו בין שבת לחול, אם כן, \u0003במקדש היכי תקעינן\u0004 \u0005[כיצד תוקעים אנו]?\u0006 שאם הדבר אסור מן התורה כיצד הותר במקדש? \u0003ועוד:\u0004 תקיעת שופר \u0003הא לאו\u0004 \u0005[הרי לא]\u0006 \u0003מלאכה היא, דאיצטריך קרא למעוטי\u0004 \u0005[שהצטרך הכתוב למעט\u0006 אותה\u0005],\u0006 שאף שאסרוה חכמים בשבת, אינה בכלל מלאכה האסורה מן התורה, ואין מסתבר שבא הכתוב לאוסרה עלינו. \u0003דתנא דבי\u0004 \u0005[ש\u0006כן \u0005שנה החכם מבית\u0006 מדרשו\u0005]\u0006 של \u0003שמואל\u0004 ברייתא זו: נאמר, \u0003\"כל מלאכת עבדה לא תעשו\"\u0004 (במדבר כט, א), \u0003יצתה\u0004 מכללן \u0003תקיעת שופר ורדיית הפת\u0004 מן התנור \u0003שהיא חכמה\u0004 ואומנות, אבל \u0003אינה מלאכה\u0004 ואינה בגדר איסורי המלאכה. ואם כן, אין לפרש שתקיעת שופר אסורה מן התורה. \u0003אלא אמר רבא\u0004 יש לדחות את ההסבר הזה, ולומר: \u0003מדאורייתא מישרא שרי\u0004 \u0005[מן התורה מותר]\u0006 לתקוע בראש השנה אף כשחל בשבת, \u0003ורבנן הוא דגזור ביה\u0004 \u0005[וחכמים הם שגזרו בו,\u0006 בדבר זה\u0005]\u0006 \u0003כ\u0004פי הסברו של \u0003רבה.\u0004 ש\u0003אמר רבה: הכל חייבין בתקיעת שופר, ו\u0004אולם \u0003אין הכל בקיאין בתקיעת שופר\u0004 כיצד לתקוע, \u0003גזירה שמא יטלנו\u0004 את השופר \u0003בידו וילך אצל הבקי ללמוד,\u0004 ושמא ישכח \u0003ויעבירנו ארבע אמות ברשות הרבים\u0004 בשבת, ונמצא מחלל את השבת. ולכן גזרו שלא יתקעו בשבת. \u0003והיינו טעמא\u0004 \u0005[וזהו הטעם]\u0006 של \u0003לולב,\u0004 שאין נוטלים אותו בשבת, \u0003והיינו טעמא\u0004 \u0005[וזהו הטעם]\u0006 של \u0003מגילה,\u0004 מגילת אסתר, שאין קוראים בה בשבת, הכל מתוך החשש שמא יטלטלו את אלה ארבע אמות ברשות הרבים. שנינו במשנה: \u0003משחרב בית המקדש התקין רבן יוחנן בן זכאי\u0004 שיתקעו ביבנה. מעשה זה מובא בפירוט יתר בברייתא הבאה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003פעם אחת חל ראש השנה להיות בשבת, והיו כל הערים מתכנסין\u0004 למקום הסנהדרין ביבנה לתפילת החג. \u0003אמר להם רבן יוחנן בן זכאי לבני בתירה,\u0004 שהיו גדולי הדור: \u0003נתקע\u0004 כמו שהיו נוהגים במקדש! \u0003אמרו לו: נדון\u0004 אם מותר הדבר או לא. \u0003אמר להם:\u0004 מוטב ש\u0003נתקע, ואחר כך\u0004 כשיהיה פנאי \u0003נדון\u0004 בדבר. \u0003לאחר שתקעו, אמרו לו: נדון! אמר להם: כבר נשמעה קרן ביבנה,\u0004 שכבר נשמעה תקיעת השופר, \u0003ואין משיבין לאחר מעשה.\u0004 שאם כבר נעשה מעשה ברבים, אין ראוי לבוא להתדיין ולומר שעשו זאת בטעות. עוד שנינו במשנה: \u0003אמר ר' אלעזר: לא התקין רבן יוחנן בן זכאי\u0004 שיתקעו בראש השנה שחל להיות בשבת מחוץ לגבולות המקדש, \u0003אלא ביבנה בלבד. אמרו לו: אחד יבנה ואחד כל מקום שיש בו בית דין.\u0004 ושואלים: \u0003דעה זו שאמרו לו\u0004 החכמים לר' אלעזר הלא \u0003היינו\u0004 \u0005[היא היא]\u0006 דעת ה\u0003תנא קמא\u0004 \u0005[הראשון],\u0006 ומה טעם לחזור ולספר שאמרו את דברי התנא הראשון?","","","ומשיבים: \u0003איכא בינייהו\u0004 \u0005[\u0006יש \u0005ביניהם\u0006 הבדל\u0005]\u0006 בין שיטת התנא הראשון במשנתנו, והשיטה שלפיה אמרו חכמים דבריהם לר' אלעזר — לגבי \u0003בי דינא דאקראי\u0004 \u0005[בית דין של ארעי],\u0006 בית דין שאיננו קבוע במקום מסויים, שלדעת תנא קמא תוקעים אף שם ולדעת החכמים שאמרו לו — אין לתקוע אלא במקום בית דין קבוע, כמו יבנה בשעתה.","שנינו במשנה ש\u0003אמרו לו\u0004 החכמים לר' אלעזר: \u0003אחד יבנה ואחד כל מקום שיש בו בית דין. אמר רב הונא:\u0004"],["\u0003ועם בית דין\u0004 תוקעים. דבריו הקצרים הללו של רב הונא לא הובנו, ומסבירים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ועם בית דין\"\u0004 — כלומר \u0003בפני בית דין\u0004 במקום בו יושבים חברי בית דין, \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003שלא בפני בית דין\u0004 — ש\u0003לא.\u0004","\u0003מתיב\u0004 \u0005[מקשה\u0006 על כך\u0005]\u0006 \u0003רבא\u0004 ממה ששנינו: \u0003ועוד זאת היתה ירושלים\u0004 בבניינה \u0003יתירה על יבנה,\u0004 ויש לשאול: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005],\u0006 מה דיוק הלשון \u0003\"ועוד זאת\"? אילימא כדקתני\u0004 \u0005[אם תאמר\u0006 שיש להבין רק \u0005כפי ששנינו\u0006 במשנה\u0005],\u0006 אם כן, \u0003\"זאת\" מיבעי ליה\u0004 \u0005[הוצרך לו\u0006 לומר\u0005]\u0006 שהרי זה הוא ההבדל שבו מדובר. \u0003אלא\u0004 תאמר: ש\u0003בירושלים תוקעין יחידין וביבנה אין תוקעין יחידין\u0004 אלא שליח צבור בלבד.","\u0003ו\u0004אולם האם \u0003ביבנה אין תוקעין יחידין? והא\u0004 \u0005[והרי]\u0006 \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב יצחק בר יוסף\u0004 מארץ ישראל לבבל, מסר: \u0003כי מסיים שליחא דציבורא\u0004 \u0005[כאשר היה מסיים שליח הציבור]\u0006 את ה\u0003תקיעה ביבנה לא שמע איניש\u0004 \u0005[אדם]\u0006 \u0003קל אוניה מקל תקועיא דיחידאי\u0004 \u0005[קול אזניו מקול תקיעות היחידים],\u0006 שלאחר שתקעו להוציא את הציבור כולו היו רבים מוציאים שופרותיהם ותוקעים, והיה הרעש גדול מאד. ולענייננו למדנו שלא רק שליח בית דין תקע ביבנה, אלא הכל תוקעים.","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 כך נבין את הדבר: ש\u0003בירושלים תוקעין בין ב\u0004שעות שהן ה\u0003זמן\u0004 הקבוע למושב \u0003בית דין\u0004 (עד חצות היום) \u0003ובין שלא בזמן\u0004 מושב \u0003בית\u0004 ה\u0003דין, ו\u0004אילו \u0003ביבנה, בזמן\u0004 מושב \u0003בית\u0004 ה\u0003דין\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003שלא בזמן\u0004 מושב \u0003בית\u0004 ה\u0003דין\u0004 — \u0003לא. הא\u0004 \u0005[הרי]\u0006 נלמד מכאן כי \u0003בזמן\u0004 מושב \u0003בית\u0004 ה\u0003דין מיהא\u0004 \u0005[על כל פנים]\u0006 \u0003תוקעין\u0004 ביבנה \u0003ואפילו שלא בפני בית\u0004 ה\u0003דין\u0004 עצמו. ואם כן, מדיוק זה קשה לדברי רב הונא האומר כי ביבנה היו תוקעים דווקא לפני בית הדין!","את הדיוק הזה דוחים: \u0003לא,\u0004 יש לפרש: ש\u0003אילו בירושלים\u0004 היו \u0003תוקעין בין בפני בית\u0004 ה\u0003דין בין שלא בפני בית\u0004 ה\u0003דין, ו\u0004אילו \u0003ביבנה\u0004 אינו כן אלא \u0003בפני בית דין\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003שלא בפני בית דין\u0004 — \u0003לא.\u0004","\u0003איכא דמתני להא\u0004 \u0005[יש שהיו שונים,\u0006 גורסים, את אימרתו \u0005זו]\u0006 של \u0003רב הונא\u0004 לא על משנתנו אלא \u0003אהא\u0004 \u0005[על\u0006 דבר \u0005זה]:\u0006 שאת הכתוב \u0003\"ביום הכפרים תעבירו שופר בכל ארצכם\"\u0004 (ויקרא כה, ט) — \u0003מלמד שכל יחיד ויחיד חייב לתקוע,\u0004 ועל כך \u0003אמר רב הונא: \"ועם בית דין\".\u0004 ומבררים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003ועם בית דין\u0004 — \u0003בזמן\u0004 מושב \u0003בית\u0004 ה\u0003דין, לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003שלא בזמן\u0004 מושב \u0003בית\u0004 ה\u0003דין,\u0004 ש\u0003לא.\u0004","ועל כך \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבא\u0004 ממה ששנינו: \u0003תקיעת ראש השנה ויובל דוחה את השבת בגבולין, איש וביתו.\u0004 ולפני שאנו מבררים את הדברים לגופם שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"איש וביתו\"; אילימא\u0004 \u0005[אם תרצה\u0006 לפרש\u0005]\u0006 כדרך שאנו מפרשים כרגיל, \u0003איש ואשתו\u0004 — אי אפשר לומר כן, שכן \u0003איתתא מי מחייבא\u0004 \u0005[האשה האם היא מחוייבת]\u0006 בתקיעת שופר? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003מצות עשה שהזמן גרמא היא, וכל מצות עשה שהזמן גרמא\u0004 — \u0003נשים פטורות.\u0004","\u0003אלא לאו\u0004 \u0005[האם לא\u0006 הכוונה\u0005]\u0006 לומר \u0003איש בביתו,\u0004 כלומר, \u0003ואפילו שלא בזמן\u0004 מושב \u0003בית\u0004 ה\u0003דין!\u0004 את הדיוק הזה דוחים: \u0003לא, לעולם\u0004 תפרש שאדם מותר לתקוע גם בביתו אבל רק \u0003בזמן\u0004 מושב \u0003בית\u0004 ה\u0003דין.\u0004 ושיטתו היא, שביובל כל יחיד ויחיד תוקע ואפילו שלא בפני בית הדין, אולם בראש השנה, אין ליחיד לתקוע אלא בפני בית הדין בלבד.","\u0003מתיב\u0004 \u0005[מקשה\u0006 על כך\u0005]\u0006 \u0003רב ששת\u0004 ממקור אחר, שנינו: \u0003שוה היובל לראש השנה\u0004 הן \u0003ל\u0004ענין \u0003תקיעה ו\u0004הן \u0003ל\u0004ענין ה\u0003ברכות, אלא שביובל תוקעין\u0004 בו \u0003בין בבית דין שקידשו בו את החדש ובין בבית דין שלא קידשו בו את החדש, וכל יחיד ויחיד חייב לתקוע, ו\u0004אילו \u0003בראש השנה לא היו תוקעין אלא בבית דין שקידשו בו את החדש, ואין כל יחיד ויחיד חייב לתקוע.\u0004","ונברר: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אין כל יחיד ויחיד חייב לתקוע\"? אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003ביובל תוקעין יחידין ובראש השנה אין תוקעין יחידין\u0004 כלל — \u0003והא כי אתא\u0004 \u0005[והרי כאשר בא]\u0006 \u0003רב יצחק בר יוסף\u0004 מארץ ישראל לבבל, \u0003אמר: כי הוה\u0004 \u0005[כאשר היה]\u0006 \u0003מסיים שליחא דציבורא תקיעתא\u0004 \u0005[שליח הציבור את התקיעות]\u0006 \u0003ביבנה\u0004 בראש השנה — \u0003לא שמע איניש\u0004 \u0005[אדם]\u0006 \u0003קל אוניה מקל תקועיא דיחידאי\u0004 \u0005[קול אזניו מקול תקיעות היחידים],\u0006 משמע שאף בראש השנה תוקעים יחידים.","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 כך הכוונה: ש\u0003אילו ביובל תוקעין בין בזמן\u0004 מושב \u0003בית\u0004 ה\u0003דין בין שלא בזמן\u0004 מושב \u0003בית\u0004 ה\u0003דין, ו\u0004אילו \u0003בראש השנה, בזמן\u0004 מושב \u0003בית\u0004 ה\u0003דין\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003שלא בזמן\u0004 מושב \u0003בית\u0004 ה\u0003דין\u0004 — \u0003לא. קתני מיהת\u0004 \u0005[שנינו על כל פנים],\u0006 כי \u0003ביובל\u0004 תוקעים \u0003בין בזמן\u0004 מושב \u0003בית\u0004 ה\u0003דין בין שלא בזמן\u0004 מושב \u0003בית\u0004 ה\u0003דין,\u0004 ולא כדברי רב הונא!","ודוחים: \u0003לא, לעולם\u0004 תפרש כי תוקעים רק \u0003בזמן\u0004 מושב \u0003בית\u0004 ה\u0003דין. והכי קתני\u0004 \u0005[וכך שנה],\u0006 כך צריך להבין: \u0003\"ביובל\", בזמן\u0004 מושב \u0003בית\u0004 ה\u0003דין\u0004 — \u0003תוקעין בין בפני בית דין בין שלא בפני בית דין,\u0004 ואילו \u0003בראש השנה תוקעין בזמן\u0004 מושב \u0003בית\u0004 ה\u0003דין,\u0004 ודווקא \u0003בפני בית דין. איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 בשם חכם אחר כשיטת רב הונא: \u0003אמר ר' חייא בר גמדא אמר ר' יוסי בן שאול אמר רבי: אין תוקעין\u0004 היחידים ביום הכיפורים ביובל \u0003אלא כל זמן שבית\u0004 ה\u0003דין יושבין\u0004 במקומם, כלומר, בזמן מושב בית הדין.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' זירא\u0004 ובירר פרט בענין זה: \u0003ננערו\u0004 חברי בית הדין \u0003לעמוד\u0004 משנסתיים זמן מושב בית הדין \u0003ולא עמדו\u0004 עדיין, מפני שהתעכבו משום מה, \u0003מהו?\u0004 האם \u0003בית דין יושבין בעינן\u0004 \u0005[צריכים אנו]\u0006 — \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 דבר זה, שהרי עדיין יושבים הם שם, \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003זמן\u0004 מושב \u0003בית\u0004 ה\u0003דין בעינן\u0004 \u0005[צריכים אנו]\u0006 וזה כבר \u0003ליכא\u0004 \u0005[אין]?\u0006 לשאלה זו לא נמצאה תשובה. והושארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","שנינו במשנה: \u0003ועוד זאת היתה ירושלים\u0004 בבניינה \u0003יתירה על יבנה,\u0004 שכל עיר שהיא רואה ושומעת וקרובה לירושלים ויכולה לבוא — תוקעים בה. את הדברים הללו, הנראים לכאורה זהים, מסבירים: \u0003רואה\u0004 — כוונתו \u0003פרט\u0004 לעיר ש\u0003יושבת בנחל\u0004 בגיא עמוק ואינה יכולה לראות למרחוק.","\u0003שומעת\u0004 — \u0003פרט ליושבת בראש ההר,\u0004 שאמנם רואה את ירושלים מרחוק, אבל רחוקה היא מכדי לשמוע. \u0003קרובה\u0004 — כוונתו \u0003פרט ליושבת חוץ לתחום\u0004 שיש שטח ריק בינה ובין ירושלים עצמה יותר מתחום שבת. \u0003ויכולה לבוא\u0004 — \u0003פרט ל\u0004זו ש\u0003מפסיק לה נהרא\u0004 \u0005[נהר]\u0006 בין אותה עיר וירושלים, שאף שהיא קרובה, כיון שאי אפשר לעבור את הנהר — אינה יכולה לבוא.","כיון שהזכרנו את תקנת רבן יוחנן בן זכאי בענין התקיעה, מזכירים תקנות אחרות שלו: \u0003בראשונה\u0004 בזמן שהיה בית המקדש קיים, \u0003היה הלולב ניטל במקדש שבעה\u0004 ימים, כל ימי חג הסוכות, \u0003ובמדינה\u0004 (מחוץ למקדש) רק \u0003יום אחד,\u0004 היום הראשון של החג. \u0003משחרב בית המקדש התקין רבן יוחנן בן זכאי שיהא לולב ניטל במדינה שבעה\u0004 ימים, כדי לעשות \u0003זכר למקדש.\u0004","ועוד התקין רבן יוחנן בן זכאי, שבזמן שבית המקדש היה קיים, הרי מדין התורה, מאותה שעה שהוקרב העומר ביום שישה עשר בניסן — הותרה כל התבואה החדשה באכילה, ורבן יוחנן בן זכאי התקין לאחר חורבן הבית \u0003שיהא יום הנף\u0004 (יום הנפת התבואה) הוא יום שישה עשר בניסן \u0003כולו אסור\u0004 באכילת תבואה חדשה, עד לערב.","\u0003ומנלן דעבדינן\u0004 \u0005[ומניין לנו שאנו\u0006 צריכים \u0005לעשות]\u0006 \u0003זכר למקדש?\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"כי אעלה ארכה לך וממכותיך ארפאך נאם ה' כי נדחה קראו לך ציון היא דרש אין לה\"\u0004 (ירמיה ל, יז), \u0003מכלל\u0004 הדברים את לומד \u0003דבעיא\u0004 \u0005[שצריכה]\u0006 ירושלים \u0003דרישה,\u0004 שידרשו ויזכרו אותה.","\u0003שיהא יום הנף\u0004 לאחר חורבן בית המקדש, \u0003כולו אסור\u0004 באכילת תבואה חדשה. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003מהרה יבנה בית המקדש, ויאמרו\u0004 אנשים: \u0003אשתקד\u0004 \u0005[בשנה שעברה]\u0006 לפני שנבנה הבית \u0003מי\u0004 \u0005האם\u0006 \u0003לא אכלנו\u0004 כבר מן התבואה החדשה \u0003בהאיר מזרח,\u0004 מיד כשהתחיל בוקרו של יום שישה עשר בניסן — \u0003עכשו נמי ניכול\u0004 \u0005[גם כן נאכל]\u0006 מיד בבוקר יום השישה עשר,","\u0003ולא ידעי\u0004 \u0005[ואינם יודעים]\u0006 \u0003דאשתקד\u0004 \u0005[שבשנה שעברה]\u0006 \u0003לא הוה\u0004 \u0005[היה]\u0006 קרבן ה\u0003עומר\u0004 ולכן מיד כש\u0003האיר מזרח\u0004 — \u0003התיר\u0004 את התבואה החדשה. ואילו \u0003השתא דאיכא\u0004 \u0005[עכשיו,\u0006 משנבנה בית המקדש, \u0005שיש]\u0006 קרבן \u0003עומר\u0004 — \u0003עומר\u0004 בלבד הוא ש\u0003מתיר,\u0004 ויש להמתין עד שיקריבוהו.","ומבררים: \u0003דמיבני אימת\u0004 \u0005[שנבנה\u0006 בית המקדש \u0005מתי]?\u0006 \u0003אילימא דאיבני בשיתסר\u0004 \u0005[אם תאמר שנבנה\u0006 בית המקדש \u0005ביום שישה עשר\u0006 בניסן\u0005]\u0006 עצמו, \u0003הרי\u0004 ביום שישה עשר לא יכלו עוד להקריב את העומר, ונמצא שמש \u0003האיר\u0004 ה\u0003מזרח התיר,\u0004 ואין לחשוש.","\u0003אלא\u0004 תאמר \u0003דאיבני בחמיסר\u0004 \u0005[שנבנה בחמישה עשר\u0006 בניסן\u0005]\u0006 או קודם לכן, והרי אז \u0003מחצות היום ולהלן\u0004 (והלאה) \u0003לשתרי\u0004 \u0005[שיהא מותר],\u0006 \u0003דהא תנן\u0004 \u0005[שהרי שנינו\u0006 במשנה\u0005]\u0006 באותו ענין: \u0003הרחוקין\u0004 מירושלים שאינם יודעים מתי הוקרב העומר — \u0003מותרין\u0004 באכילת תבואה חדשה \u0003מחצות היום ולהלן, לפי\u0004 שהם יכולים לסמוך \u0003שאין בית דין מתעצלים בו,\u0004 בקרבן העומר, להקריבו לאחר שעה זו. ואם כן, גם כשיבנה בית המקדש ודאי לא יאחרו את הקרבת העומר מחצי היום ותהא התבואה החדשה מותרת גם כעת משעה זו!","ומשיבים: \u0003לא נצרכא\u0004 \u0005[הוצרכה]\u0006 לומר אלא \u0003דאיבני\u0004 \u0005[שנבנה]\u0006 בית המקדש \u0003בחמיסר\u0004 \u0005[ביום חמישה עשר\u0006 בניסן\u0005]\u0006 \u0003סמוך לשקיעת החמה,\u0004 ועד שימצאו תבואה לקצור, ועד שיקצרוה, יעבור זמן רב, ולא יספיקו להקריב את קרבן העומר בשעתו, ושמא יקריבוהו בסוף יום השישה עשר. \u0003אי נמי\u0004 \u0005[או גם כן],\u0006 \u0003דאיבני בליליא\u0004 \u0005[שנבנה בלילה]\u0006 או לשישה עשר בניסן, ואי אפשר להכינו אלא במשך היום.","\u0003אמר רב נחמן בר יצחק: רבן יוחנן בן זכאי\u0004"],["\u0003בשיטת ר' יהודה אמרה\u0004 להלכה זו, ש\u0003אמר:\u0004 מה שנאמר, \"ולחם וקלי וכרמל לא תאכלו \u0003עד עצם היום הזה\"\u0004 (ויקרא כג, יד), שלא תאמר שבהאיר המזרח מותר, אלא \u0003עד עצמו של יום\u0004 אסור. \u0003וקסבר\u0004 \u0005[וסבור הוא]\u0006 בהבנת הדברים שהכתוב \u0003\"עד\"\u0004 כוונתו: \u0003ועד בכלל\u0004, תאריך זה עצמו בכלל. נמצא שמדין תורה אסורה אכילת חדש עד סוף יום שישה עשר בניסן, אלא שכשבית המקדש קיים אפשר להתחיל לאכול מזמן הקרבת העומר.","ומקשים: \u0003ומי סבר לה כוותיה\u0004 \u0005[והאם סבר\u0006 ר' יהודה \u0005כמותו]\u0006 כרבן יוחנן בן זכאי? \u0003והא מפליג פליג עליה\u0004 \u0005[והרי חולק הוא עליו],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003משחרב בית המקדש התקין רבן יוחנן בן זכאי שיהא יום הנף כולו אסור. אמר ר' יהודה: והלא מן התורה הוא אסור, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"עד עצם היום הזה\"!\u0004","ודוחים: \u0003התם\u0004 \u0005[שם]\u0006 — \u0003ר' יהודה הוא דקא טעי\u0004 \u0005[שטעה]\u0006 בהבנת הדברים: \u0003איהו\u0004 \u0005[הוא]\u0006 ר' יהודה \u0003סבר\u0004 כי \u0003רבן יוחנן בן זכאי מדרבנן קאמר\u0004 \u0005[מדברי חכמים אמר]\u0006 שיש לגזור על אכילת החדש ביום שישה עשר, \u0003ולא היא\u0004 (ואינו כן), אלא \u0003מדאורייתא קאמר\u0004 \u0005[מ\u0006דין \u0005התורה אמר].\u0006","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 לשון \u0003\"התקין\" קתני\u0004 \u0005[שנינו],\u0006 ולשון \"התקין\" פירושו, שאין זה מן הדין אלא תקנה חדשה! ומסבירים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"התקין\"\u0004 — \u0003דרש\u0004 את הכתוב באופן זה \u0003והתקין\u0004 שכך יעשו מכאן ולהבא, כי בזמן שבית המקדש היה קיים לא הוצרכו לדרשה זו של הכתוב.","\u0003בראשונה,\u0004 בתחילת ימי הבית, \u0003היו מקבלין עדות החדש כל היום\u0004 בראש השנה, שאם הגיעו העדים ממקום רחוק, והעידו שראו את מולד הירח בלילה הקודם — היו קובעים יום זה כיום טוב.","\u0003פעם אחת נשתהו העדים מלבוא\u0004 והגיעו בשעה מאוחרת מאוד \u0003ונתקלקלו הלוים בשיר,\u0004 כיון שלא ידעו אם יום טוב הוא או יום חול, ואז \u0003התקינו\u0004 חכמים \u0003שלא יהו מקבלין\u0004 עדות כל אותו יום \u0003אלא עד\u0004 שעת \u0003המנחה.\u0004","\u0003ואם באו עדים מן המנחה ולמעלה\u0004 (והלאה) עד הלילה — \u0003נוהגין אותו היום קודש\u0004 בקדושת החג ובאיסור מלאכה, כפי שנהגו בו עד לאותה שעה מחמת הספק שמא אכן יבואו עדים במהלך היום ונמצא שהוא אכן ראש השנה. וזאת כדי שלא יבואו העם לזלזל בקדושת החג בשנה הבאה, בכך שיאמרו שאין לנהוג בו איסור מלאכה, שהרי בשנה שעברה נהגו בו איסור מלאכה ובטעות נהגו כן, שהרי משעת המנחה והלאה חזרו ונהגו בו כביום חול. וכמו כן נוהגים בו אף \u0003למחר קודש\u0004 כפי הראוי, לפי שלא הוקבע החודש בזמנו.","\u0003משחרב בית המקדש\u0004 ששוב לא היה מקום לתקנה זו \u0003התקין רבן יוחנן בן זכאי שיהו מקבלין עדות החדש כל היום.\u0004","שואלים: \u0003מה קלקול קלקלו הלוים בשיר\u0004 כלומר, מה אירע שם? \u0003הכא תרגימו\u0004 \u0005[כאן\u0006 בבבל \u0005הסבירו]:\u0006 \u0003שלא אמרו שירה כל עיקר,\u0004 כיון שלא ידעו איזה שירה עליהם לומר — אם שירה שאומרים ביום חול או שבחג. \u0003ר' זירא אמר: שאמרו שירה של\u0004 יום \u0003חול עם\u0004 הקרבת \u0003תמיד של בין הערבים\u0004 ולאחר העדות התברר שהיו צריכים לומר שירה של חג.","\u0003אמר לו ר' זירא לאהבה בריה\u0004 \u0005[בנו]:\u0006 \u0003פוק תני להו\u0004 \u0005[\u0006לך \u0005צא ושנה להם]\u0006 לחכמים בני בבל האומרים שלא אמרו שירה כלל, את לשון ברייתא זו, וממנה ילמדו שהיו שרים של חול. ששנינו: \u0003התקינו שלא יהו מקבלין עדות החדש אלא כדי שיהא שהות ביום להקריב תמידין ומוספין\u0004 של חג \u0003ונסכיהם, ולומר שירה שלא בשיבוש.\u0004 ומברייתא זו נדייק: \u0003אי אמרת בשלמא אמור\u0004 \u0005[נניח אם אומר אתה\u0006 כדברי \u0005שאמרו]\u0006 אז \u0003שירה של חול\u0004 — \u0003היינו דאיכא\u0004 \u0005[זהו שיש]\u0006 \u0003שיבוש, אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 \u0003לא אמור\u0004 \u0005[אמרו]\u0006 שירה \u0003כלל\u0004 — \u0003מאי\u0004 \u0005[מה]\u0006 \u0003שיבוש איכא\u0004 \u0005[יש] —\u0006 הרי לכאורה לשון שיבוש משמעה שעושים דבר שלא כראוי!","ודוחים: מכאן אין ראיה, \u0003כיון\u0004 ש\u0003לא אמור\u0004 \u0005[אמרו]\u0006 שירה \u0003כלל\u0004 — \u0003אין לך שיבוש גדול מזה,\u0004 שהעדר אמירה הוא שיבוש בסדר הקרבת הקרבן.","\u0003מתיב\u0004 \u0005[מקשה\u0006 על כך\u0005]\u0006 \u0003רב אחא בר הונא\u0004 ממה ששנינו: \u0003תמיד של ראש השנה שחרית קרב כהלכתו\u0004 כמו בכל יום, \u0003במוסף\u0004 של ראש השנה \u0003מהו אומר\u0004 — שירה זו, מהפסוק: \u0003\"הרנינו לאלהים עוזנו הריעו לאלהי יעקב\"\u0004 (תהלים פא, ב). \u0003במנחה מהו אומר\u0004 בשיר — \u0003\"קול ה' יחיל מדבר\"\u0004 (תהלים כט, ח), כדי להזכיר בראש השנה את קול השופר של מתן תורה.","\u0003ובזמן שחל ראש השנה להיות ב\u0004יום \u0003חמישי בשבת\u0004 והספיקו העדים להעיד עליו לפני שהקריבו את התמיד של שחר, \u0003שהשירה שלו\u0004 בכל יום חמישי בשבת היא אף בחול \u0003\"הרנינו לאלהים עוזנו\"\u0004 — \u0003לא היה אומר בשחרית \"הרנינו\", מפני שחוזר וכופל את הפרק.\u0004","\u0003אלא מהו אומר\u0004 — \u0003\"הסירותי מסבל שכמו\"\u0004 (תהלים פא, ז), שנאמר ביוסף שיצא מכלאו בראש השנה. \u0003ואם באו עדים\u0004 ביום חמישי \u0003אחר תמיד של שחר\u0004 — \u0003אומר \"הרנינו\"\u0004 גם במוסף, \u0003אף על פי שחוזר וכופל את הפרק,\u0004 עד כאן לשון הברייתא.","ומעתה נדייק לענייננו: \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 \u0003כל היכא דמסתפקא אמרינן\u0004 \u0005[\u0006שב\u0005כל מקום שיש ספק\u0006 מה לומר \u0005אומרים]\u0006 \u0003שירה\u0004 של יום \u0003חול\u0004 — \u0003היינו דקאמר\u0004 \u0005[זהו שאמר]\u0006 \u0003אומרו\u0004 את שירת חול \u0003וכופלו, אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שבמקרה של ספק \u0003לא אמור\u0004 \u0005[אמרו]\u0006 \u0003כלל\u0004 — \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003אומרו וכופלו?\u0004"],["ודוחים: מכאן אין ראיה שכך עושים תמיד כי \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 ש\u0003שירה דיומיה\u0004 \u0005[של יומו]\u0006 \u0003היא,\u0004 שהרי בראש השנה שחל להיות ביום חמישי אומרים \"הרנינו\" בכל מקרה, אם משום ראש השנה, ואם משום שירת היום הקבועה, שכשיש ספק איזו שירה יש לומר — שמא לא היו אומרים כלל.","אגב הזכרת שיר החג ושיר של יום מביאים ברייתא באותו נושא, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה אומר משום\u0004 (משמו) של \u0003ר' עקיבא: ב\u0004יום ה\u0003ראשון מה היו אומרים\u0004 הלוים בשיר — \u0003\"לה' הארץ ומלואה\"\u0004 (תהלים כד, א), לזכר היום הראשון של בריאת העולם, \u0003על שם ש\u0004בו \u0003קנה\u0004 את השמים ואת הארץ \u0003והקנה\u0004 את העולם ליושביו \u0003ו\u0004הוא \u0003שליט\u0004 יחיד \u0003בעולמו,\u0004 כי לא נבראו המלאכים אלא ביום השני.","\u0003ב\u0004יום ה\u0003שני מה היו אומרים\u0004 — \u0003\"גדול ה' ומהלל מאד\u0004 בעיר אלהינו בהר קדשו \u0003\"(תהלים מח, ב), על שם שחילק מעשיו\u0004 ביום השני של הבריאה בין מים עליונים לתחתונים \u0003ומלך עליהן,\u0004 שהרי מזמור זה מדבר במקום המקדש והשכינה.","\u0003בשלישי היו אומרים: \"אלהים נצב בעדת אל\"\u0004 (תהלים פב, א), \u0003על שם שגילה ארץ בחכמתו\u0004 בבריאת היום השלישי, שנאמר בו \"ותראה היבשה\" (בראשית א, ט), \u0003והכין תבל\u0004 על ידי כך \u0003לעדתו\u0004 שתוכל לחיות בארץ. \u0003ברביעי היו אומרים: \"אל נקמות ה'\"\u0004 (בראשית צד, א), \u0003על שם שברא\u0004 ביום זה \u0003חמה ולבנה, ועתיד ליפרע\u0004 ולהנקם \u0003מעובדיהן\u0004 כעובדי עבודה זרה.","\u0003בחמישי היו אומרים: \"הרנינו לאלהים עוזנו\"\u0004 (תהילים פא, ב), \u0003על שם שברא\u0004 בו \u0003עופות ודגים\u0004 שהם גורמים לכל הרואה אותם \u0003לשבח\u0004 (\"להרנין\") \u0003לשמו, בששי היו אומרים: \"ה' מלך גאות לבש\"\u0004 (בראשית צג, א), \u0003על שם שגמר מלאכתו\u0004 באותו יום \u0003ומלך עליהן\u0004 במלוא פארו. \u0003בשביעי היו אומרים: \"מזמור שיר ליום השבת\"\u0004 (בראשית צב, א), על שם שעתיד הקדוש ברוך הוא להחריב את עולמו ויהיה העולם שומם מבלי אדם ושובת ממלאכה, ויהיה איפוא אותו יום, \u0003יום שכולו שבת.\u0004","\u0003אמר ר' נחמיה: מה ראו חכמים לחלק בין הפרקים הללו,\u0004 שכל השירות נכתבו לזכר העבר, בזמן בריאת העולם, ואילו ביום השבת נאמר שירה על העתיד לבוא? \u0003אלא\u0004 כך יש לפרש: \u0003בראשון\u0004 — על \u0003שקנה והקנה ושליט בעולמו, בשני\u0004 — על \u0003שחילק מעשיו ומלך עליהם, בשלישי\u0004 — על \u0003שגילה ארץ בחכמתו והכין תבל לעדתו,\u0004","\u0003ברביעי\u0004 — על \u0003שברא חמה ולבנה ועתיד ליפרע מעובדיהן, בחמישי\u0004 — על \u0003שברא עופות ודגים לשבח לשמו, בששי —\u0004 על \u0003שגמר מלאכתו ומלך עליהם, בשביעי\u0004 — \u0003על שם ששבת\u0004 ממלאכתו, ו\"מזמור שיר ליום השבת\" מתייחס לשבת הראשונה של ימי הבריאה.","ומעירים: \u0003וקמיפלגי\u0004 \u0005[והם חלוקים]\u0006 לגבי מה שאמר \u0003רב קטינא,\u0004 ש\u0003אמר רב קטינא: שיתא אלפי שני הוה עלמא וחד חרוב\u0004 \u0005[ששת אלפים שנה קיים העולם ואחד הוא נחרב],\u0006 \u0003שנאמר: \"ונשגב ה' לבדו ביום ההוא\"\u0004 (ישעיה ב, יא), שאלף שנים הם עבורו כיום אחד (\"כי אלף שנים בעיניך כיום אתמול כי יעבור\". תהילים צ, ד) והוא כדברי ר' עקיבא. \u0003אמר אביי: תרי חרוב\u0004 \u0005[שני\u0006 אלפים \u0005הוא נחרב],\u0006 \u0003שנאמר: \"יחינו מימים\"\u0004 (הושע ו, ב). ואין לפיכך קשר בין העולם הבא ובין \"יום השבת\".","ושואלים עוד: \u0003במוספי דשבתא\u0004 \u0005[ב\u0006קרבנות \u0005המוסף של שבת]\u0006 \u0003מה היו אומרים? אמר רב ענן בר רבא אמר רב:\u0004 היו אומרים \u0003הזי\"ו ל\"ך\u0004 שהיו מחלקים את שירת האזינו לשישה חלקים: \u0003\"ה\u0004אזינו השמים\u0003\"\u0004 (דברים לב, א), \u0003\"ז\u0004כור ימות עולם\u0003\"\u0004 (דברים לב, ז), \u0003\"י\u0004רכיבהו על במותי ארץ\u0003\"\u0004 (דברים לב, יג), \u0003\"ו\u0004ירא ה' וינאץ\u0003\"\u0004 (דברים לב, יט), \u0003\"ל\u0004ולי כעס אויב אגור\u0003\"\u0004 (דברים לב, כז), \u0003\"כ\u0004י ידין ה' עמו\u0003\"\u0004(דברים לב, לו), ובכל פעם היו אומרים חלק אחד.","\u0003ואמר רב חנן בר רבא אמר רב: כדרך שחלוקים\u0004 פסוקי שירת האזינו \u0003כאן\u0004 בשירה שבמוספי שבת במקדש — \u0003כך חלוקין\u0004 בקריאת התורה \u0003בבית הכנסת\u0004 כשקורים פרשה זו.","ועוד שואלים: \u0003במנחתא דשבתא\u0004 \u0005[ב\u0006קרבן \u0005מנחה,\u0006 תמיד של בין הערביים, \u0005של שבת]\u0006 \u0003מה היו אומרים? אמר ר' יוחנן: \"אז ישיר\"\u0004 (שמות טו, א), עד \"מי כמוך\" (שמות טו, יא), \u0003ו\"מי כמוך\"\u0004 עד סוף שירת הים, \u0003ו\"אז ישיר\u0004 ישראל את השירה\" (במדבר כא, יז), שהיא שירת הבאר כולה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 השאלה: \u0003הני כולהו בחד שבתא אמרי להו\u0004 \u0005[אלה כולם בשבת אחת אומרים אותם]\u0006 את כל חלקי שירת האזינו, \u0003או דלמא כל שבתא ושבתא אמרי חד\u0004 \u0005[או שמא כל שבת ושבת אומרים\u0006 קטע \u0005אחד]?\u0006 ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 \u0003, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' יוסי: עד שהראשונה\u0004 בשירת המוספים של בוקר \u0003אומרת אחת,\u0004 כלומר: מסיימת את כל מחזור פרקי השירה שבשבתות שונות של השירה כולה — \u0003השניה\u0004 של השיר, במנחה, \u0003חוזרת שתים,\u0004 אומרת את מחזור השירה שלה פעמיים, שהרי היא מורכבת משלושה חלקים בלבד, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003כל שבתא ושבתא אמרי חד\u0004 \u0005[כל שבת ושבת אומרים\u0006 קטע \u0005אחד]\u0006 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן].\u0006","\u0003אמר רב יהודה בר אידי אמר ר' יוחנן: עשר מסעות נסעה שכינה,\u0004 כלומר, עד שיצאה שכינה מן המקדש לגמרי נעשה הדבר בעשרה שלבים, ודברים אלה למדים \u0003מקראי\u0004 \u0005[מן הכתובים],\u0006 \u0003וכנגדן גלתה סנהדרין\u0004 לעשרה מקומות, ודבר זה יודעים אנו \u0003מגמרא\u0004 \u0005[מן המסורת].\u0006","ומפרטים: \u0003עשר מסעות נסעה שכינה,\u0004 דבר זה נלמד \u0003מקראי\u0004 \u0005[מן הכתובים],\u0006 ואלו הם: \u0003מ\u0004ן ה\u0003כפרת\u0004 שעל הארון אל ה\u0003כרוב, ומכרוב\u0004 זה \u0003לכרוב\u0004 אחר, \u0003ומכרוב למפתן\u0004 הבית, \u0003וממפתן לחצר, ומחצר למזבח, וממזבח לגג, ומגג לחומה\u0004 של הר הבית, \u0003ומחומה לעיר, ומעיר להר\u0004 שליד ירושלים, \u0003ומ\u0004ן ה\u0003הר למדבר, וממדבר עלתה וישבה במקומה\u0004 במרום, ללא קשר עם בני אדם — \u0003שנאמר: \"אלך אשובה אל מקומי\"\u0004 (הושע ה, טו).","ומפרטים: \u0003מכפרת לכרוב, מכרוב לכרוב, ומכרוב למפתן\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 למשה במשכן: \u0003\"ונועדתי לך שם ודברתי אתך מעל הכפרת\u0004 מבין שני הכרובים\u0003\"\u0004 (שמות כה, כב), משמע שכבוד השכינה בכפורת הוא, \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"וירכב על כרוב ויעף\"\u0004 (שמואל ב' כב, יא), הרי שכבוד השכינה הוא על הכרוב, \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"וכבוד אלהי ישראל נעלה מעל הכרוב אשר היה עליו אל מפתן הבית\"\u0004 (יחזקאל ט, ג), משמע שגלתה השכינה מן הכרוב אל המפתן.","\u0003וממפתן לחצר\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וימלא הבית את הענן והחצר מלאה את נגה כבוד ה'\"\u0004 (יחזקאל י, ד). ו\u0003מחצר למזבח\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ראיתי את ה' נצב על המזבח\"\u0004 (עמוס ט, א). \u0003וממזבח לגג\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"טוב לשבת על פנת גג\"\u0004 (משלי כא, ט). \u0003מגג לחומה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והנה ה' נצב על חומת אנך\"\u0004 (עמוס ז, ז). \u0003מחומה לעיר\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"קול ה' לעיר יקרא\"\u0004 (מיכה ו, ט).","\u0003ומעיר\u0004 עלתה השכינה \u0003להר\u0004 שליד הבית שהוא הר הזיתים — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויעל כבוד ה' מעל תוך העיר ויעמד על ההר אשר מקדם לעיר\"\u0004 (יחזקאל יא, כג). \u0003ומהר למדבר\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"טוב שבת בארץ מדבר\u0004 מאשת מדינים וכעס \u0003\"(משלי כא, יט). וממדבר עלתה וישבה במקומה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אלך אשובה אל מקומי\u0004 עד אשר יאשמו \u0003\"(הושע ה, טו).\u0004","\u0003אמר ר' יוחנן: ששה חדשים נתעכבה שכינה לישראל במדבר, שמא יחזרו בתשובה\u0004 ותחזור שכינה למקומה, \u0003כיון שלא חזרו\u0004 — \u0003אמר: תיפח עצמן,\u0004 כלומר, ילכו לאבדון, \u0003שנאמר: \"ועיני רשעים תכלינה ומנוס אבד מנהם ותקותם מפח נפש\"\u0004 (איוב יא, כ), אלו הן עשר גלויות של שכינה מקודש הקדשים.","\u0003וכנגדן גלתה סנהדרין, מגמרא\u0004 \u0005[לפי המסורת]:\u0006 \u0003מלשכת הגזית\u0004 ששם מקומה הקבוע גלתה הסנהדרין \u0003לחנות\u0004 שהוא מקום מיוחד בהר הבית ולא בתוך המקדש עצמו, \u0003ומחנות לירושלים, ומירושלים\u0004 גלתה \u0003ליבנה,\u0004"],["\u0003ומיבנה לאושא, ומאושא חזרה ליבנה, ומיבנה\u0004 חזרה שוב \u0003לאושא, ומאושא\u0004 נדדה \u0003לשפרעם, ומשפרעם לבית שערים, ומבית שערים לצפורי, ומצפורי לטבריא. וטבריא עמוקה מכולן\u0004 שהיא מצויה בבקעת הירדן. ורמז לנדידות אלה — \u0003שנאמר: \"ושפלת מארץ תדברי\"\u0004 (ישעיה כט, ד).","\u0003ר' אלעזר אומר: שש גלות הן,\u0004 אם מונים רק את המקומות ולא את דרך הנדודים, ורמז לדבר — \u0003שנאמר: \"כי השח ישבי מרום קריה נשגבה ישפילנה ישפילה עד ארץ יגיענה עד עפר\"\u0004 (ישעיה כו, ה), שיש בפסוק זה רמז לשש ירידות (השח, ישפילנה, ישפילה, עד ארץ, יגיענה, עד עפר) \u0003אמר ר' יוחנן: ומשם,\u0004 כלומר ממקום שפלותם וירידתם \u0003עתידין ליגאל, שנאמר: \"התנערי מעפר קומי שבי\u0004 ירושלים\u0003\"\u0004 (ישעיה נב, ב).","\u0003אמר ר' יהושע בן קרחה: ועוד זאת התקין רבן יוחנן בן זכאי: שאפילו ראש בית דין\u0004 (נשיא הסנהדרין) \u0003בכל מקום\u0004 ואינו נמצא במקום מושב הסנהדרין, אף על פי שקידוש החודש תלוי בו כפי ששנינו (לעיל ראש השנה כד,א) ש\"ראש בית דין אומר מקודש\", מכל מקום תיקן \u0003שלא יהו העדים הולכין\u0004 להעיד עדות החודש \u0003אלא\u0004 ילכו \u0003למקום הוועד,\u0004 ויקדשוהו חברי הסנהדרין בלא ראש בית הדין.","מסופר: \u0003ההיא איתתא דאזמנוה לדינא קמיה\u0004 \u0005[אשה אחת הזמינו אותה לדין לפני]\u0006 \u0003אמימר בנהרדעי\u0004 \u0005[בנהרדעא],\u0006 \u0003אזל\u0004 \u0005[הלך]\u0006 \u0003אמימר למחוזא\u0004 לפי שעה, \u0003ולא אזלה בתריה\u0004 \u0005[הלכה אחריו]\u0006 להתדיין שם. \u0003כתב פתיחא עילווה\u0004 \u0005[שטר נדוי עליה]\u0006 על שלא צייתה לבית הדין, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לאמימר: והא אנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]:\u0006 \u0003אפילו ראש בית דין בכל מקום שלא יהו העדים הולכין אלא למקום הוועד,\u0004 משמע שהולכים אחר בית דין ולא אחר ראש הדיינים המזמין!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אמימר: \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 \u0003לענין עדות החדש\u0004 שבהם יש צורך בקביעות מקום, \u0003שאם כן,\u0004 שיבואו למקום הקבוע ולא ימצאו שם את ראש הוועד ויצטרכו לטרוח ללכת למקום אחר — \u0003נמצאת מכשילן לעתיד לבא\u0004 שלא ירצו העדים לבוא, ולכן תקנו להם תקנה זו. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 לגבי תביעות — הלא נאמר: \u0003\"ועבד לוה לאיש מלוה\"\u0004 (משלי כב, ז), שהנתבע הנקרא לדין משועבד לנוחיותו של התובע, ושל בית הדין.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003אין\u0004 ה\u0003כהנים רשאין לעלות בסנדליהן לדוכן\u0004 כשהם מברכים ברכת כהנים בבית הכנסת, \u0003וזו אחד מתשע תקנות שהתקין רבן יוחנן בן זכאי.\u0004 את התקנות הללו מונים: \u0003שית דהאי פירקא\u0004 \u0005[שש\u0006 שנמנו \u0005בפרק זה]\u0006 (תקיעה בשבת ביבנה, לולב כל שבעה, יום הנף כולו אסור באכילת חדש, קבלת עדי החודש כל היום, הליכת עדי החודש למקום הועד, וברכת הכהנים ללא נעילת הסנדל) \u0003וחדא דפירקא קמא\u0004 \u0005[ואחת שבפרק הראשון]\u0006 שלא יחללו העדים את השבת אלא על ניסן ותשרי בלבד,","\u0003ואידך\u0004 \u0005[והאחרת],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003גר שנתגייר בזמן הזה\u0004 שלפי דין תורה צריך הגר להביא שתי עולות עוף לקרבן, נוסף למילה וטבילה. וכיון שלאחר החורבן אי אפשר להביא קרבן \u0003צריך שיפריש רובע\u0004 (רבע שקל) שהוא בערך דמי שני גוזלי יונה \u0003ל\u0004צורך \u0003קינו\u0004 (זוג גוזלים זה), כלומר, שהגר יכין הכל לצורך זה, ומיד כשייבנה בית המקדש יהיה בידו להקריב. \u0003אמר ר' שמעון בן אלעזר: כבר נמנה עליה\u0004 על הלכה זו \u0003רבן יוחנן בן זכאי וביטלה, שלא יפריש מעות אלה מפני התקלה,\u0004 שאם יתחייב להפריש מעות שמא במשך הזמן (שהרי אין תאריך לפדיון מעות אלה) ישגה אדם וישתמש בכסף זה, ונמצא בא לידי מעילה בקודש.","\u0003ואידך\u0004 \u0005[והאחרת]\u0006 התקנה התשיעית בזה \u0003פלוגתא\u0004 \u0005[מחלוקת\u0006 היא\u0005]\u0006 בין \u0003רב פפא ורב נחמן בר יצחק,\u0004 מה היתה. \u0003רב פפא אמר:\u0004 התקנה היתה בענין \u0003כרם רבעי, רב נחמן בר יצחק אמר:\u0004 בענין \u0003לשון של זהורית.\u0004","ומבארים, \u0003רב פפא אמר: כרם רבעי,\u0004 שכן שנינו במשנה: \u0003כרם רבעי\u0004 כלומר פירות הכרם בשנה הרביעית לנטיעתם — שאמרה תורה שצריך להעלותם לירושלים ולאכלם שם. ואם אי אפשר להעבירם בעינם — פודים אותם ומביאים דמיהם לירושלים וקונים בהם דברי מאכל לאכלם בעיר. אולם תקנו חכמים שחלק מסוים של פירות כרם רבעי עצמם \u0003היה עולה לירושלים\u0004 בעינו ולא יפדוהו בכסף. וקבעו תחום להבאת הפירות בערך \u0003מהלך יום לכל צד\u0004 מירושלים \u0003וזו היא תחומה\u0004 של רצועה זו שבה היה כרם רבעי עולה בעינו: \u0003אילת מן הצפון, ועקרבת מן הדרום, לוד מן המערב, וירדן מן המזרח.\u0004","\u0003ואמר עולא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003רבה בר עולא. אמר ר' יוחנן: מה טעם\u0004 תקנו תקנה זו — \u0003כדי לעטר שוקי ירושלים בפירות\u0004 כלומר שעל ידי כך נמצא שיש פירות רבים בירושלים מכיון שכבר מביאים פירות משובחים מכל הכרמים שיש לחלל.","\u0003ותניא\u0004 \u0005[ושנוייה\u0006 ברייתא\u0005]:\u0006 \u0003כרם רבעי היה לו לר' אליעזר במזרח לוד בצד כפר טבי,\u0004 שהוא בתוך התחום שבו צריך להביא פירות הכרם עצמם לירושלים. \u0003וביקש ר' אליעזר להפקירו לעניים\u0004 שהיה עליו טורח גדול להביאם בעינם.","\u0003אמרו לו תלמידיו: רבי, כבר נמנו חבריך עליו והתירוהו.\u0004 שלאחר חורבן הבית בטלה תקנה זו עד שישוב וייבנה. ומסבירים: \u0003מאן\u0004 \u0005[מי]\u0006 הם \u0003חביריך\u0004 האמורים כאן — הכוונה היא ל\u0003רבן יוחנן בן זכאי.\u0004","\u0003רב נחמן בר יצחק אמר: לשון של זהורית\u0004 היתה תקנתו. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בראשונה היו קושרין לשון של זהורית\u0004 (צמר צבוע אדום) \u0003על פתח אולם\u0004 (חלק המקדש הסמוך להיכל הקודש) \u0003מבחוץ,\u0004 ואם אחר הקרבת הקרבנות ושילוח השעיר \u0003הלבין\u0004 לשון זהורית זה בדרך נס — \u0003היו\u0004 העם \u0003שמחין,\u0004 שהיה זה סימן שנמחלו עוונותיהם. \u0003לא הלבין\u0004 — \u0003היו עצבין, ו\u0004כיון שאירע שלא הלבין והיה כל העם מתעצב, \u0003התקינו שיהו קושרין אותו על פתח אולם מבפנים\u0004 כדי שלא יהיו הכל רואים אותו.","\u0003ועדיין היו מציצין ורואין, הלבין\u0004 — \u0003היו שמחין, לא הלבין\u0004 — \u0003היו עצבין, התקינו שיהו קושרין אותו חציו בסלע\u0004 שלידו עומד המשלח את השעיר לעזאזל \u0003וחציו בין קרניו של שעיר המשתלח,\u0004 ואז רק משלח השעיר היה רואה אם הלבין. ותקנה זו תיקן רבן יוחנן בן זכאי.","ומסבירים את יסוד המחלוקת הזו: \u0003רב נחמן בר יצחק מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כרב פפא? אמר לך\u0004 \u0005[היה יכול לומר לך]:\u0006 \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 לומר שביטול תקנת כרם רבעי של \u0003רבן יוחנן בן זכאי\u0004 היא, אם כן \u0003חבריו\u0004 של \u0003ר' אליעזר מי הוה\u0004 \u0005[האם היה]?\u0006 הלא \u0003רבו הוה\u0004 \u0005[היה]\u0006 ובודאי אין לומר שזו תקנת רבן יוחנן. \u0003ואידך\u0004 \u0005[והאחר]\u0006 מה משיב הוא על כך? ומשיבים: \u0003כיון\u0004 ש\u0003תלמידים הוו\u0004 \u0005[היו]\u0006 אלה שאמרו לו — \u0003לאו אורח ארעא למימרא ליה לרביה\u0004 \u0005[אין זה דרך ארץ לומר לו שיאמר\u0006 לו אדם \u0005לרבו]\u0006 \u0003\"רבך\"\u0004 ולכן אמרו בלשון \"חבריך\".","ושואלים: \u0003ורב פפא מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כרב נחמן בר יצחק? אמר לך\u0004 \u0005[היה יכול לומר לך]:\u0006 \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 לומר שתקנה זו של \u0003רבן יוחנן בן זכאי\u0004 היתה — \u0003בימי רבן יוחנן בן זכאי מי הוה\u0004 \u0005[האם היתה]\u0006 בכלל \u0003לשון של זהורית\u0004 מלבינה? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כל שנותיו של רבן יוחנן בן זכאי\u0004 היו \u0003מאה ועשרים שנה; ארבעים שנה\u0004 מהן \u0003עסק בפרקמטיא\u0004 (במסחר) שיוכל להגיע לעצמאות כלכלית ויוכל לעסוק בתורה, \u0003ארבעים שנה למד\u0004 תורה, \u0003ארבעים שנה לימד\u0004 תורה.","\u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003ארבעים שנה קודם שנחרב הבית לא היה לשון של זהורית מלבין אלא מאדים. ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]\u0006 \u0003משחרב הבית התקין רבן יוחנן בן זכאי,\u0004 משמע שחי ופעל לאחר החורבן. ואם כן באותן השנים שרבן יוחנן בן זכאי היה מלמד תורה ויכול להתקין תקנות לרבים — כבר לא היה מקום לעשות זאת, שכבר ידעו שאין לשון של זהורית מלבין כלל! ושואלים: \u0003ואידך\u0004 \u0005[והאחר],\u0006 מה הוא עונה על כך? לדעתו אותה תקנה היתה במשך \u0003אותם ארבעים שנה\u0004 ש\u0003למד, תלמיד יושב לפני רבו הוה\u0004 \u0005[היה],\u0006 \u0003ואמר מילתא\u0004 \u0005[דבר]\u0006 והציע הצעה \u0003ואסתבר טעמיה\u0004 \u0005[והסתבר טעמו]\u0006 לחכמים,"],["\u0003וקבעיה רביה בשמיה\u0004 \u0005[וקבעו רבו בשמו]\u0006 ומונים אותה בין תקנותיו.","\u0003סדר ברכות\u0004 של ראש השנה כיצד? \u0003אומר אבות\u0004 שהיא הברכה הראשונה (\"מגן אברהם\") שבשמונה עשרה, \u0003וגבורות\u0004 (\"מחיה מתים\"), \u0003וקדושת השם\u0004 (\"אתה קדוש\") \u0003וכולל מלכיות עמהן\u0004 בברכת קדושת השם \u0003ואינו תוקע\u0004 אחריה.","ומוסיפים ברכה מיוחדת ל\u0003קדושת היום ותוקע\u0004 לאחריה. ואומר ברכה של \u0003זכרונות ותוקע,\u0004 ולאחריה אומר ברכת \u0003שופרות ותוקע, ו\u0004אחר כך \u0003אומר\u0004 כדרך שמסיימים כל תפילה כרגיל, בברכת ה\u0003עבודה\u0004 (\"רצה\") \u0003והודאה\u0004 (\"מודים\") \u0003וברכת כהנים,\u0004 אלו \u0003דברי ר' יוחנן בן נורי.\u0004","\u0003אמר לו ר' עקיבא: אם אינו תוקע למלכיות למה הוא מזכיר\u0004 אותה לעצמה? \u0003אלא\u0004 כך הסדר: \u0003אומר אבות וגבורות\u0004 כרגיל, \u0003וקדושת השם, וכולל מלכיות עם קדושת היום ותוקע, זכרונות ותוקע, שופרות ותוקע, ו\u0004אחר כך \u0003אומר עבודה והודאה וברכת כהנים.\u0004","שנינו במשנה, \u0003אמר לו ר' עקיבא: אם אינו תוקע למלכיות למה הוא מזכיר?\u0004 ותוהים: \u0003למה הוא מזכיר?!\u0004 מה מקום לשאלה זו? הלא \u0003רחמנא אמר אידכר\u0004 \u0005[התורה אמרה הזכר]\u0006 וכיון שמצוה להזכיר, אין לקשרה בהכרח עם תקיעת השופר! \u0003אלא\u0004 כך היתה כוונתו: \u0003למה עשר,\u0004 כלומר, למה אומר עשרה פסוקים בברכה זו כמו בברכות האחרות \u0003לימא\u0004 \u0005[שיאמר]\u0006 \u0003תשע\u0004 או פחות, שהרי \u0003הואיל ואשתני\u0004 \u0005[והשתנתה]\u0006 ברכה זו בחסרון תקיעה תשתנה גם במספר הפסוקים שבה!","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מנין שאומרים\u0004 ברכת \u0003אבות\u0004 — \u0003שנאמר: \"הבו לה' בני אלים\"\u0004 (תהילים כט, א) במובן: הזכירו לפני ה' את החזקים, התקיפים, ומכאן — שמזכירים את גדולת האבות. \u0003ומנין שאומרים גבורות\u0004 — \u0003שנאמר: \"הבו לה' כבוד ועז\"\u0004 (תהילים כט, א). \u0003ומנין שאומרים קדושות\u0004 — \u0003שנאמר: \"הבו לה' כבוד שמו השתחוו לה' בהדרת קדש\"\u0004 (תהלים כט, ב).","\u0003ומנין שאומרים\u0004 בתפילת ראש השנה \u0003מלכיות זכרונות ושופרות? ר' אליעזר אומר: דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004בחודש השביעי באחד לחודש יהיה לכם \u0003שבתון זכרון תרועה מקרא קדש\"\u0004 (ויקרא כג, כד), וכך יש לפרשו: \u0003\"שבתון\"\u0004 — \u0003זה\u0004 רמז לברכה שמזכירים בה \u0003קדושת היום, \"זכרון\"\u0004 — \u0003אלו זכרונות, \"תרועה\"\u0004 — \u0003אלו שופרות, \"מקרא קדש\"\u0004 פירושו: \u0003קדשהו ב\u0004המנעות מ\u0003עשיית מלאכה.\u0004","\u0003אמר לו ר' עקיבא: מפני מה לא נאמר\u0004 אחרת: \u0003\"שבתון\"\u0004 — \u0003שבות, שבו פתח הכתוב תחילה,\u0004 שסברה היא לומר שמתחלה נאמר עיקר הדבר — שיום זה הוא יום חג המנוע מעשיית מלאכה! \u0003אלא\u0004 כך צריך לדרוש את הכתובים: \u0003\"שבתון\"\u0004 — פירושו \u0003קדשהו ב\u0004המנעות מ\u0003עשיית מלאכה, \"זכרון\"\u0004 — \u0003אלו זכרונות, \"תרועה\"\u0004 — \u0003אלו שופרות, \"מקרא קדש\"\u0004 — \u0003זו קדושת היום.\u0004","אם כן \u0003מנין שאומרים מלכיות? תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003רבי אומר:\u0004 נאמר שם \u0003\"אני ה' אלהיכם\"\u0004 (ויקרא כג, כב) שהוא הזכרת אלוהותו של הקדוש ברוך הוא, והיא מלכותו בעולם, \u0003ו\u0004נאמר סמוך לו: \u0003\"בחדש השביעי\"\u0004 (ויקרא כג, כד) — \u0003זו מלכות\u0004 שצריך לומר ביום זה.","\u0003ר' יוסי בר' יהודה אומר: אינו צריך\u0004 לפסוק זה, \u0003הרי הוא אומר:\u0004 \"וביום שמחתכם ובמועדיכם ובראשי חדשיכם ותקעתם בחצוצרות על עולותיכם ועל זבחי שלמיכם \u0003והיו לכם לזכרון לפני אלהיכם\u0004 אני ה' אלהיכם\" (במדבר י, י), \u0003שאין תלמוד לומר\u0004 בסוף הפסוק לומר שוב \u0003\"אני ה' אלהיכם\", ומה תלמוד לומר\u0004 בהדגשה זו של \u0003\"אני ה' אלהיכם\"\u0004 — \u0003זה בנה אב,\u0004 כלומר, כאן מקור ויסוד להלכה, ש\u0003לכל מקום שנאמר בו זכרונות\u0004 — \u0003יהיו\u0004 בו \u0003מלכיות עמהן.\u0004","ומעתה חוזרים לבעיה שבמשנתנו: \u0003והיכן אומרה לקדושת היום? תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003רבי אומר: עם המלכיות אומרה,\u0004 וטעמו: \u0003מה מצינו בכל מקום,\u0004 כלומר, בכל החגים, שאת קדושת היום אומרים \u0003ב\u0004ברכה ה\u0003רביעית\u0004 — \u0003אף כאן\u0004 אומרים אותה \u0003ברביעית.\u0004","\u0003רבן שמעון בן גמליאל אומר: עם הזכרונות אומרה\u0004 לקדושת היום. וטעמו: \u0003מה מצינו בכל מקום\u0004 שקדושת היום נאמרת \u0003באמצע\u0004 תפילת שמונה עשרה (רביעית מבין השבע) — \u0003אף כאן\u0004 הריהי נאמרת \u0003באמצע,\u0004 והברכה החמישית היא הברכה האמצעית בתפילת ראש השנה (שיש בה תשע ברכות).","\u0003מסופר: וכשקידשו בית דין את השנה באושא ירד ר' יוחנן בן ברוקא לפני רבן שמעון בן גמליאל, ועשה\u0004 נהג בתפילתו \u0003כ\u0004שיטת \u0003ר' יוחנן בן נורי. אמר לו רבן שמעון: לא היו נוהגין כן ביבנה. ליום השני\u0004 של ראש השנה \u0003ירד ר' חנינא בנו של ר' יוסי הגלילי ועשה כר' עקיבא. אמר רבן שמעון בן גמליאל: כך היו נוהגין ביבנה.\u0004","על ברייתא זו תוהים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 ש\u0003רבן שמעון בן גמליאל כ\u0004שיטת \u0003ר' עקיבא סבירא ליה\u0004 \u0005[סבור הוא]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' עקיבא\u0004 ש\u0003מלכיות עם קדושת היום אמר להו\u0004 \u0005[אומר\u0006 הוא \u0005אותן]\u0006 \u0003ורבן שמעון בן גמליאל אומר\u0004 ש\u0003קדושת היום עם הזכרונות אמר להו\u0004 \u0005[אומר\u0006 הוא \u0005אותם]\u0006 וכיצד הסכים רבן שמעון בן גמליאל עם מנהג ר' עקיבא? \u0003אמר ר' זירא: אין הכוונה שהסכים בכל הפרטים, אלא התכוון לומר שתוקעין למלכיות,\u0004 שלענין זה בלבד הסכים, שכך נהגו ביבנה.","שנינו שם: \u0003ליום השני ירד ר' חנינא.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירושו של יום \u0003שני, אילימא\u0004 \u0005[אם תאמר]\u0006 שהכוונה היא ל\u0003יום טוב שני\u0004 של ראש השנה, \u0003למימרא דעברוה\u0004 \u0005[האם תאמר שעיברו]\u0006 את חודש \u0003אלול\u0004 ואז יום שלושים של אלול הוא יום ראשון של ראש השנה, ואחד בתשרי הוא יום שני, אולם \u0003האמר\u0004 \u0005[הרי אמר]\u0006 \u0003ר' חנינא בר כהנא: מימות עזרא ואילך לא מצינו\u0004 שיהיה חודש \u0003אלול מעובר\u0004 וקשה להניח שהיה מקרה כזה בימי התנאים! \u0003אמר רב חסדא: מאי\u0004 \u0005[מה\u0006 הפירוש\u0005]\u0006 \u0003שני\u0004 — \u0003ליום שני.\u0004 כלומר, \u0003לשנה הבאה,\u0004 שבראש השנה בשנה הבאה אירע הדבר.","\u0003אין פוחתין מעשרה\u0004 פסוקים של מלכויות שאומרים בתוך ברכת \u0003מלכיות, מעשרה\u0004 פסוקים של זכרונות בברכת \u0003זכרונות, מעשרה\u0004 פסוקים של שופרות בברכת \u0003שופרות. ר' יוחנן בן נורי אומר: אם אמר שלש שלש מכולן\u0004 — \u0003יצא.\u0004","שואלים: \u0003הני\u0004 \u0005[אותם]\u0006 \u0003עשרה\u0004 פסוקים של \u0003מלכיות\u0004 ושאר ברכות \u0003כנגד מי\u0004 קבעום? \u0003אמר רבי: כנגד עשרה הלולים שאמר דוד בספר תהילים.\u0004 ותוהים: \u0003הלולים\u0004 בתהילים, הרי \u0003טובא הוו\u0004 \u0005[הרבה יותר\u0006 מזה \u0005הם]!\u0006 ומשיבים: \u0003הנך דכתיב בהו\u0004 \u0005[אותם שנאמר בהם]\u0006 \u0003\"הללוהו בתקע שופר\"\u0004 (תהילים קנ, ג), ובפרק זה נאמרו עשר פעמים \"הללוהו\".","\u0003רב יוסף אמר: כנגד עשרת הדברות שנאמרו לו למשה בסיני. ר' יוחנן אמר: כנגד עשרה מאמרות שבהן נברא העולם.\u0004 על כך שואלים: \u0003הי נינהו\u0004 \u0005[מה הם]\u0006 בעצם עשרה מאמרות אלו — הרי הם אותן פעמים שכתוב","\u0003\"ויאמר\u0004 אלוהים\" בפרשת \u0003בראשית,\u0004 אולם אלה הלא \u0003תשעה הוו\u0004 \u0005[הם]\u0006 ולא עשרה! ומשיבים: המלה \u0003\"בראשית\"\u0004 עצמה \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003מאמר הוא,\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"בדבר ה' שמים נעשו\"\u0004 (תהילים לג, ו), לומר שכל הבריאה כולה נוצרה בכלל בדיבור אחד, ואחר כך נתפרטה והלכה בדברים שונים.","שנינו במשנה, \u0003ר' יוחנן בן נורי אומר: אם אמר שלש שלש מכולן יצא. איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים: \u0003היכי קתני\u0004 \u0005[כיצד שנה],\u0006 מה כוונת דבריו, האם יש לפרש שאומרים \u0003שלש מן התורה, שלש מן הנביאים, ושלש מן הכתובים דהוו\u0004 \u0005[שהם]\u0006 בסך הכל \u0003תשע ואיכא בינייהו חדא\u0004 \u0005[ויש ביניהם\u0006 בין ר' יוחנן בן נורי וחכמים הפרש ב\u0005אחת],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003אחד מן התורה ואחד מן הנביאים ואחד מן הכתובים, דהויין להו\u0004 \u0005[שהם]\u0006 \u0003שלש\u0004 הזכרות \u0003ואיכא בינייהו טובא\u0004 \u0005[ויש ביניהם\u0006 הפרש \u0005גדול]?\u0006","ומביאים ראיה, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 הוכחה לדבר: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין פוחתין מעשרה מלכיות, מעשרה זכרונות, מעשרה שופרות, ואם אמר שבע מכולן\u0004 — \u0003יצא, כנגד שבעה רקיעים.\u0004","\u0003ר' יוחנן בן נורי אמר: הפוחת\u0004 — \u0003לא יפחות משבע, ואם אמר שלש מכולן\u0004 — \u0003יצא, כנגד תורה ונביאים וכתובים, ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 \u0003כנגד כהנים לוים וישראלים.\u0004 משמע שהוא סבור שהפוחת אומר בסך הכל שלש. \u0003אמר רב הונא אמר שמואל: הלכה כר' יוחנן בן נורי,\u0004 שאם עשה כן — יצא.","\u0003אין מזכירין\u0004 פסוקים מתוך \u0003זכרון מלכות ושופר\u0004 אם פסוקים אלה יש בהם זכרון \u0003של פורענות.\u0004 ובאמירת עשרה פסוקים אלה \u0003מתחיל ב\u0004פסוקים של ה\u0003תורה, ומשלים בנביא, ר' יוסי אומר: אם השלים\u0004 בפסוק מן \u0003התורה\u0004 — \u0003יצא.\u0004"],["פסוקי \u0003מלכיות\u0004 של פורענות, \u0003כגון: \"חי אני נאם ה' אלהים אם לא ביד חזקה ובזרוע נטויה ובחמה שפוכה אמלך עליכם\"\u0004 (יחזקאל כ, לג) \u0003ואף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003אמר רב נחמן\u0004 על כתוב זה: \u0003כל כי האי ריתחא לירתח קודשא בריך הוא עלן וליפרוקינן\u0004 \u0005[כל כגון כעס זה,\u0006 כלומר, הלואי \u0005יכעס הקדוש ברוך הוא עלינו ויגאלנו]\u0006 מכל מקום, \u0003כיון דבריתחא אמור\u0004 \u0005[שבכעס נאמר]\u0006 הפסוק — \u0003אדכורי ריתחא בריש שתא לא מדכרינן\u0004 \u0005[הזכרת כעס בראש השנה אין אנו מזכירים].\u0006","\u0003זכרון\u0004 של פורענות כיצד — \u0003כגון: \"ויזכר כי בשר המה\u0004 רוח הולך ולא ישוב\" (תהילים עח, לט). \u0003שופר\u0004 של פורענות — \u0003כגון: \"תקעו שופר בגבעה\u0004 חצוצרה ברמה הריעו בית און אחריך בנימין\u0003\"\u0004 (הושע ה, ח).","\u0003אבל אם בא לומר מלכות זכרון ושופר של פורענות של גוים\u0004 — \u0003אומר. מלכות\u0004 של פורענות — \u0003כגון: \"ה' מלך ירגזו עמים\"\u0004 (תהילים צט, א), \u0003וכגון: \"ה' מלך עולם ועד אבדו גוים מארצו\"\u0004 (תהילים י, טז). \u0003זכרון\u0004 של פורענות — \u0003כגון: \"זכר ה' לבני אדום\u0004 את יום ירושלים האומרים ערו ערו עד היסוד בה\u0003\"\u0004 (תהילים קלז, ז). \u0003שופר\u0004 של פורענות — \u0003כגון: \"וה' אלהים בשופר יתקע והלך בסערות תימן\"\u0004 (זכריה ט, יד) \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ה' צבאות יגן עליהם\"\u0004 (זכריה ט, טו) על ישראל.","\u0003אין מזכירין\u0004 בפסוקים אלה \u0003זכרון של יחיד, ואפילו\u0004 הוא \u0003לטובה, כגון: \"זכרני ה' ברצון עמך\"\u0004 (תהילים קו, ד), \u0003וכגון: \"זכרה לי אלהי לטובה\"\u0004 (נחמיה ה, יט).","\u0003פקדונות,\u0004 פסוקים שכתוב בהם שה' פקד — \u0003הרי הן כזכרונות\u0004 לענין זה, \u0003כגון: \"וה' פקד את שרה\"\u0004 (בראשית כא, א), \u0003וכגון: \"פקוד פקדתי אתכם\"\u0004 (שמות ג, טז), אלה \u0003דברי ר' יוסי. ר' יהודה אומר:\u0004 פקדונות \u0003אינן כזכרונות.\u0004","אגב מובאות אלה שואלים: \u0003ולר' יוסי נהי נמי\u0004 \u0005[אם אמנם גם כן]\u0006 נאמר ש\u0003פקדונות הרי הן כזכרונות,\u0004 אולם הפסוק שהוא מביא \u0003\"וה' פקד את שרה\"\u0004 הלא \u0003פקדון\u0004 של ה\u0003יחיד הוא,\u0004 והרי אמרנו שאין מזכירים זכרון של יחיד אלא של הרבים בלבד! ומשיבים: \u0003כיון דאתו\u0004 \u0005[שבאו]\u0006 \u0003רבים מינה\u0004 \u0005[ממנה]\u0006 — \u0003כרבים דמיא\u0004 \u0005[היא נחשבת]\u0006 שכיון שהיא אם כל ישראל — הרי זה כזכרון השייך לכלל ישראל.","וכן נחלקו לגבי הפסוק: \u0003\"שאו שערים ראשיכם והנשאו פתחי עולם ויבוא מלך הכבוד. מי זה מלך הכבוד ה' עזוז וגבור ה' גבור מלחמה\"\u0004 (תהילים כד, ז-ח), והבא אחריו: \u0003\"שאו שערים ראשיכם ושאו פתחי עולם ויבא מלך הכבוד. מי הוא זה מלך הכבוד ה' צבאות הוא מלך הכבוד סלה\"\u0004 (תהילים כד, ט-י). פסקה \u0003ראשונה\u0004 חושבים אותה, כ\u0003שתים,\u0004 כשתי מלכויות, משום שנזכרת בה פעמיים לשון מלכות, \u0003שניה\u0004 נחשבת מטעם זה כ\u0003שלש,\u0004 אלו \u0003דברי ר' יוסי.\u0004","\u0003ר' יהודה אומר: ראשונה\u0004 אינה נחשבת אלא כ\u0003אחת,\u0004 שהשאלה (\"מי הוא זה מלך הכבוד\"?) אינה נראית בעיניו כמלכות, ומטעם זה \u0003שניה\u0004 נחשבת רק כ\u0003שתים.\u0004","וכן פסוק אחר: \u0003\"זמרו אלהים זמרו זמרו למלכנו זמרו. כי מלך כל הארץ אלהים\u0004 זמרו משכיל\" (תהילים מז, ז-ח) — הרי כאן \u0003שתים,\u0004 שפעמיים מוזכרת כאן לשון מלכות, אלו \u0003דברי ר' יוסי. ר' יהודה אומר:\u0004 רק מלכות \u0003אחת\u0004 היא, ש\"זמרו למלכנו\" אינו נחשב למלכות. \u0003ושוין\u0004 (מסכימים) שניהם שבפסוק \u0003\"מלך אלוהים על גוים אלהים ישב על כסא קדשו\"\u0004 (תהילים מז, ט) \u0003שהיא\u0004 נחשבת הזכרה \u0003אחת\u0004 בלבד, ש\"ישב על כסא קדשו\" אינו מלכות מפורשת.","\u0003זכרון שיש בו תרועה\u0004 כיצד — \u0003כגון\u0004 הפסוק: \u0003\"שבתון זכרון תרועה מקרא קדש\"\u0004 (ויקרא כג, כד), \u0003אומרה עם הזכרונות ואומרה עם השופרות\u0004 פעמיים, או באיזה מהם שירצה, אלו \u0003דברי ר' יוסי. ר' יהודה אומר: אינו אומרה אלא עם הזכרונות בלבד,\u0004 לפי שעיקרו של הכתוב הוא הזכרון.","\u0003מלכות שיש עמו תרועה\u0004 כיצד — \u0003כגון: \"ה' אלהיו עמו ותרועת מלך בו\"\u0004 (במדבר כג, כא) — \u0003אומרה עם המלכיות ואומרה עם השופרות,\u0004 אלו \u0003דברי ר' יוסי. ר' יהודה אומר: אינו אומרה אלא עם המלכיות בלבד.\u0004","\u0003תרועה שאין עמה\u0004 ו\u0003לא כלום,\u0004 כלומר אין בה ענין נוסף חוץ מהזכרת התרועה, כיצד — \u0003כגון \"יום תרועה יהיה לכם\"\u0004 (במדבר כט, א) — \u0003אומרה עם השופרות,\u0004 אלו \u0003דברי ר' יוסי. ר' יהודה אומר: אינו אומרה כל עיקר,\u0004 כי צריך שיהיה בפסוק גם ענין של תפילה ובקשה השייכות לראש השנה.","שנינו במשנה: כי בתפילת ראש השנה \u0003מתחיל ב\u0004אמירת פסוקי ה\u0003תורה ומשלים בנביא,\u0004 ו\u0003ר' יוסי אומר אם השלים בתורה יצא.\u0004 מלשון ר' יוסי במשנה אפשר ללמוד: \u0003אם השלים\u0004 כלומר, \u0003דיעבד\u0004 \u0005[לאחר מעשה]\u0006 — \u0003אין\u0004 \u0005[כן].\u0006 \u0003לכתחילה\u0004 — \u0003לא\u0004 יעשה כן. \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יוסי אומר: המשלים בתורה הרי זה משובח!\u0004 ומשיבים: \u0003אימא\u0004 \u0005[אמור]\u0006 ותקן את לשון המשנה, לא \"אם השלים\" אלא: \u0003משלים,\u0004 כלומר לכתחילה.","ומקשים: ובכל זאת \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"אם השלים\" קתני\u0004 \u0005[שנינו],\u0006 ומזה משמע כי \u0003דיעבד\u0004 \u0005[לאחר מעשה]\u0006 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003לכתחילה\u0004 — \u0003לא!\u0004 ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 כך יש לתקן את לשון המשנה: \u0003מתחיל בתורה ומשלים בנביא. ר' יוסי אומר: משלים בתורה, ואם השלים בנביא\u0004 — \u0003יצא. תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך],\u0006 \u0003אמר ר' אלעזר בר' יוסי: וותיקין היו משלימין אותה בתורה,\u0004 ובודאי בשיטת אביו אמרה.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003זכרונות ושופרות איכא טובא\u0004 \u0005[יש הרבה]\u0006 ואפשר שיימצאו פסוקים גם בתורה גם מן הנביאים די הצורך, \u0003אלא מלכיות\u0004 הלא \u0003תלת\u0004 \u0005[שלוש]\u0006 בלבד \u0003הוא דהויין\u0004 \u0005[שיש]\u0006 והם: \u0003\"ה' אלהיו עמו ותרועת מלך בו\"\u0004 (במדבר כג, כא), \u0003\"ויהי בישרון מלך\"\u0004 (דברים לג, ה), והפסוק \u0003\"ה' ימלך לעלם ועד\"\u0004 (שמות טו, יח), \u0003ואנן בעינן עשר וליכא\u0004 \u0005[ואנחנו\u0006 הלא \u0005צריכים עשרה\u0006 פסוקים \u0005ואין לנו]!\u0006 שהרי לר' יוסי צריך לפחות ארבעה מן התורה!","\u0003אמר רב הונא: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר, ממה שאמרו: \u0003\"שמע ישראל ה' אלהינו ה' אחד\"\u0004 (דברים ו, ד) — הרי זה פסוק של \u0003מלכות,\u0004 אלו \u0003דברי ר' יוסי, ר' יהודה אומר: אינה מלכות.\u0004","\u0003\"וידעת היום והשבת אל לבבך כי ה' הוא האלהים\u0004 בשמים ממעל ועל הארץ מתחת \u0003אין עוד\"\u0004 (דברים ד, לט) — הרי זה פסוק של \u0003מלכות,\u0004 אלו \u0003דברי ר' יוסי, ר' יהודה אומר: אינה מלכות. \"אתה הראת לדעת כי ה' הוא האלהים אין עוד מלבדו\"\u0004 (דברים ד, לה) — הרי זה פסוק של \u0003מלכות,\u0004 אלו \u0003דברי ר' יוסי, ר' יהודה אומר: אינה מלכות.\u0004 ואם כן לשיטת ר' יוסי יש פסוקים במספר מספיק כדי שיוכל לומר שלושה פסוקים בתורה בתחילה ופסוק אחרון בסוף.","אותו אדם ה\u0003עובר לפני התיבה ביום טוב של ראש השנה, השני,\u0004 כלומר זה שמתפלל תפילה שניה, היא תפילת מוסף — הוא \u0003מתקיע,\u0004 כלומר: מוציא את העם ידי חובתם בתקיעות. \u0003ובשעת ההלל,\u0004 באותם ימים בהם אומרים הלל, \u0003הראשון,\u0004 כלומר: זה שהתפלל תפילה ראשונה, תפילת שחרית, הוא \u0003מקרא\u0004 לעם \u0003את ההלל.\u0004","ושואלים: \u0003מאי שנא\u0004 \u0005[במה שונה],\u0006 כלומר, מדוע דווקא ה\u0003שני מתקיע\u0004 — \u0003משום\u0004 ש\u0003\"ברב עם הדרת מלך\"\u0004 (משלי יד, כח) ולכן עושים זאת כאשר כל האנשים הגיעו כבר לתפילה ולא בשחרית, מפני המאחרים, אולם \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003הלל נמי\u0004 \u0005[גם כן]\u0006 \u0003נימא\u0004 \u0005[שנאמר]\u0006 \u0003בשני\u0004 משום אותו נימוק ש\u0003\"ברוב עם הדרת מלך\"!\u0004","\u0003אלא מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003הלל\u0004 שכן אומרים אותו \u0003בראשון\u0004 — \u0003משום\u0004 ש\u0003זריזין מקדימין למצות,\u0004 אולם \u0003תקיעה נמי\u0004 \u0005[גם כן]\u0006 \u0003נעביד\u0004 \u0005[נעשה]\u0006 \u0003בראשון, משום\u0004 אותו טעם ש\u0003זריזין מקדימין למצות!\u0004","\u0003אמר ר' יוחנן: בשעת השמד שנו,\u0004 שגזרו על התקיעות, והיו צריכים לדחות את התקיעות עד לתפילת המוסף שלא ישגיחו עוד בהם.","\u0003מביאים מן המשנה מדקאמר\u0004 \u0005[ממה שנאמר]:\u0006 \u0003\"בשעת הלל\", מכלל דבראש השנה ליכא\u0004 \u0005[אין]\u0006 אמירת \u0003הלל.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? שאומרים הלל בכל חג ואין אומרים בראש השנה? \u0003אמר ר' אבהו: אמרו מלאכי השרת לפני הקדוש ברוך הוא: רבונו של עולם! מפני מה אין ישראל אומרים שירה\u0004 (הלל) \u0003לפניך בראש השנה וביום הכפורים? אמר להם: אפשר מלך יושב על כסא דין, וספרי חיים וספרי מתים פתוחין לפניו\u0004 לכתוב כל אדם בספר זה או זה — \u0003וישראל אומרים שירה?\u0004 שזמן זה של דין אינו ראוי שיאמרו בו שירה, ולכן אין הלל נאמר אלא בחגים אחרים, שהם זמני שמחה.","\u0003שופר של ראש השנה אין מעבירין עליו את התחום,\u0004 כלומר, אין יוצאים מתחום שבת כדי לשמוע תקיעת שופר, \u0003ואין מפקחין עליו את הגל\u0004 שאם נפל עליו גל אבנים — אין מפנים את האבנים כדי להוציאו, ואף \u0003לא עולין באילן\u0004 כדי להורידו אם היה תלוי בו, \u0003ולא רוכבין על גבי בהמה, ולא שטין על פני המים\u0004 לקחת אותו, \u0003ואין חותכין אותו\u0004 אם צריך לחותכו ולתקנו — \u0003בין\u0004 שעוברים \u0003בדבר שהוא\u0004 אסור \u0003משום שבות\u0004 בלבד שהיא תקנת חכמים, \u0003ובין בדבר שהוא משום\u0004 מצות \u0003לא תעשה\u0004 מן התורה. \u0003אבל אם רצה ליתן לתוכו מים או יין\u0004 בתוך יום החג כדי לצלל את קולו — \u0003יתן,\u0004 שאין במעשה זה משום מלאכה כלל.","עוד אמרו: \u0003אין מעכבין את התנוקות מלתקוע\u0004 בשופר בראש השנה, אף על פי שאין עליהם חובת מצוות, \u0003אבל מתעסקין עמהן עד שילמדו\u0004 מעצמם. \u0003והמתעסק\u0004 בדרך זו או אחרת בתקיעת שופר — \u0003לא יצא\u0004 ידי חובה, \u0003ו\u0004כן \u0003השומע\u0004 תקיעת שופר \u0003מן המתעסק\u0004 — \u0003לא יצא.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 ההלכה שאין עושים מלאכה ביום טוב כדי לקיים תקיעת שופר? משום שתקיעת \u0003שופר\u0004 מצוות \u0003עשה הוא ו\u0004איסור מלאכה של \u0003יום טוב\u0004 יש בו גם \u0003עשה\u0004 של שבתון, וגם \u0003לא תעשה\u0004 של איסור מלאכה — \u0003ואין עשה דוחה את לא תעשה ועשה.\u0004","נאמר במשנה ש\u0003לא עולין באילן, ולא רוכבין על גבי בהמה,\u0004 ואחר כך מזכירים גם שאין לחתוך אותו ממקומו. ותוהים על סדר הדברים: \u0003השתא\u0004 \u0005[עכשיו],\u0006 הרי, דברים שהם אסורים \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 בלבד \u0003אמרת\u0004 ש\u0003לא\u0004 יעשו, דברים שהם אסורים \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שלא לעשות?! ומשיבים: משנתנו בסגנון של \u0003\"זו ואין צריך לומר זו\" קתני\u0004 \u0005[שנה],\u0006 שמתחיל בדבר חידוש ומסיים בדבר פשוט וידוע יותר."],["שנינו במשנה: ש\u0003אין חותכין אותו,\u0004 את השופר, בראש השנה, \u0003בין בדבר שהוא משום שבות ובין בדבר שהוא משום לא תעשה.\u0004 ומסבירים: דבר שיש בו \u0003משום שבות\u0004 — כגון שחותכים אותו \u0003במגלא\u0004 \u0005[במגל],\u0006 שאין רגיל לחתוך בו ואין בכך איסור גמור מן התורה. וחיתוך שיש בו משום \u0003לא תעשה\u0004 הוא \u0003בסכינא\u0004 \u0005[בסכין],\u0006 שדרך לחתוך בו.","ושוב תוהים: \u0003השתא\u0004 \u0005[עכשיו]\u0006 הרי \u0003משום שבות אמרת\u0004 ש\u0003לא\u0004 יעשה — דבר שיש בו משום \u0003לא תעשה מיבעיא\u0004 \u0005[הוצרכה\u0006 לומר\u0005]?\u0006 ומשיבים: משנתנו בסגנון של \u0003זו ואין צריך לומר זו קתני\u0004 \u0005[שנה]\u0006 שמתחיל בדבר החידוש ומסיים בדבר פשוט.","\u0003שנינו במשנה: אבל אם רצה ליתן לתוכו,\u0004 לתוך השופר, בראש השנה \u0003מים או יין\u0004 כדי לשפר את קולו — \u0003יתן.\u0004 ומדייקים: \u0003מים או יין\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003מי רגלים\u0004 שבגלל חמיצותם יפים הם לתיקון השופר עצמו — \u0003לא.\u0004","ומעירים: \u0003מתניתין מני\u0004 \u0005[משנתנו\u0006 כשיטת \u0005מי היא] —\u0006 כשיטת \u0003אבא שאול היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006, \u0003אבא שאול אומר: מים או יין\u0004 — \u0003מותר\u0004 מותר להכניס לתוך השופר בראש השנה, \u0003כדי לצחצחו, מי רגלים\u0004 — \u0003אסור, מפני הכבוד\u0004 שאף שהם מועילים, אין זה כבוד לשופר, שהוא תשמיש מצוה, שיתקנו אותו באופן זה.","שנינו במשנה: \u0003אין מעכבין את התינוקות מלתקוע\u0004 בראש השנה. ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 את ה\u0003נשים,\u0004 אם רצו לתקוע בשופר בעצמן — \u0003מעכבין, והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין מעכבין לא את הנשים ולא את התינוקות מלתקוע ביום טוב! אמר אביי: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 משנתנו היא כשיטת \u0003ר' יהודה, הא\u0004 \u0005[זו]\u0006 הברייתא כשיטת \u0003ר' יוסי ור' שמעון\u0004 היא.","\u0003דתניא\u0004 \u0005[שכן שנויה\u0006 ברייתא\u0005],\u0006 נאמר: \u0003\"דבר אל בני ישראל\u0004 אדם כי יקריב מכם קרבן לה'... וסמך ידו על ראש העולה ונרצה לו לכפר עליו\u0003\"\u0004 (ויקרא א, ב-ד), לומר: \u0003בני ישראל סומכין\u0004 על הקרבן, \u0003ואין בנות ישראל סומכות\u0004 כלל, אלו \u0003דברי ר' יהודה. ר' יוסי ור' שמעון אומרים: נשים סומכות רשות,\u0004 שאף שאינן חייבות בדבר, אם רצו לסמוך — מותר להן. ומכאן ניתן להסיק ששיטת ר' יוסי ור' שמעון היא שמצוות שאין הנשים חייבות בהן מכל מקום אם רצו לעשותן — מותר להן.","שנינו במשנה: \u0003אבל מתעסקין בהם\u0004 עם הקטנים \u0003עד שילמדו\u0004 לתקוע בעצמן. \u0003אמר ר' אלעזר: אפילו בשבת\u0004 שחל בה ראש השנה מותר להניח לתינוקות, ואפילו לסייע להם ללמוד לתקוע. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003מתעסקין בהן עד שילמדו,\u0004 ו\u0003אפילו בשבת. ואין מעכבין התינוקות מלתקוע בשבת, ואין צריך לומר ביום טוב.\u0004","על לשון הברייתא תוהים: \u0003הא גופא קשיא\u0004 \u0005[זו עצמה קשה]\u0006 מתוכה; \u0003אמרת\u0004 תחילה \u0003מתעסקין בהן עד שילמדו ואפילו בשבת, אלמא\u0004 \u0005[מכאן]\u0006 כי \u0003לכתחלה אמרינן\u0004 \u0005[אומרים אנו להם]\u0006 \u0003תקעו,\u0004 אף שהמבוגרים אינם תוקעים. \u0003והדר תנא\u0004 \u0005[וחזר ושנה]\u0006 לשון \u0003אין מעכבין,\u0004 משמע: \u0003עכובא\u0004 \u0005[לעכב]\u0006 \u0003הוא\u0004 ש\u0003לא מעכבין, הא\u0004 \u0005[הרי]\u0006 \u0003לכתחלה לא אמרינן\u0004 \u0005[אין אומרים\u0006 להם\u0005]\u0006 \u0003תקעו!\u0004","ומתרצים: \u0003לא קשיא\u0004 \u0005[אינו קשה];\u0006 \u0003כאן\u0004"],["\u0003בקטן שהגיע לחינוך,\u0004 מחנכים אותו לתקוע, שהרי יש צד מצוה בדבר לחנכו לקיום המצווה, \u0003כאן,\u0004 שאין מעכבים אותו אבל מלכתחילה אין מחנכים אותו לכך, מדובר \u0003בקטן שלא הגיע לחינוך.\u0004","\u0003ועוד שנינו במשנה: והמתעסק\u0004 בשופר ועלתה בידו תקיעה \u0003לא יצא\u0004 בה ידי חובתו. ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אם היה זה \u0003תוקע לשיר\u0004 שלא נתכוון למצוה אלא לשם זמר בלבד — \u0003יצא\u0004 ידי חובתו, אף שלא התכוון לצאת ידי חובה, ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[האם נאמר\u0006 שדבר זה \u0005מסייע לו]\u0006 \u0003ל\u0004שיטת \u0003רבא\u0004 ש\u0003אמר רבא: התוקע לשיר\u0004 — \u0003יצא.\u0004 ודוחים: מכאן אין ראיה ברורה; \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003תוקע לשיר\u0004 — \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003מתעסק קרי ליה\u0004 \u0005[קורא לו]\u0006 התנא, שכל שלא נתכוון למצוה קרוי אצלו מתעסק.","\u0003ו\u0004עוד שנינו במשנה: \u0003והשומע מן המתעסק\u0004 — \u0003לא יצא.\u0004 ומכאן נדייק: \u0003אבל השומע מן המשמיע לעצמו\u0004 שלא התכוון להשמיע לאחרים, \u0003מאי\u0004 \u0005[מה]\u0006 יהיה דינו? לפי הדיוק יש לומר כי \u0003יצא. לימא תיהוי תיובתיה\u0004 \u0005[האם לומר\u0006 ש\u0005תהא\u0006 זו \u0005קושיה חמורה]\u0006 על \u0003ר' זירא,\u0004 שכן \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לשמעיה\u0004 \u0005[לשמשו]:\u0006 \u0003איכוון\u0004 \u0005[כוון]\u0006 בלבך להוציאני \u0003ותקע לי\u0004 בשופר, משמע שצריך כוונת משמיע!","ודוחים: \u0003דלמא איידי דתנא רישא\u0004 \u0005[שמא מתוך ששנה בראש\u0006 המשנה\u0005]\u0006 \u0003מתעסק, תנא סיפא נמי\u0004 \u0005[שנה בסופה גם כן]\u0006 \u0003מתעסק,\u0004 אבל אין לדייק מכאן שרק המתעסק פסול ויתכן שגם מי שלא התכוון להוציא אחרים גם כן פסול.","\u0003סדר\u0004 ה\u0003תקיעות\u0004 הוא: \u0003שלש\u0004 תקיעות מורכבות \u0003של שלש שלש\u0004 שהן: תקיעה ותרועה ותקיעה. \u0003שיעור\u0004 זמן \u0003תקיעה\u0004 הוא \u0003כ\u0004שיעורן של \u0003שלש תרועות,\u0004 ו\u0003שיעור תרועה\u0004 הוא \u0003כשלש יבבות,\u0004 כלומר, קולות כלשהם. \u0003תקע\u0004 בתקיעה ה\u0003ראשונה\u0004 כרגיל \u0003ומשך\u0004 בתקיעה ה\u0003שניה\u0004 שלאחר התרועה \u0003כשתים\u0004 כאורך שתי תקיעות — \u0003אין בידו אלא אחת,\u0004","\u0003ואין אנו אומרים שבגלל משך הזמן הכפול תחשב זו בין כתקיעה של סוף מחזור אחד ובין כתקיעה לתחילת מחזור שני. מי שבירך,\u0004 כלומר, התפלל תפילת מוסף \u0003ואחר כך נתמנה\u0004 לו (הזדמן בידו) \u0003שופר\u0004 — אף הוא \u0003תוקע ומריע ותוקע,\u0004 ועושה כן \u0003שלש פעמים.\u0004","\u0003כשם ששליח צבור חייב\u0004 בתפילה \u0003כך כל יחיד ויחיד חייב\u0004 בתפילת ראש השנה. \u0003רבן גמליאל אומר:\u0004 אינו חייב, כי \u0003שליח צבור מוציא את הרבים ידי חובתן.\u0004","על המשנה הקובעת את שיעור זמן התקיעה תוהים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 כי \u0003שיעור תקיעה כתרועה,\u0004 ואילו במשנתנו נאמר ששיעור תקיעה כשלוש תרועות! \u0003אמר אביי: תנא דידן קא חשיב תקיעה דכולהו בבי ותרועות דכולהו בבי\u0004 \u0005[התנא שלנו\u0006 במשנתנו מנה \u0005וחשב את התקיעות של כל השערים,\u0006 המחזורים, \u0005וכל התרועות של כל השערים,\u0006 המחזורים\u0005]\u0006 ושיעור התקיעה (כלומר כל התקיעות) הוא כשיעור התרועות. \u0003תנא ברא\u0004 \u0005[התנא של הברייתא]\u0006 \u0003קא חשיב חד בבא ותו לא\u0004 \u0005[החשיב שער\u0006 מחזור \u0005אחד ולא יותר]\u0006 ושיעור אורך תקיעה אחת הרי הוא כשיעור אורכה של תרועה.","\u0003שיעור תרועה כשלש יבבות.\u0004 ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 \u0003אחרת: שיעור תרועה כשלשה שברים!\u0004","\u0003אמר אביי: בהא\u0004 \u0005[בזה]\u0006 \u0003ודאי פליגי\u0004 \u0005[חלוקים]\u0006 התנאים, שאף שבאנו ליישב את הברייתא הראשונה עם המשנה, הרי ברייתא זו מגלה לנו מחלוקת עקרונית, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"יום תרועה יהיה לכם\"\u0004 (במדבר כט, א), \u0003ומתרגמינן\u0004 \u0005[ומתרגמים אנו]\u0006 פסוק זה: \u0003\"יום יבבא יהא לכון\".\u0004 ומהו לשון \"יבבא\", דבר זה נלמד \u0003וכתיב באימיה\u0004 \u0005[ונאמר על אמו]\u0006 של \u0003סיסרא: \"בעד החלון נשקפה ותיבב אם סיסרא\"\u0004 (שופטים ה, כח), והבעיה היא מה הוא אותו הקול הקרוי יבבה. \u0003מר\u0004 \u0005[חכם זה]\u0006 \u0003סבר\u0004 שיבבה היא \u0003גנוחי גנח\u0004 \u0005[\u0006כקול \u0005גניחה]\u0006 שהוא קול אנחה שבור, ובשופר משמיעים קולות הקרויים שברים. \u0003ומר\u0004 \u0005[וחכם זה]\u0006 \u0003סבר\u0004 שיבבה פירושו \u0003ילולי יליל\u0004 \u0005[\u0006כקול \u0005יללה]\u0006 ויללות הם קולות ילל קצרים מאד וקצובים, ובקול השופר הוא קרוי תרועה.","לגופם של הדברים \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מנין ש\u0004תקיעה של ראש השנה היא \u0003בשופר\u0004 — \u0003תלמוד לומר: \"והעברת שופר תרועה\u0004 בחודש השביעי בעשור לחודש ביום הכיפורים תעבירו שופר בכל ארצכם\" (ויקרא כה, ט),","\u0003אין לי אלא\u0004 שתוקעים שופר \u0003ביובל, בראש השנה מנין\u0004 שתוקעים בשופר? \u0003תלמוד לומר: \"בחדש השביעי\" שאין תלמוד לומר\u0004 בפסוק זה \u0003בחדש השביעי\u0004 שהרי נאמר ביום הכיפורים, \u0003ומה תלמוד לומר\u0004 המילים \"\u0003בחודש השביעי\u0004\" — ללמדנו: \u0003שיהיו כל תרועות של חדש שביעי זה\u0004 — \u0003כזה.\u0004","בפסוק זה נאמר \"שופר תרועה\", משמע שמשמיעים קול תרועה, \u0003ומנין שפשוטה\u0004 כלומר, קול תקיעה \u0003לפניה\u0004 — \u0003תלמוד לומר: \"והעברת שופר תרועה\"\u0004 והעברת שופר משמעה — תקיעה בשופר, בקול פשוט. \u0003ומנין שפשוטה לאחריה\u0004 — \u0003תלמוד לומר \"תעבירו שופר\",\u0004 הרי שוב הזכרת תקיעה לאחר תרועה.","\u0003ואין לי\u0004 שתוקעים תקיעות בדרך זו \u0003אלא ביובל, בראש השנה מנין? תלמוד לומר: \"בחדש השביעי\",\u0004"],["\u0003שאין תלמוד לומר \"בחדש השביעי\",\u0004 שהרי נאמר ביום הכיפורים, \u0003ומה תלמוד לומר \"בחדש השביעי\"\u0004 — \u0003שיהו כל תרועות\u0004 של \u0003החדש השביעי זה כזה.\u0004","\u0003ומנין לשלש\u0004 מחזורי תקיעות \u0003של שלש שלש\u0004 — \u0003תלמוד לומר: \"והעברת שופר תרועה\"\u0004 (ויקרא כה, ט), ונאמר: \u0003\"שבתון זכרון תרועה\"\u0004 (ויקרא כג, כד), ונאמר: \u0003\"יום תרועה יהיה לכם\"\u0004 (במדבר כט, א), הרי שלוש תקיעות אמורות.","\u0003ומנין ליתן את האמור של זה בזה ושל זה בזה,\u0004 שהרי לא כולם נאמרו בראש השנה — \u0003תלמוד לומר: \"שביעי\" \"שביעי\" לגזירה שוה.\u0004","\u0003הא כיצד\u0004 עושים למעשה? תוקעים \u0003שלש\u0004 מחזורי תקיעות \u0003שהן תשע\u0004 תקיעות בודדות. \u0003שיעור תקיעה כ\u0004שיעור ה\u0003תרועה, שיעור תרועה כ\u0004שיעור \u0003שלשה שברים.\u0004 ולאחר שהבאנו את הברייתא אנו באים לעיין בה.","\u0003האי תנא, מעיקרא מייתי לה בהיקישא\u0004 \u0005[תנא זה מתחילה מביא,\u0006 מוכיח את דבריו \u0005 על ידי ההיקש]\u0006 של המילים \"בחודש השביעי\", לומר שכל שנעשה בחודש השביעי יהיה באותו אופן, \u0003והשתא מייתי לה\u0004 \u0005[ועכשיו מביא\u0006 את הדבר\u0005]\u0006 \u0003בגזירה שוה\u0004 של המילים \"שביעי\" \"שביעי\", וכיצד שינה בתוך אותה הברייתא את מהלך ההוכחה? ומסבירים: \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש להבין: \u0003אי לאו\u0004 \u0005[אם לא]\u0006 היתה \u0003גזירה שוה, הוה מייתינא לה בהיקישא\u0004 \u0005[היו מביאים,\u0006 משיגים \u0005דבר זה על ידי ההיקש],\u0006 \u0003השתא דאתיא\u0004 \u0005[עכשיו שבאה]\u0006 \u0003גזירה שוה\u0004 ללמד — אכן \u0003היקישא לא צריך\u0004 \u0005[ההיקש איננו נחוץ].\u0006","ומעירים: \u0003והאי תנא מייתי לה\u0004 \u0005[ותנא זה\u0006 שנביא את דבריו \u0005מביא את זאת,\u0006 מוכיח את הדברים\u0005]\u0006 \u0003בגזירה שוה,\u0004 ממה שנאמר ב\u0003מדבר. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 על הכתוב: \u0003\"ותקעתם תרועה\"\u0004 (במדבר י, ה), ומכאן נלמד כי \u0003תקיעה\u0004 היא קול \u0003בפני עצמה, ותרועה\u0004 היא קול \u0003בפני עצמה. אתה אומר תקיעה בפני עצמה ותרועה בפני עצמה, או אינו אלא תקיעה ותרועה אחת היא,\u0004 ואין אלה אלא מילים נרדפות — \u0003כשהוא אומר: \"ובהקהיל את הקהל תתקעו ולא תריעו\"\u0004 (במדבר י, ז), \u0003הוי אומר: תקיעה\u0004 היא קול \u0003בפני עצמה ותרועה היא קול\u0004 בפני עצמה.","\u0003ומנין ש\u0004נדרש קול תקיעה \u0003פשוטה לפניה,\u0004 לפני התרועה — \u0003תלמוד לומר: \"ותקעתם תרועה\"\u0004 (במדבר י, ה), כלומר: תתקעו — קול פשוט, ואחר כך תרועה. \u0003ומנין שפשוטה לאחריה\u0004 — \u0003תלמוד לומר: \"תרועה יתקעו\"\u0004 (במדבר י, ו), קודם תרועה ולאחר מכן יתקעו.","\u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקא אומר: אינו צריך\u0004 להוכחה זו, כי יש לו הוכחה אחרת: \u0003הרי הוא אומר\u0004 בכתוב זה: \u0003\"ותקעתם תרועה שנית\"\u0004 (במדבר י, ו), \u0003שאין תלמוד לומר \"שנית\",\u0004 שהרי הדבר מובן מעצמו מן ההקשר, \u0003ומה תלמוד לומר \"שנית\"\u0004 — \u0003זה בנה אב,\u0004 כלומר, זה מקור ובסיס לקביעה כללית: \u0003שכל מקום שנאמר \"תרועה\"\u0004 — \u0003תהא תקיעה שניה לה. אין לי אלא במדבר,\u0004 שכך יש לעשות בתקיעות, \u0003בראש השנה מנין? תלמוד לומר: \"תרועה\" \"תרועה\" לגזירה שוה.\u0004","\u0003ושלש תרועות נאמרו בראש השנה: \"שבתון זכרון תרועה\"\u0004 (ויקרא כג, כד), \u0003\"יום תרועה\"\u0004 (במדבר כט, א), \u0003\"והעברת שופר תרועה\"\u0004 (ויקרא כה, ט), \u0003ושתי תקיעות לכל אחת ואחת\u0004 מן התרועות, אחת לפניה ואחת לאחריה.","\u0003מצינו למדין: שלש תרועות ושש תקיעות נאמרו בראש השנה, שתים\u0004 מהן \u0003מדברי תורה, ואחת מדברי סופרים,\u0004 שהיא נלמדת ממדרשי המקראות ואינה מפורשת בכתוב. כיצד? \u0003\"שבתון זכרון תרועה\" \"והעברת שופר תרועה\"\u0004 — הוא \u0003מדברי תורה,\u0004 ומה שנאמר: \u0003\"יום תרועה יהיה לכם\" לתלמודו הוא בא,\u0004 ללמד ענין לעצמו, ולא לענין התקיעות.","\u0003ר' שמואל בר נחמני אמר\u0004 בשם \u0003ר' יונתן:\u0004 תקיעה \u0003אחת\u0004 היא \u0003מדברי תורה, ושתים מדברי סופרים.\u0004 כיצד? \u0003\"והעברת שופר תרועה\"\u0004 הוא \u0003מדברי תורה,\u0004 ומה שנאמר: \u0003\"שבתון זכרון תרועה\"\u0004 ו\u0003\"יום תרועה יהיה לכם\"\u0004 — \u0003לתלמודו הוא בא.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 ש\"יום תרועה\" \u0003לתלמודו הוא בא,\u0004 מה למדים מכאן? ומסבירים: \u0003מיבעי\u0004 \u0005[צריך]\u0006 ללמוד אותו לענין זה: שהתקיעה היא \u0003ביום ולא בלילה,\u0004 ולכן באה ההדגשה \"יום תרועה\".","ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 \u0003ביום ולא בלילה\u0004 שאיננו לומד מפסוק זה, \u0003מנא ליה\u0004 \u0005[מנין לו]\u0006 הלכה זו? ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא לו,\u0006 הוא לומד את הדבר\u0005],\u0006 \u0003מ\u0004מה שנאמר \u0003\"ביום הכפרים\"\u0004 לענין יובל, וכיון שנאמר \"ביום\" — כוונתו ביום ולא בלילה.","ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003מ\u0004המילים \u0003\"ביום הכפרים\" יליף\u0004 \u0005[\u0006הוא \u0005לומד],\u0006 אם כן \u0003נגמור נמי מיניה\u0004 \u0005[שילמד גם כן משם]\u0006 לענין הצורך בתקיעה \u0003פשוטה לפניה ופשוטה לאחריה,\u0004 ולא יצטרך ללימוד זה כלל! ומשיבים: \u0003\"והעברת\" \"תעבירו\" לא משמע להו\u0004 \u0005[אינו נשמע להם]\u0006 כפירוש הענין, שלדעתם אין מילים אלה מתארות את קול השופר, אלא לענין אחר.","ושואלים: \u0003אלא מאי דרשי בהו\u0004 \u0005[מה הם דורשים בהן,\u0006 במילים הללו\u0005]?\u0006 ומשיבים: \u0003\"והעברת\"\u0004 מפרשים הם \u0003כד\u0004 ברי \u0003רב מתנא,\u0004 ש\u0003אמר רב מתנא:\u0004 מה שנאמר \u0003\"והעברת\",\u0004 כוונתו: שבשעת התקיעה צריך להיות השופר כ\u0003דרך העברתו,\u0004 כפי שהוא בראש האיל, ולא הפוך, ו\u0003\"תעבירו\" דקאמר רחמנא\u0004 \u0005[שאמרה התורה]\u0006 בא להוציא מפירוש מוטעה שלולא החזרה הייתי סבור שפירוש \"תעבירו\" הוא \u0003נעבריה\u0004 \u0005[שיעבירנו]\u0006 \u0003ביד\u0004 ולא יתקע, ולכן צריך את שניהם.","ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 שפירש \"תעבירו\" לענין קול התקיעה, מהיכן לומד הוא הלכה זו? ומשיבים: את ההלכה של \u0003רב מתנא\u0004 למדים \u0003מדשני בדיבוריה\u0004 \u0005[ממה ששינה\u0006 הכתוב \u0005בדיבורו]\u0006 ולא אמר \"יתקעו\" אלא \"תעבירו\" אנו מבינים שהוא דרך העברתו,","ואילו \u0003\"תעבירו\" ביד\u0004 — \u0003לא מצית אמרת\u0004 \u0005[אין אתה יכול לומר]\u0006 ולפרש כן, \u0003דגמר\u0004 \u0005[שהוא לומד]\u0006 \u0003\"עברה\" \"עברה\" ממשה; כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"והעברת שופר תרועה\", וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"ויצו משה ויעבירו קול במחנה\"\u0004 (שמות לו, ו), \u0003מה להלן\u0004 במשה, ההעברה היא \u0003בקול\u0004 — \u0003אף כאן בקול.\u0004","ושואלים: \u0003ולהאי תנא דמייתי לה\u0004 \u0005[ולדעת תנא זה שלומד אותה]\u0006 את התקיעה בראש השנה \u0003מ\u0004מה שהיה ב\u0003מדבר\u0004 בזמן אסיפת העדה, \u0003אי\u0004 \u0005[אם\u0006 כן\u0005]\u0006 \u0003מה להלן\u0004 (במדבר היו אלה) \u0003חצוצרות, אף כאן\u0004 בראש השנה חובת התקיעה תהיה ב\u0003חצוצרות?\u0004","\u0003תלמוד לומר: \"תקעו בחדש שופר בכסה ליום חגנו\"\u0004 (תהלים פא, ד), ופירושו: \u0003איזהו חג שהחדש,\u0004 הירח החדש, \u0003מתכסה בו? הוי אומר זה ראש השנה.\u0004 ששאר החגים חלים תמיד ימים אחדים בתוך החודש והירח נראה בהם יפה ורק בראש השנה עדיין אין הירח נראה, \u0003וקאמר רחמנא\u0004 \u0005[ואמרה התורה]:\u0006 \u0003\"תקעו בחודש שופר\",\u0004 הרי שחובת התקיעה מן התורה בשופר ולא בדבר אחר.","בדרך תקיעת השופר \u0003אתקין\u0004 \u0005[התקין]\u0006 \u0003ר' אבהו בקסרי\u0004 שיתקעו באופן זה: ראשית \u0003תקיעה,\u0004 ולאחריה \u0003שלשה שברים,\u0004 כלומר, קולות שבורים ארוכים, ואחריהם \u0003תרועה,\u0004 קול המורכב מקולות קצרים הבאים רצופים זה אחר זה, ולאחר מכן שוב \u0003תקיעה.\u0004 ושואלים: \u0003מה נפשך\u0004 מה שיטתו, מה רצונו בזה? אם לדעתו תרועה (שהיא לכל הדיעות קול הקרוי \"יבבה\") הוא \u0003ילולי יליל\u0004 \u0005[\u0006קול \u0005יללה],\u0006 קולות קצרים רצופים — \u0003לעביד\u0004 \u0005[שיעשה]\u0006 \u0003תקיעה תרועה ותקיעה,\u0004 ואם סבור הוא שקול יבבה הוא \u0003גנוחי גנח\u0004 \u0005[\u0006קול \u0005גניחות]\u0006 ארוכות ושבורות — \u0003לעביד\u0004 \u0005[שיעשה]\u0006 \u0003תקיעה\u0004 ו\u0003שלשה שברים ותקיעה,\u0004 ומדוע תיקן שיעשו גם שברים וגם תרועה?","ומשיבים: \u0003מספקא ליה\u0004 \u0005[מסופק היה לו]\u0006 לר' אבהו \u0003אי גנוחי גנח אי ילולי יליל\u0004 \u0005[אם\u0006 פירושו \u0005גניחה או\u0006 פירושו \u0005יללה]\u0006 וכדי לצאת ידי שניהם צירף את שני סוגי הקולות. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב עוירא:\u0004 כיון שהוא מסופק, וכיון שצריך להשמיעך קול אחד של תרועה \u0003ודלמא ילולי הוה\u0004 \u0005[ושמא\u0006 קול זה, קול \u0005יללה היה]\u0006 \u0003וקא\u0004 \u0005[והרי הוא]\u0006 \u0003מפסיק\u0004 ב\u0003שלשה שברים בין תרועה לתקיעה,\u0004 על ידי תיקון זה של ר' אבהו, ואם כן, הרי לפי השיטה האחרת הוא פסול! ומשיבים: מדובר כאן \u0003דהדר עביד\u0004 \u0005[שחוזר\u0006 אחר כך ו\u0005עושה]\u0006 \u0003תקיעה תרועה ותקיעה\u0004 ועל ידי כך הוא יוצא גם ידי ספק זה. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבינא: ודלמא גנוחי הוה\u0004 \u0005[ושמא\u0006 קול \u0005גניחה,\u0006 אנחה \u0005הוא זה]\u0006 \u0003וקא מפסקא\u0004 \u0005[ומפסקת]\u0006 ה\u0003תרועה בין\u0004 ה\u0003שברים לתקיעה!\u0004 ומשיבים: \u0003דהדר עביד\u0004 \u0005[שחוזר\u0006 אחר כך ו\u0005עושה]\u0006 \u0003תקיעה שברים תקיעה\u0004 כדי לצאת גם ידי ספק זה.","ושואלים: \u0003כיון שהיה עושה בשני האופנים אלא ר' אבהו מאי אתקין\u0004 \u0005[מה התקין],\u0006 כלומר, מה תועלת בתקנתו? שהרי \u0003אי גנוחי גנח\u0004 \u0005[אם גניחה\u0006 היא\u0005]\u0006 — \u0003הא עבדיה\u0004 \u0005[הרי עשה אותה],\u0006 ו\u0003אי ילולי יליל\u0004 \u0005[אם יללה\u0006 היא\u0005]\u0006 — \u0003הא עבדיה\u0004 \u0005[הרי עשה אותה]!\u0006 ומשיבים: \u0003מספקא ליה דלמא גנח ויליל\u0004 \u0005[מסופק לו שמא הוא גניחה ויללה\u0006 יחד\u0005].\u0006","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שהיה מסופק אם היו כאן שני קולות יחד, \u0003ליעבד נמי איפכא\u0004 \u0005[שיעשה גם כן להיפך]:\u0006 \u0003תקיעה תרועה שלשה שברים ותקיעה, דלמא יליל וגנח\u0004 \u0005[שמא\u0006 קול זה היה של \u0005יללה וגניחה]!\u0006 ומשיבים: דבר זה איננו מסתבר, כי \u0003סתמא דמילתא כי מתרע באיניש מילתא\u0004 \u0005[סתמו של דבר כאשר קורה לאדם דבר\u0006 רע\u0005]\u0006 — \u0003ברישא גנח והדר יליל\u0004 \u0005[מתחילה\u0006 הוא \u0005גונח ואחר כך\u0006 הוא \u0005מילל]\u0006 אבל לא להיפך, ולכן הוסיף רק קול מורכב זה.","שנינו במשנה: \u0003תקע בראשונה ומשך בשניה כשתים\u0004 — יצא רק ידי חובת אחת. \u0003אמר ר' יוחנן: שמע\u0004"],["\u0003תשע תקיעות בתשע שעות\u0004 שונות \u0003ביום\u0004 — \u0003יצא\u0004 ידי חובה, כי אין חובה שתהיינה התקיעות סמוכות זו לזו.","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003שמע תשע תקיעות בתשע שעות ביום\u0004 — \u0003יצא.\u0004 שמע את כל התקיעות \u0003מתשעה בני אדם כאחד\u0004 — \u0003לא יצא.\u0004 שמע \u0003תקיעה מזה ו\u0004לאחר מכן \u0003תרועה מזה\u0004 — \u0003יצא,\u0004 שאינו חייב לשמוע את כולן מאיש אחד. \u0003ואפילו\u0004 שמען \u0003בסירוגין,\u0004 פעם מאיש זה ופעם מאחר, \u0003ואפילו\u0004 במשך \u0003כל היום כולו.\u0004","על דברים אלה שואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן משום\u0004 (משמו) של \u0003ר' שמעון בן יהוצדק: בהלל ובמגילה, אם שהה\u0004 והפסיק בלא קריאה שהות זמן \u0003כדי לגמור את כולה\u0004 — \u0003חוזר לראש,\u0004 לפי שצריך לקוראה כולה כאחת, ומדוע אינו אומר כן אף בתקיעת שופר? ומשיבים: \u0003לא קשיא\u0004 \u0005[אין זה קשה];\u0006 \u0003הא\u0004 — \u0003דידיה\u0004 \u0005[זו שלו]\u0006 שלדעתו אין ההפסקה מעכבת, \u0003והא דרביה\u0004 \u0005[וזו של רבו]\u0006 ר' שמעון בן יהוצדק, הסבור שאין להפסיק.","ושואלים: \u0003ודידיה\u0004 \u0005[ומשלו]\u0006 \u0003לא,\u0004 כלומר, האם לא היתה זו גם דעתו של ר' יוחנן עצמו? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' אבהו הוה שקיל ואזיל בתריה\u0004 \u0005[היה נוטל והולך אחרי]\u0006 \u0003ר' יוחנן והוה קרי\u0004 \u0005[והיה קורא]\u0006 באותה שעה \u0003קריאת שמע\u0004 תוך כדי הילוך, \u0003כי מטא\u0004 \u0005[כאשר הגיע]\u0006 \u0003למבואות מטונפות\u0004 בצואה שבהם אסור לקרוא, \u0003אישתיק\u0004 \u0005[השתתק]\u0006 ולא קרא, \u0003בתר דחליף\u0004 \u0005[לאחר שחלף\u0006 ויצא משם\u0005]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אבהו לר' יוחנן: \u0003מהו\u0004 הדין, האם מותר לי \u0003לגמור\u0004 קריאת שמע ממקום שהפסקתי? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אם שהית\u0004 בתוך המבוא שהות שדי בה \u0003כדי לגמור את כולה\u0004 — \u0003חזור לראש.\u0004 והרי מכאן הוכחה שאף ר' יוחנן עצמו סבור שאם עשה הפסק גדול צריך לחזור לראש!","ומשיבים: זו אינה הוכחה גמורה, \u0003הכי קאמר ליה\u0004 \u0005[כך אמר לו]:\u0006 \u0003לדידי\u0004 \u0005[לשיטתי]\u0006 — \u0003לא סבירא לי\u0004 \u0005[אין אני סבור\u0006 כן\u0005]\u0006 שההפסקה מעכבת, אולם \u0003לדידך דסבירא לך\u0004 \u0005[לשיטתך,\u0006 לדעתך \u0005שאתה סבור\u0006 כן\u0005]\u0006 שהפסקה באמצע מעכבת, הרי הכלל הוא: \u0003אם שהית כדי לגמור את כולה\u0004 — \u0003חזור לראש.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003תקיעות\u0004 כגון אלה שתוקעים בתענית — \u0003אין מעכבות זו את זו,\u0004 ואם לא עשה כולן, אלה שעשה — עשה. \u0003ברכות\u0004 שבתוך התפילה \u0003אין מעכבות זו את זו\u0004 ויוצא בכל אחת שאמר לעצמה, אולם \u0003תקיעות וברכות של ראש השנה ושל יום הכפורים מעכבות\u0004 האחת את האחרות\u0003.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 מעכבות הן? \u0003אמר רבה: אמר הקדוש ברוך הוא, אמרו לפני בראש השנה מלכיות זכרונות ושופרות, מלכיות\u0004 — \u0003כדי שתמליכוני עליכם, זכרונות\u0004 — \u0003כדי שיבא לפני זכרוניכם לטובה, ובמה\u0004 — \u0003בשופר.\u0004 וכיון שברכות אלה הן חטיבה משמעותית אחת, אם לא אמרן כאחת — לא יצא ידי חובתו.","שנינו במשנה ש\u0003מי שבירך ואחר כך נתמנה\u0004 \u0005[נזדמן]\u0006 \u0003לו שופר\u0004 — \u0003תוקע ומריע ותוקע.\u0004 ומדייקים: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003לא הוה ליה\u0004 \u0005[היה לו]\u0006 \u0003שופר מעיקרא\u0004 \u0005[מתחילה],\u0006 \u0003הא הוה ליה\u0004 \u0005[הרי\u0006 אם \u0005היה לו]\u0006 \u0003שופר מעיקרא\u0004 \u0005[מתחילה],\u0006 \u0003כי שמע להו\u0004 \u0005[כאשר הוא שומע אותן]\u0006 את התקיעות — על \u0003סדר\u0004 ה\u0003ברכות שמע להו\u0004 \u0005[שומע\u0006 הוא \u0005אותן],\u0006 שלכתחילה יש לתקוע תקיעות בין הברכות.","מסופר: \u0003רב פפא בר שמואל קם לצלויי\u0004 \u0005[עמד להתפלל]\u0006 תפילת ראש השנה, \u0003אמר ליה לשמעיה\u0004 \u0005[לו לשמשו]:\u0006 \u0003כי נהירנא לך\u0004 \u0005[כאשר ארמוז לך]\u0006 \u0003תקע לי.\u0004 שארמוז לך מתי אני מסיים כל אחת מן הברכות, ואז תתקע. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: לא אמרו\u0004 דבר זה שתוקעין אחר כל ברכה וברכה \u0003אלא בחבר עיר,\u0004 כלומר, כאשר כל העיר (או הציבור) מתפללת יחד, אבל לא בתפילות היחידים.","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003כשהוא שומען,\u0004 את התקיעות — \u0003שומען על הסדר\u0004 — תקיעה תרועה ותקיעה, \u0003ועל סדר\u0004 ה\u0003ברכות. במה דברים אמורים\u0004 — \u0003בחבר עיר, אבל שלא בחבר עיר\u0004 — \u0003שומען על הסדר ושלא על סדר ברכות. ויחיד שלא תקע\u0004 — \u0003חבירו תוקע לו\u0004 ויוצא ידי חובה בשמיעה בלבד, \u0003ויחיד שלא בירך\u0004 — \u0003אין חבירו מברך עליו.\u0004","\u0003ומצוה בתוקעין יותר מן המברכין. כיצד\u0004 נוהגים לפי כלל זה? היו \u0003שתי עיירות, באחת\u0004 ברור ש\u0003תוקעין,\u0004 שיש שם אנשים הבקיאים באומנות התקיעה, \u0003ובאחת מברכין\u0004 — \u0003הולכין למקום שתוקעין, ואין הולכין למקום שמברכין.\u0004","על הלכה זו תוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 — \u0003הא דאורייתא הא דרבנן\u0004 \u0005[זו\u0006 התקיעה \u0005היא מן התורה, זו\u0006 הברכה \u0005מדברי חכמים],\u0006 וברור שדברי תורה חשובים יותר! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003דאף על גב דהא\u0004 \u0005[שאף על פי שזו]\u0006 הברכה היא \u0003ודאי והא\u0004 \u0005[וזו]\u0006 התקיעה, היא \u0003ספק,\u0004 מכל מקום, ספק תקיעה עדיף על ודאי ברכה.","שנינו במשנה: \u0003כשם ששליח צבור חייב, כך כל יחיד ויחיד\u0004 חייב, ורבן גמליאל אומר ששליח הצבור מוציא את הרבים ידי חובה. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמרו לו לרבן גמליאל: לדבריך, למה\u0004 ה\u0003צבור מתפללין,\u0004 והלא שליח הציבור מוציאם ידי חובה! \u0003אמר להם: כדי להסדיר שליח\u0004 ה\u0003צבור תפלתו,\u0004 כלומר, לתת לו זמן כדי להתכונן ולהסדיר את תפילתו כראוי,","\u0003אמר להם רבן גמליאל: לדבריכם\u0004 ששליח הצבור איננו מוציא את הכל, \u0003למה שליח צבור יורד לפני התיבה? אמרו לו: כדי להוציא את\u0004 זה \u0003שאינו בקי\u0004 להתפלל. \u0003אמר להם: כשם שמוציא את\u0004 זה \u0003שאינו בקי\u0004 — \u0003כך מוציא את הבקי.\u0004","עד כאן הברייתא, ועליה \u0003אמר רבה בר בר חנה אמר ר' יוחנן: מודים חכמים לרבן גמליאל,\u0004 שקיבלו לבסוף את דעתו. \u0003ורב אמר: עדיין היא מחלוקת\u0004 ולא הוכרעה בשעתה, אלא נשארו כל החולקים בדעותיהם. מסופר: \u0003שמעה\u0004 \u0005[שמע את\u0006 הענין הזה\u0005]\u0006 \u0003ר' חייא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבה בר נחמני, אזל, אמרה לשמעתא קמיה\u0004 \u0005[הלך, אמר את השמועה,\u0006 ההלכה הזו, \u0005לפני]\u0006 \u0003ר' דימי בר חיננא. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי אמר\u0004 \u0005[כך אמר]\u0006 \u0003רב: עדיין היא\u0004 ב\u0003מחלוקת. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003רבה בר בר חנה נמי הכי קאמר\u0004 \u0005[גם כן כך אמר],\u0006 וסיפר רבה בר בר חנה: \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר ר' יוחנן להא שמעתא\u0004 \u0005[את השמועה,\u0006 ההלכה \u0005הזו]\u0006 שהכל מודים לרבן גמליאל \u0003אפליג עליה\u0004 \u0005[נחלק עליו]\u0006 \u0003ריש לקיש ואמר: עדיין היא מחלוקת.\u0004","לגופו של דבר שואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' חנה ציפוראה\u0004 \u0005[מציפורי]\u0006 \u0003אמר ר' יוחנן: הלכתא\u0004 \u0005[ההלכה]\u0006 \u0003כ\u0004שיטת \u0003רבן גמליאל,\u0004 וכיון שפסק \u0003הלכתא\u0004 \u0005[הלכה]\u0006 \u0003מכלל דפליגי\u0004 \u0005[מכאן שהם חלוקים]\u0006 בדבר, ואם כן אינו סבור שהודו חכמים לרבן גמליאל!"],["\u0003כי סליק\u0004 \u0005[כאשר עלה]\u0006 \u0003ר' אבא מימי\u0004 \u0005[מ\u0006הפלגתו \u0005בימים]\u0006 ובא לבית המדרש \u0003פירשה\u0004 לסתירה זו באופן הבא: \u0003מודים חכמים לרבן גמליאל בברכות של ראש השנה ושל יום הכפורים,\u0004 שהסכימו ששליח הציבור מוציא את הכל ידי חובתם, \u0003והלכה\u0004 שפסק ר' יוחנן \u0003מכלל דפליגי\u0004 \u0005[שמשמע\u0006 מכאן \u0005שחלוקים]\u0006 היא \u0003בברכות\u0004 של \u0003כל השנה.\u0004","על תירוץ זה תוהים: \u0003איני\u0004 \u0005[וכי כן הוא]?!\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' חנה ציפוראה אמר ר' יוחנן: הלכה כרבן גמליאל בברכות של ראש השנה ושל יום הכפורים,\u0004 משמע שלדעתו אף בזה היתה מחלוקת!","\u0003אלא אמר רב נחמן בר יצחק,\u0004 עלינו לחזור מסברה זו, ולומר: \u0003מאן\u0004 \u0005[מי הם]\u0006 אלה החכמים ש\u0003מודים\u0004 לרבן גמליאל — \u0003ר' מאיר\u0004 הוא, \u0003ו\u0004ה\u0003הלכה\u0004 ש\u0003מכלל\u0004 הדברים אתה למד \u0003דפליגי\u0004 \u0005[שחולקים]\u0006 — זו היא שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 שנחלקו על ר' מאיר.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ברכות של ראש השנה ושל יום הכפורים\u0004 — \u0003שליח ציבור מוציא\u0004 את \u0003הרבים ידי חובתן,\u0004 אלו \u0003דברי ר' מאיר. וחכמים אומרים: כשם ששליח צבור חייב\u0004 — \u0003כך כל יחיד ויחיד חייב.\u0004 ואם כן יש מחלוקת תנאים בשאלה אם לקבל מקצת מדברי רבן גמליאל.","ושואלים: \u0003מאי שנא הני\u0004 \u0005[במה שונות אלה]\u0006 ברכות ראש השנה ויום הכיפורים, שבהם מודים לרבן גמליאל, שלא כבשאר הברכות? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהוא \u0003משום דנפישי קראי\u0004 \u0005[שמרובים הפסוקים]\u0006 שיש לומר בכל אותן הברכות, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב חננאל אמר רב: כיון שאמר\u0004 — \u0003\"ובתורתך כתוב לאמר\",\u0004 כלומר, שכך כתוב בתורה \u0003שוב אינו צריך\u0004 לפרש את הפסוקים עצמם, הרי שאמירת פסוקים אלה אינה מעכבת! \u0003אלא\u0004 — הטעם הוא \u0003משום דאוושי\u0004 \u0005[שמרובות]\u0006 ה\u0003ברכות\u0004 עצמן, וכיון שנוסח הברכה ארוך, אין הכל יכולים ללמוד אותו בעל פה.","\u0003גופא\u0004 \u0005[לגופו\u0006 של ענין\u0005]\u0006 שהזכרנו, \u0003אמר רב חננאל אמר רב: כיון שאמר \"ובתורתך כתוב לאמר\"\u0004 — \u0003שוב אינו צריך.\u0004 ומסבירים \u0003סבור מינה\u0004 \u0005[סברו\u0006 התלמידים לומר \u0005מכאן]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 דווקא \u0003ביחיד, אבל בצבור לא. אתמר\u0004 \u0005[נאמר],\u0006 ש\u0003אמר ר' יהושע בן לוי: אחד יחיד אחד צבור, כיון שאמר \"ובתורתך כתוב לאמר\"\u0004 — \u0003שוב אינו צריך,\u0004 ויצא ידי חובתו. \u0003אמר ר' אלעזר: לעולם יסדיר אדם תפלתו\u0004 ויתכונן לכך בפני עצמו, \u0003ואחר כך יתפלל. אמר ר' אבא: מסתברא מילתיה\u0004 \u0005[מסתברים דבריו]\u0006 של \u0003ר' אלעזר בברכות של ראש השנה ושל יום הכפורים ושל פרקים\u0004 (תפילות שמתפללים מזמן לזמן) ולא בכל יום, \u0003אבל\u0004 ברכות של \u0003כל השנה\u0004 — \u0003לא.\u0004","","ושואלים: \u0003איני\u0004 \u0005[וכי כך הוא]?!\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב יהודה\u0004 היה \u0003מסדר\u0004 בפני עצמו \u0003צלותיה ומצלי\u0004 \u0005[תפילתו, ו\u0006אחר כך היה \u0005מתפלל]\u0006 אפילו תפילה של יום חול! ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003רב יהודה, כיון דמתלתין יומין לתלתין יומין הוה מצלי\u0004 \u0005[שמשלושים יום לשלושים יום היה מתפלל]\u0006 ולא התפלל במשך כל החודש מפני שהיה עסוק בתורתו, ואם כן בשבילו גם תפילות רגילות \u0003כפרקים\u0004 רחוקים \u0003דמי\u0004 \u0005[נחשבות].\u0006","\u0003אמר רב אחא בר עוירא אמר ר' שמעון חסידא: פוטר היה רבן גמליאל אפילו עם\u0004 (הקהל) \u0003ש\u0004נמצא \u0003בשדות\u0004 ולא בבית הכנסת, שיוצאים ידי חובתם בתפילת שליח הציבור. ותוהים: אפילו אלה?! \u0003ולא מיבעיא\u0004 \u0005[הוצרכה]\u0006 לומר על \u0003הני דקיימי הכא\u0004 \u0005[אלה שנמצאים כאן]\u0006 בתוך העיר?!","הלא \u0003אדרבה\u0004 (היפך הדברים) מסתבר: \u0003הני\u0004 — \u0003אניסי\u0004 \u0005[אלה\u0006 שבשדות \u0005הם אנוסים]\u0006 שאינם יכולים לצאת ידי חובתם אלא על ידי שליח הציבור, אבל \u0003הני לא אניסי\u0004 \u0005[אלה\u0006 שבעיר ולא באו \u0005אינם אנוסים]\u0006 והיו יכולים לבוא לבית הכנסת ולהתפלל בעצמם,","\u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003אבא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב בנימין בר חייא\u0004 ברייתא: \u0003עם\u0004 (הקהל) \u0003ש\u0004בבית הכנסת, אם עומדים \u0003אחורי\u0004 ה\u0003כהנים\u0004 בשעה שמברכים, ולא פנים אל פנים כנגדם — \u0003אינן בכלל\u0004 ה\u0003ברכה,\u0004 שהרי היו יכולים לטרוח קצת ולבוא אל מול הכהנים. ומצד אחר יודעים אנו שברכת הכהנים חלה אף על הרחוקים.","\u0003אלא,\u0004 יש לומר בנוסח אחר: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל מסר את השמועה באופן זה: \u0003אמר ר' יעקב בר אידי אמר ר' שמעון חסידא: לא פטר רבן גמליאל אלא עם שבשדות, מאי טעמא\u0004 \u0005[\u0006ו\u0005מה טעם]\u0006 הדבר — \u0003משום דאניסי\u0004 \u0005[משום ש\u0006הם \u0005אנוסים]\u0006 \u0003במלאכה\u0004 ואינם יכולים להתכונן לתפילה, \u0003אבל\u0004 אלה ש\u0003בעיר\u0004 — \u0003לא,\u0004 שמאחר ואינם אנוסים, היו הם יכולים להסדיר את תפילתם בעצמם.",""]]};
